INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC3-2-u3-C1','sci',3,2,'u3',1,'여러 가지 물체로 소리 내기 — 풍선·나무판은 두드려서, 병은 입구를 불어서, 비닐봉지는 비벼서, 페트병은 연필로 문지르거나 쌀을 넣고 흔들어서 소리를 냄 · 하나의 물체로도 방법을 바꾸면 여러 가지 소리를 낼 수 있음',ARRAY['[4과07-01] 여러 가지 물체를 이용하여 소리를 내 보고, 소리가 나는 물체는 떨림이 있음을 설명할 수 있다(차시 머리 주석 기준 · 문구 W7 확인)']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC3-2-u3-C2','sci',3,2,'u3',1,'소리 듣고 짐작하기와 놀이 약속 — 소리만 듣고도 어떤 물체로 어떻게 냈는지 짐작할 수 있음 · 쌀 넣은 페트병 흔들기는 빗소리, 쟁반 위 쌀 흔들기는 파도 소리, 수건 펄럭이기는 날갯짓 소리와 닮음 · 유리·칼·가위처럼 다칠 수 있는 물체는 쓰지 않고 소리를 너무 크게 내지 않음 · 많이 맞히기보다 소리를 내고 듣는 과정이 중요하고 조용히 귀 기울여 들음',ARRAY['[4과07-01] 여러 가지 물체를 이용하여 소리를 내 보고, 소리가 나는 물체는 떨림이 있음을 설명할 수 있다(차시 머리 주석 기준 · 문구 W7 확인)']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC3-2-u3-C3','sci',3,2,'u3',2,'소리가 나는 물체의 떨림 — 치기 전 소리굽쇠는 딱딱하고 차갑지만, 친 소리굽쇠에 손을 대면 떨림이 느껴지고 매달린 탁구공이 튀어 오르며 물 표면에 대면 물이 튀어 오름 · 소리가 나는 물체는 떨림이 있음',ARRAY['[4과07-01] 여러 가지 물체를 이용하여 소리를 내 보고, 소리가 나는 물체는 떨림이 있음을 설명할 수 있다(차시 머리 주석 기준 · 문구 W7 확인)']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC3-2-u3-C4','sci',3,2,'u3',2,'여러 감각으로 관찰하기와 떨림 멈추기 — 소리는 귀뿐 아니라 눈(튀어 오르는 탁구공·물)과 손(떨림)으로도 관찰함 · 기타 줄, 스피커 막, 말하는 사람의 목도 소리가 날 때 떨림 · 떨림을 멈추면 소리도 멈춤 · 고무망치로 소리굽쇠를 너무 세게 치지 않음',ARRAY['[4과07-01] 여러 가지 물체를 이용하여 소리를 내 보고, 소리가 나는 물체는 떨림이 있음을 설명할 수 있다(차시 머리 주석 기준 · 문구 W7 확인)']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC3-2-u3-C5','sci',3,2,'u3',3,'소리의 세기 — 소리의 크고 작은 정도를 소리의 세기라고 함 · 멀리 있는 친구를 부를 때·발표할 때·응원할 때는 큰 소리, 귓속말·자장가는 작은 소리 · 디지털 탐구 도구로 크고 작은 정도를 측정할 수 있음',ARRAY['[4과07-02] 큰 소리와 작은 소리, 높은 소리와 낮은 소리를 구분하고, 세기와 높낮이가 다른 소리를 낼 수 있다(차시 머리 주석 기준 · 문구 W7 확인)']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC3-2-u3-C6','sci',3,2,'u3',3,'떨림의 크기와 소리의 세기 — 작은북을 세게 치면 북면이 크게 떨리며 퐁퐁이가 높게 튀고 큰 소리, 약하게 치면 작게 떨리며 낮게 튀고 작은 소리가 남 · 심벌즈도 같음 · 작은 소리도 작게 떨림 · 너무 큰 소리는 귀를 다치게 할 수 있어 지나치게 세게 치지 않고 북 아닌 곳은 치지 않음',ARRAY['[4과07-02] 큰 소리와 작은 소리, 높은 소리와 낮은 소리를 구분하고, 세기와 높낮이가 다른 소리를 낼 수 있다(차시 머리 주석 기준 · 문구 W7 확인)']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC3-2-u3-C7','sci',3,2,'u3',4,'소리의 높낮이 — 소리의 높고 낮은 정도를 소리의 높낮이라고 함 · 짧은 음판·짧은 관·짧게 잡은 고무줄은 높은 소리, 긴 것은 낮은 소리 · 피아노 조율사는 줄마다 알맞은 높낮이가 나도록 맞춤',ARRAY['[4과07-02] 큰 소리와 작은 소리, 높은 소리와 낮은 소리를 구분하고, 세기와 높낮이가 다른 소리를 낼 수 있다(차시 머리 주석 기준 · 문구 W7 확인)']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC3-2-u3-C8','sci',3,2,'u3',4,'물체의 길이와 소리의 높낮이 — 소리를 내는 물체가 짧으면 높은 소리, 길면 낮은 소리가 남 · 간이 악기에서 자 가운데를 누르고 튕기면 튕기는 고무줄이 짧아 높은 소리, 윗부분을 누르면 길어 낮은 소리 · 높낮이를 견줄 때는 같은 세기로 튕김',ARRAY['[4과07-02] 큰 소리와 작은 소리, 높은 소리와 낮은 소리를 구분하고, 세기와 높낮이가 다른 소리를 낼 수 있다(차시 머리 주석 기준 · 문구 W7 확인)']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC3-2-u3-C9','sci',3,2,'u3',4,'세기와 높낮이 구별 — 세기는 크고 작은 정도(떨림의 크기), 높낮이는 높고 낮은 정도(물체의 길이) · 같은 음판을 세게 치면 높낮이는 같고 세기만 커짐 · 큰 소리가 곧 높은 소리는 아님',ARRAY['[4과07-02] 큰 소리와 작은 소리, 높은 소리와 낮은 소리를 구분하고, 세기와 높낮이가 다른 소리를 낼 수 있다(차시 머리 주석 기준 · 문구 W7 확인)']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC3-2-u3-C10','sci',3,2,'u3',5,'여러 가지 물질을 통한 소리 전달 관찰 — 책상에 귀를 대면 두드리는 소리가, 물속 방수 스피커 소리는 관으로, 친구 목소리는 실 전화기로 들림 · 책상·물로 들을 때는 반대쪽 귀를 손으로 막음 · 떨어져 있어도 소리를 듣는 것은 물질을 통해 전달되기 때문',ARRAY['[4과07-03] 여러 가지 물질을 통하여 소리가 전달되는 것을 관찰하고, 소음을 줄이는 방법을 찾아 일상생활에서 실천할 수 있다(차시 머리 주석 기준 · 문구 W7 확인)']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC3-2-u3-C11','sci',3,2,'u3',5,'고체·액체·기체와 소리 전달 — 책상·실은 고체, 물은 액체, 공기는 기체 · 소리는 고체, 액체, 기체 상태의 여러 가지 물질을 통해 전달되고 우리가 듣는 대부분의 소리는 공기를 통해 전달됨 · 공기가 없는 우주에서는 전달할 물질이 없어 목소리를 들을 수 없음',ARRAY['[4과07-03] 여러 가지 물질을 통하여 소리가 전달되는 것을 관찰하고, 소음을 줄이는 방법을 찾아 일상생활에서 실천할 수 있다(차시 머리 주석 기준 · 문구 W7 확인)']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC3-2-u3-C12','sci',3,2,'u3',6,'소음의 뜻 — 사람에게 불쾌감이나 고통을 주는 소리를 소음이라고 함 · 소리 자체는 소중함 · 같은 소리도 누군가에게는 좋은 소리, 다른 사람에게는 소음일 수 있음',ARRAY['[4과07-03] 여러 가지 물질을 통하여 소리가 전달되는 것을 관찰하고, 소음을 줄이는 방법을 찾아 일상생활에서 실천할 수 있다(차시 머리 주석 기준 · 문구 W7 확인)']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC3-2-u3-C13','sci',3,2,'u3',6,'소음을 줄이는 두 가지 방법 — 스피커·텔레비전 소리를 줄이는 것처럼 소리의 세기를 줄이는 방법 · 바닥 매트, 도로 방음벽, 창틀 이중창, 교실 커튼, 가구 밑 카펫처럼 소리가 잘 전달되지 않게 하는 방법 · 같은 소음도 줄이는 방법이 여러 가지',ARRAY['[4과07-03] 여러 가지 물질을 통하여 소리가 전달되는 것을 관찰하고, 소음을 줄이는 방법을 찾아 일상생활에서 실천할 수 있다(차시 머리 주석 기준 · 문구 W7 확인)']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC3-2-u3-C14','sci',3,2,'u3',7,'층간 소음과 실천 방법 고르기 — 텔레비전의 큰 소리, 늦은 시각 세탁기 소리, 집 안 발걸음이 이웃에게 소음이 됨 · 소리를 작게 하기, 세탁기 밑 고무 받침대, 슬리퍼·양말·실내화처럼 우리가 실천할 수 있는 방법을 고름 · 내 집의 큰 소리도 이웃에게는 소음',ARRAY['[4과07-03] 여러 가지 물질을 통하여 소리가 전달되는 것을 관찰하고, 소음을 줄이는 방법을 찾아 일상생활에서 실천할 수 있다(차시 머리 주석 기준 · 문구 W7 확인)']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC3-2-u3-C15','sci',3,2,'u3',7,'실천·기록·소개와 공동체 태도 — 정한 방법을 일주일 동안 실천하며 실천표에 매일 기록함 · 그림·동영상 같은 소개 자료에 잘한 점과 보완할 점을 담음 · 다른 모둠을 흉보지 않고 함께 고침 · 공동체의 소음 문제는 모두 함께 노력해야 줄어듦',ARRAY['[4과07-03] 여러 가지 물질을 통하여 소리가 전달되는 것을 관찰하고, 소음을 줄이는 방법을 찾아 일상생활에서 실천할 수 있다(차시 머리 주석 기준 · 문구 W7 확인)']::text[],15) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC3-2-u3-C16','sci',3,2,'u3',8,'음향 카메라 — 귀로 듣는 소리를 눈으로 볼 수 있게 해 주는 기기 · 여러 개의 마이크가 달려 있고 화면 속에 소리가 나는 곳을 색깔로 나타냄 · 소리의 세기나 높낮이에 따라 색깔이 달라짐 · 소리를 키우거나 없애는 기기가 아님',ARRAY['[4과07-02] 큰 소리와 작은 소리, 높은 소리와 낮은 소리를 구분하고, 세기와 높낮이가 다른 소리를 낼 수 있다(차시 머리 주석 기준 · 문구 W7 확인)']::text[],16) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC3-2-u3-C17','sci',3,2,'u3',8,'인공지능 음향 카메라의 쓰임 — 인공지능은 사람의 생각하는 능력 등을 컴퓨터 프로그램이 대신하게 만든 기술 · 인공지능 음향 카메라는 섞인 소리 속에서도 소리마다 세기와 높낮이를 구별해 자동차·기계의 고장 난 곳을 빠르게 찾음 · 무인 비행기에 달아 재난 때 조난자의 위치를 찾는 데 쓸 수 있을 것',ARRAY['[4과07-02] 큰 소리와 작은 소리, 높은 소리와 낮은 소리를 구분하고, 세기와 높낮이가 다른 소리를 낼 수 있다(차시 머리 주석 기준 · 문구 W7 확인)']::text[],17) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u3-X01','sci',3,'u3',ARRAY['SC3-2-u3-C1']::text[],'한 물체는 한 가지 소리만 낸다고 여긴다','방법을 바꾸면 다른 소리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u3-X02','sci',3,'u3',ARRAY['SC3-2-u3-C1']::text[],'소리를 낸 방법(두드리기·불기·비비기·문지르기·흔들기)을 잘못 가르거나 물체와 방법을 잘못 잇는다','두드려요 · 불어요 · 비벼요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u3-X03','sci',3,'u3',ARRAY['SC3-2-u3-C2']::text[],'유리·칼·가위처럼 다칠 수 있는 물체를 쓰거나 소리를 너무 크게 내도 된다고 여긴다','다치지 않게, 너무 크지 않게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u3-X04','sci',3,'u3',ARRAY['SC3-2-u3-C2']::text[],'놀이의 목적을 많이 맞히기로 여기거나 듣는 태도를 잘못 안다(떠들기, 다 듣기 전에 외치기 등)','과정이 중요해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u3-X05','sci',3,'u3',ARRAY['SC3-2-u3-C2']::text[],'비슷한 소리와 그 소리를 내는 방법을 잘못 잇는다','빗소리 · 파도 · 날갯짓') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u3-X06','sci',3,'u3',ARRAY['SC3-2-u3-C3']::text[],'소리가 나는 물체에 떨림이 없다고 여기거나, 소리가 나지 않을 때도 떨린다고 여긴다','소리가 날 때 떨려요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u3-X07','sci',3,'u3',ARRAY['SC3-2-u3-C3']::text[],'친 소리굽쇠를 손·탁구공·물에 대 본 결과를 잘못 안다','손 · 탁구공 · 물') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u3-X08','sci',3,'u3',ARRAY['SC3-2-u3-C4']::text[],'소리는 귀로만 관찰할 수 있다고 여기거나 눈으로 본 것과 손으로 느낀 것을 뒤바꾼다','귀 · 눈 · 손') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u3-X09','sci',3,'u3',ARRAY['SC3-2-u3-C4']::text[],'떨림을 멈추어도 소리가 계속 난다고 여긴다','떨림을 멈추면 소리도 멈춰요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u3-X10','sci',3,'u3',ARRAY['SC3-2-u3-C4']::text[],'소리가 날 때 떨리는 부분(기타 줄·스피커 막·목)을 잘못 안다','줄 · 막 · 목') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u3-X11','sci',3,'u3',ARRAY['SC3-2-u3-C5']::text[],'소리의 세기의 뜻을 잘못 안다(떨림, 빠르기, 높고 낮은 정도 등으로)','크고 작은 정도') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u3-X12','sci',3,'u3',ARRAY['SC3-2-u3-C5']::text[],'상황에 알맞은 큰 소리와 작은 소리를 잘못 가른다','부를 때 · 귓속말') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u3-X13','sci',3,'u3',ARRAY['SC3-2-u3-C6']::text[],'세게 치면 작게 떨린다고 여기는 등 떨림의 크기와 소리의 세기를 거꾸로 잇는다','크게 떨리면 큰 소리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u3-X14','sci',3,'u3',ARRAY['SC3-2-u3-C6']::text[],'작은 소리가 나는 물체는 떨리지 않는다고 여긴다','작은 소리도 작게 떨려요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u3-X15','sci',3,'u3',ARRAY['SC3-2-u3-C6']::text[],'퐁퐁이가 튀어 오른 높이를 거꾸로 읽는다','높게 튀면 세게 친 것') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u3-X16','sci',3,'u3',ARRAY['SC3-2-u3-C6']::text[],'큰 소리 실험의 안전 약속을 지키지 않는다(지나치게 큰 소리, 북 아닌 곳 치기 등)','귀를 지켜요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u3-X17','sci',3,'u3',ARRAY['SC3-2-u3-C7']::text[],'소리의 높낮이의 뜻을 잘못 안다(크고 작은 정도, 떨림 등으로)','높고 낮은 정도') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u3-X18','sci',3,'u3',ARRAY['SC3-2-u3-C7']::text[],'높은 소리와 낮은 소리를 잘못 가른다','짧은 쪽 · 긴 쪽') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u3-X19','sci',3,'u3',ARRAY['SC3-2-u3-C8']::text[],'소리를 내는 물체가 길수록 높은 소리가 난다고 여긴다','짧으면 높은 소리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u3-X20','sci',3,'u3',ARRAY['SC3-2-u3-C8']::text[],'높낮이를 견줄 때 튕기는 세기를 다르게 하는 등 간이 악기 실험 방법을 잘못 안다','같은 세기로 튕겨요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u3-X21','sci',3,'u3',ARRAY['SC3-2-u3-C9']::text[],'같은 음판·같은 물체를 세게 치면 소리가 높아진다고 여긴다','세기만 커져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u3-X22','sci',3,'u3',ARRAY['SC3-2-u3-C9']::text[],'소리의 세기와 높낮이를 같은 것으로 여기거나 무엇이 달라졌는지 뒤바꾼다','세기와 높낮이는 달라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u3-X23','sci',3,'u3',ARRAY['SC3-2-u3-C10','SC3-2-u3-C11']::text[],'소리는 공기(기체)를 통해서만 전달된다고 여긴다','고체 · 액체도 전달해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u3-X24','sci',3,'u3',ARRAY['SC3-2-u3-C10']::text[],'책상·물로 소리를 듣는 실험 방법을 잘못 안다(반대쪽 귀를 막지 않기, 귀를 떼기 등)','반대쪽 귀를 막아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u3-X25','sci',3,'u3',ARRAY['SC3-2-u3-C11']::text[],'소리를 전달한 물질의 상태(고체·액체·기체)를 잘못 가른다','실은 고체, 물은 액체') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u3-X26','sci',3,'u3',ARRAY['SC3-2-u3-C11']::text[],'우주에서 소리가 들리지 않는 까닭을 잘못 알거나 물질 없이도 소리가 전달된다고 여긴다','전달할 물질이 없어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u3-X27','sci',3,'u3',ARRAY['SC3-2-u3-C12']::text[],'소음의 뜻을 잘못 안다(큰 소리는 모두 소음, 떨림·높낮이 등)','불쾌감이나 고통을 주는 소리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u3-X28','sci',3,'u3',ARRAY['SC3-2-u3-C12']::text[],'소리는 모두 나쁘다거나 없애야 한다고 여긴다','소리는 소중해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u3-X29','sci',3,'u3',ARRAY['SC3-2-u3-C12']::text[],'같은 소리는 누구에게나 똑같이 소음이거나 아니라고 여긴다','사람마다 달라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u3-X30','sci',3,'u3',ARRAY['SC3-2-u3-C13']::text[],'소음을 줄이는 방법이 아닌 것을 고른다(더 크게 틀기, 창문 활짝 열기 등)','줄이는 방법인가요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u3-X31','sci',3,'u3',ARRAY['SC3-2-u3-C13']::text[],'세기를 줄이는 방법과 소리가 잘 전달되지 않게 하는 방법을 잘못 가른다','세기 · 전달') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u3-X32','sci',3,'u3',ARRAY['SC3-2-u3-C13','SC3-2-u3-C14']::text[],'소음과 알맞은 줄이는 방법을 잘못 잇는다','발소리에는 매트·실내화') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u3-X33','sci',3,'u3',ARRAY['SC3-2-u3-C14']::text[],'실천할 방법을 고르는 기준을 잘못 안다(어렵거나 돈이 많이 드는 방법 등)','실천할 수 있는 방법') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u3-X34','sci',3,'u3',ARRAY['SC3-2-u3-C14','SC3-2-u3-C15']::text[],'혼자 있거나 내 집이면 소리를 마음껏 내도 된다고 여기거나 한쪽만 조심하면 된다고 여긴다','이웃에게는 소음') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u3-X35','sci',3,'u3',ARRAY['SC3-2-u3-C15']::text[],'실천·기록·소개 과정과 태도를 잘못 안다(기록하지 않기, 다른 모둠 흉보기, 한 번 빠뜨리면 소용없다 등)','매일 기록 · 함께 고쳐요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u3-X36','sci',3,'u3',ARRAY['SC3-2-u3-C16']::text[],'음향 카메라를 소리를 키우거나 없애는 기기로 여긴다','소리를 눈으로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u3-X37','sci',3,'u3',ARRAY['SC3-2-u3-C16']::text[],'음향 카메라 화면의 색깔이 바뀌는 까닭을 잘못 안다(날씨, 겉 색깔 등)','세기 · 높낮이') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u3-X38','sci',3,'u3',ARRAY['SC3-2-u3-C17']::text[],'인공지능 음향 카메라의 쓰임을 잘못 안다(저절로 고치기, 비 내리기 등)','고장 난 곳 찾기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u3-X39','sci',3,'u3',ARRAY['SC3-2-u3-C17']::text[],'인공지능의 뜻을 잘못 안다','생각하는 능력을 대신') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L01_basic#1','sci',3,2,'u3','L01','g3_2_sci_u3_L01_basic','lesson_basic','SC3-2-u3-C2',1,'mc','auto','페트병에 쌀을 넣고 흔들면 어떤 소리와 가장 닮았나요?',ARRAY['SC3-2-u3-X05']::text[],false,'{"seq":1,"concept":"SC3-2-u3-C2","difficulty":1,"kind":"mc","stem":"페트병에 쌀을 넣고 흔들면 어떤 소리와 가장 닮았나요?","options":[{"t":"빗소리","correct":true},{"t":"천둥소리","mis":"SC3-2-u3-X05"},{"t":"종소리","mis":"SC3-2-u3-X05"},{"t":"자동차 소리","mis":"SC3-2-u3-X05"}],"explanation":["쌀알이 잘게 부딪혀요.","빗방울을 떠올려요.","빗소리예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L01_basic#2','sci',3,2,'u3','L01','g3_2_sci_u3_L01_basic','lesson_basic','SC3-2-u3-C1',1,'sa','auto','병 입구를 입으로 불어서 소리를 냈어요. 소리를 낸 물체는 무엇인가요? 한 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC3-2-u3-C1","difficulty":1,"kind":"sa","stem":"병 입구를 입으로 불어서 소리를 냈어요. 소리를 낸 물체는 무엇인가요? 한 글자로 쓰세요.","answer":["병"],"explanation":["입으로 불었어요.","입구가 있는 물체예요.","병이에요."],"mis":"SC3-2-u3-X02"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L01_basic#3','sci',3,2,'u3','L01','g3_2_sci_u3_L01_basic','lesson_basic','SC3-2-u3-C1',1,'ox','auto','하나의 물체로도 여러 가지 방법으로 다양한 소리를 낼 수 있어요.',ARRAY['SC3-2-u3-X01']::text[],false,'{"seq":3,"concept":"SC3-2-u3-C1","difficulty":1,"kind":"ox","stem":"하나의 물체로도 여러 가지 방법으로 다양한 소리를 낼 수 있어요.","answer":"O","reason_options":[{"t":"페트병을 흔들거나 문질러서 서로 다른 소리를 낼 수 있기 때문에","correct":true},{"t":"한 물체는 한 가지 소리만 내기 때문에","mis":"SC3-2-u3-X01"}],"mis":"SC3-2-u3-X01","explanation":["페트병을 떠올려요.","방법을 바꿔 봐요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L01_basic#4','sci',3,2,'u3','L01','g3_2_sci_u3_L01_basic','lesson_basic','SC3-2-u3-C2',1,'mc','auto','소리를 낼 때 쓰지 않아야 하는 물체는 무엇인가요?',ARRAY['SC3-2-u3-X03']::text[],false,'{"seq":4,"concept":"SC3-2-u3-C2","difficulty":1,"kind":"mc","stem":"소리를 낼 때 쓰지 않아야 하는 물체는 무엇인가요?","options":[{"t":"가위","correct":true},{"t":"페트병","mis":"SC3-2-u3-X03"},{"t":"알루미늄 캔","mis":"SC3-2-u3-X03"},{"t":"비닐봉지","mis":"SC3-2-u3-X03"}],"explanation":["손을 다칠 수 있는 물체를 찾아요.","뾰족한 물체예요.","가위예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L01_basic#5','sci',3,2,'u3','L01','g3_2_sci_u3_L01_basic','lesson_basic','SC3-2-u3-C1',2,'match','auto','물체와 소리를 낸 방법을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC3-2-u3-C1","difficulty":2,"kind":"match","stem":"물체와 소리를 낸 방법을 알맞게 이으세요.","pairs":[{"l":"풍선","r":"손으로 두드려요"},{"l":"병","r":"입구를 입으로 불어요"},{"l":"비닐봉지","r":"두 손으로 비벼요"}],"mis":"SC3-2-u3-X02","explanation":["물체를 하나씩 떠올려요.","병은 입으로 해요.","풍선-두드리기, 병-불기, 비닐봉지-비비기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L01_basic#6','sci',3,2,'u3','L01','g3_2_sci_u3_L01_basic','lesson_basic','SC3-2-u3-C1',2,'mc','auto','소리 낸 방법 기록에서 두드려서 소리를 낸 것은 무엇인가요?',ARRAY['SC3-2-u3-X02']::text[],false,'{"seq":6,"concept":"SC3-2-u3-C1","difficulty":2,"kind":"mc","stem":"소리 낸 방법 기록에서 두드려서 소리를 낸 것은 무엇인가요?","options":[{"t":"㉠","correct":true},{"t":"㉡","mis":"SC3-2-u3-X02"},{"t":"㉢","mis":"SC3-2-u3-X02"},{"t":"㉣","mis":"SC3-2-u3-X02"}],"explanation":["손으로 친 것을 찾아요.","풍선을 봐요.","㉠이에요."],"asset":{"type":"passage","lines":["㉠ 풍선을 손으로 두드렸어요.","㉡ 병 입구를 입으로 불었어요.","㉢ 비닐봉지를 두 손으로 비볐어요.","㉣ 쌀을 넣은 페트병을 흔들었어요."],"title":"소리 낸 방법 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L01_basic#7','sci',3,2,'u3','L01','g3_2_sci_u3_L01_basic','lesson_basic','SC3-2-u3-C2',2,'mc','auto','친구가 내는 소리를 듣고 알아맞힐 때 알맞은 태도는 무엇인가요?',ARRAY['SC3-2-u3-X04']::text[],false,'{"seq":7,"concept":"SC3-2-u3-C2","difficulty":2,"kind":"mc","stem":"친구가 내는 소리를 듣고 알아맞힐 때 알맞은 태도는 무엇인가요?","options":[{"t":"조용히 귀 기울여 들어요","correct":true},{"t":"큰 소리로 떠들어요","mis":"SC3-2-u3-X04"},{"t":"귀를 막고 있어요","mis":"SC3-2-u3-X04"},{"t":"다 듣기 전에 답을 외쳐요","mis":"SC3-2-u3-X04"}],"explanation":["잘 들어야 맞혀요.","끝까지 들어요.","조용히 귀 기울여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L01_basic#8','sci',3,2,'u3','L01','g3_2_sci_u3_L01_basic','lesson_basic','SC3-2-u3-C2',2,'blank','auto','「쟁반에 쌀을 올려놓고 흔들면 (    ) 소리와 비슷해요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC3-2-u3-X05']::text[],false,'{"seq":8,"concept":"SC3-2-u3-C2","difficulty":2,"kind":"blank","stem":"「쟁반에 쌀을 올려놓고 흔들면 (    ) 소리와 비슷해요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"파도","correct":true},{"t":"천둥","mis":"SC3-2-u3-X05"},{"t":"날갯짓","mis":"SC3-2-u3-X05"},{"t":"종","mis":"SC3-2-u3-X05"}],"explanation":["쌀이 쟁반 위를 쓸려 다녀요.","바닷가를 떠올려요.","파도 소리예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L01_basic#9','sci',3,2,'u3','L01','g3_2_sci_u3_L01_basic','lesson_basic','SC3-2-u3-C2',2,'ox','auto','소리 내기 놀이는 많이 맞힌 모둠이 앞서는 것이 가장 중요해요.',ARRAY['SC3-2-u3-X04']::text[],false,'{"seq":9,"concept":"SC3-2-u3-C2","difficulty":2,"kind":"ox","stem":"소리 내기 놀이는 많이 맞힌 모둠이 앞서는 것이 가장 중요해요.","answer":"X","reason_options":[{"t":"소리를 내고 듣는 과정이 더 중요하기 때문에","correct":true},{"t":"많이 맞혀야 잘한 것이기 때문에","mis":"SC3-2-u3-X04"}],"mis":"SC3-2-u3-X04","explanation":["놀이의 목적을 떠올려요.","과정이 중요해요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L01_basic#10','sci',3,2,'u3','L01','g3_2_sci_u3_L01_basic','lesson_basic','SC3-2-u3-C1',3,'mc','auto','연필 옆면으로 페트병을 위아래로 문질러 소리를 냈어요. 같은 페트병으로 다른 소리를 내는 방법으로 알맞은 것은 무엇인가요?',ARRAY['SC3-2-u3-X01','SC3-2-u3-X03','SC3-2-u3-X02']::text[],false,'{"seq":10,"concept":"SC3-2-u3-C1","difficulty":3,"kind":"mc","stem":"연필 옆면으로 페트병을 위아래로 문질러 소리를 냈어요. 같은 페트병으로 다른 소리를 내는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"페트병에 쌀을 넣고 흔든다","correct":true},{"t":"같은 방법으로 한 번 더 문지른다","mis":"SC3-2-u3-X01"},{"t":"유리컵으로 페트병을 세게 친다","mis":"SC3-2-u3-X03"},{"t":"페트병을 들고 가만히 있는다","mis":"SC3-2-u3-X02"}],"explanation":["방법을 바꿔야 해요.","다칠 물체는 안 돼요.","쌀을 넣고 흔들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L01_challenge#1','sci',3,2,'u3','L01','g3_2_sci_u3_L01_challenge','lesson_challenge','SC3-2-u3-C2',2,'sa','auto','수건을 펄럭이면 새가 날 때 나는 소리와 비슷해요. 「새의 ○○○ 소리」에서 ○○○에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SC3-2-u3-C2","difficulty":2,"kind":"sa","stem":"수건을 펄럭이면 새가 날 때 나는 소리와 비슷해요. 「새의 ○○○ 소리」에서 ○○○에 알맞은 말을 쓰세요.","answer":["날갯짓"],"explanation":["새가 날 때예요.","날개를 움직여요.","날갯짓이에요."],"mis":"SC3-2-u3-X05"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L01_challenge#2','sci',3,2,'u3','L01','g3_2_sci_u3_L01_challenge','lesson_challenge','SC3-2-u3-C1',2,'mc','auto','소리 낸 방법 기록에서 입으로 불어서 소리를 낸 것은 무엇인가요?',ARRAY['SC3-2-u3-X02']::text[],false,'{"seq":2,"concept":"SC3-2-u3-C1","difficulty":2,"kind":"mc","stem":"소리 낸 방법 기록에서 입으로 불어서 소리를 낸 것은 무엇인가요?","options":[{"t":"㉡","correct":true},{"t":"㉠","mis":"SC3-2-u3-X02"},{"t":"㉢","mis":"SC3-2-u3-X02"},{"t":"㉣","mis":"SC3-2-u3-X02"}],"explanation":["입을 쓴 것을 찾아요.","병 입구예요.","㉡이에요."],"asset":{"type":"passage","lines":["㉠ 풍선을 손으로 두드렸어요.","㉡ 병 입구를 입으로 불었어요.","㉢ 비닐봉지를 두 손으로 비볐어요.","㉣ 쌀을 넣은 페트병을 흔들었어요."],"title":"소리 낸 방법 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L01_challenge#3','sci',3,2,'u3','L01','g3_2_sci_u3_L01_challenge','lesson_challenge','SC3-2-u3-C2',3,'error','auto','소리 내기 놀이를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-2-u3-X03','SC3-2-u3-X04']::text[],false,'{"seq":3,"concept":"SC3-2-u3-C2","difficulty":3,"kind":"error","stem":"소리 내기 놀이를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「크게 낼수록 잘 맞히니까 있는 힘껏 소리 내자.」","correct":true,"mis_target":"SC3-2-u3-X03"},{"t":"친구 나 — 「다치지 않게 가위나 유리는 쓰지 말자.」","mis":"SC3-2-u3-X03"},{"t":"친구 다 — 「소리를 다 들은 뒤에 답을 말하자.」","mis":"SC3-2-u3-X04"}],"explanation":["약속을 떠올려요.","너무 크게 내지 않아요.","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L01_challenge#4','sci',3,2,'u3','L01','g3_2_sci_u3_L01_challenge','lesson_challenge','SC3-2-u3-C1',3,'mc','auto','소리 낸 방법 기록 ㉠~㉣ 가운데 비비거나 흔들어서 소리를 낸 것끼리 묶은 것은 무엇인가요?',ARRAY['SC3-2-u3-X02']::text[],false,'{"seq":4,"concept":"SC3-2-u3-C1","difficulty":3,"kind":"mc","stem":"소리 낸 방법 기록 ㉠~㉣ 가운데 비비거나 흔들어서 소리를 낸 것끼리 묶은 것은 무엇인가요?","options":[{"t":"㉢, ㉣","correct":true},{"t":"㉠, ㉡","mis":"SC3-2-u3-X02"},{"t":"㉠, ㉢","mis":"SC3-2-u3-X02"},{"t":"㉡, ㉣","mis":"SC3-2-u3-X02"}],"explanation":["하나씩 읽어요.","비닐봉지와 페트병이에요.","㉢, ㉣이에요."],"asset":{"type":"passage","lines":["㉠ 풍선을 손으로 두드렸어요.","㉡ 병 입구를 입으로 불었어요.","㉢ 비닐봉지를 두 손으로 비볐어요.","㉣ 쌀을 넣은 페트병을 흔들었어요."],"title":"소리 낸 방법 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L01_challenge#5','sci',3,2,'u3','L01','g3_2_sci_u3_L01_challenge','lesson_challenge','SC3-2-u3-C2',3,'match','auto','내고 싶은 소리와 비슷하게 내는 방법을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC3-2-u3-C2","difficulty":3,"kind":"match","stem":"내고 싶은 소리와 비슷하게 내는 방법을 알맞게 이으세요.","pairs":[{"l":"빗소리","r":"페트병에 쌀을 넣고 흔들어요"},{"l":"파도 소리","r":"쟁반에 쌀을 올려놓고 흔들어요"},{"l":"날갯짓 소리","r":"수건을 펄럭여요"}],"mis":"SC3-2-u3-X05","explanation":["닮은 움직임을 떠올려요.","수건은 날개처럼 펄럭여요.","빗소리-페트병, 파도-쟁반, 날갯짓-수건이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L01_challenge#6','sci',3,2,'u3','L01','g3_2_sci_u3_L01_challenge','lesson_challenge','SC3-2-u3-C1',3,'mc','auto','「풍선 두드리기, 나무판을 자로 두드리기, 비닐봉지 비비기」를 「두드려서 낸 소리인가?」로 나누었어요. ⭕ 쪽에 들어가는 것끼리 묶은 것은 무엇인가요?',ARRAY['SC3-2-u3-X02']::text[],false,'{"seq":6,"concept":"SC3-2-u3-C1","difficulty":3,"kind":"mc","stem":"「풍선 두드리기, 나무판을 자로 두드리기, 비닐봉지 비비기」를 「두드려서 낸 소리인가?」로 나누었어요. ⭕ 쪽에 들어가는 것끼리 묶은 것은 무엇인가요?","options":[{"t":"풍선, 나무판","correct":true},{"t":"풍선, 비닐봉지","mis":"SC3-2-u3-X02"},{"t":"나무판, 비닐봉지","mis":"SC3-2-u3-X02"},{"t":"비닐봉지만","mis":"SC3-2-u3-X02"}],"explanation":["두드린 것을 찾아요.","비닐봉지는 비볐어요.","풍선, 나무판이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L01_challenge#7','sci',3,2,'u3','L01','g3_2_sci_u3_L01_challenge','lesson_challenge','SC3-2-u3-C1',3,'ox','auto','같은 페트병이라도 흔들 때와 문지를 때 나는 소리는 서로 달라요.',ARRAY['SC3-2-u3-X01']::text[],false,'{"seq":7,"concept":"SC3-2-u3-C1","difficulty":3,"kind":"ox","stem":"같은 페트병이라도 흔들 때와 문지를 때 나는 소리는 서로 달라요.","answer":"O","reason_options":[{"t":"소리를 낸 방법이 달라지면 다른 소리가 나기 때문에","correct":true},{"t":"물체가 같으면 언제나 같은 소리가 나기 때문에","mis":"SC3-2-u3-X01"}],"mis":"SC3-2-u3-X01","explanation":["방법을 견줘요.","흔들기와 문지르기예요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L01_challenge#8','sci',3,2,'u3','L01','g3_2_sci_u3_L01_challenge','lesson_challenge','SC3-2-u3-C2',4,'mc','auto','친구가 칸막이 뒤에서 소리를 들려주었어요. 알아맞히는 말로 가장 알맞은 것은 무엇인가요?',ARRAY['SC3-2-u3-X04','SC3-2-u3-X01']::text[],false,'{"seq":8,"concept":"SC3-2-u3-C2","difficulty":4,"kind":"mc","stem":"친구가 칸막이 뒤에서 소리를 들려주었어요. 알아맞히는 말로 가장 알맞은 것은 무엇인가요?","options":[{"t":"「바스락바스락 소리가 났으니 비닐봉지를 두 손으로 비볐을 것 같아.」","correct":true},{"t":"「무슨 소리인지 몰라도 일단 내가 먼저 외칠래.」","mis":"SC3-2-u3-X04"},{"t":"「물체만 맞히면 되니까 방법은 생각하지 않아도 돼.」","mis":"SC3-2-u3-X04"},{"t":"「한 물체는 한 소리만 나니까 무조건 페트병이야.」","mis":"SC3-2-u3-X01"}],"explanation":["끝까지 들어요.","물체와 방법을 함께 말해요.","비닐봉지 비비기를 짐작한 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L01_challenge#9','sci',3,2,'u3','L01','g3_2_sci_u3_L01_challenge','lesson_challenge','SC3-2-u3-C1',4,'mc','auto','알루미늄 캔 하나로 서로 다른 소리를 세 가지 내려고 해요. 가장 알맞은 계획은 무엇인가요?',ARRAY['SC3-2-u3-X01','SC3-2-u3-X03','SC3-2-u3-X02']::text[],false,'{"seq":9,"concept":"SC3-2-u3-C1","difficulty":4,"kind":"mc","stem":"알루미늄 캔 하나로 서로 다른 소리를 세 가지 내려고 해요. 가장 알맞은 계획은 무엇인가요?","options":[{"t":"손가락으로 두드리기, 연필로 문지르기, 쌀을 넣고 흔들기","correct":true},{"t":"손가락으로 한 번, 두 번, 세 번 두드리기","mis":"SC3-2-u3-X01"},{"t":"캔 대신 유리병과 가위로 소리 내기","mis":"SC3-2-u3-X03"},{"t":"캔은 두고 입으로 캔 소리를 흉내 내기","mis":"SC3-2-u3-X02"}],"explanation":["방법이 서로 달라야 해요.","다칠 물체는 빼요.","두드리기·문지르기·흔들기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L01_challenge#10','sci',3,2,'u3','L01','g3_2_sci_u3_L01_challenge','lesson_challenge','SC3-2-u3-C2',4,'essay','teacher','소리 내기 놀이에서 한 물체로 소리를 낸 방법 두 가지를 쓰고, 놀이할 때 지킬 약속 두 가지를 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC3-2-u3-C2","difficulty":4,"kind":"essay","stem":"소리 내기 놀이에서 한 물체로 소리를 낸 방법 두 가지를 쓰고, 놀이할 때 지킬 약속 두 가지를 쓰세요.","answer_guide":{"answer":"예: 페트병을 연필 옆면으로 문질러 소리를 냈고, 페트병에 쌀을 넣고 흔들어 빗소리 같은 소리를 냈다. 가위나 유리처럼 다칠 수 있는 물체는 쓰지 않고, 소리를 너무 크게 내지 않는다.","scoring_points":["한 물체로 소리를 낸 방법 두 가지를 썼는가","다칠 수 있는 물체를 쓰지 않는 약속을 썼는가","소리를 너무 크게 내지 않거나 귀 기울여 듣는 약속을 썼는가"]},"explanation":["한 물체를 골라요.","방법을 두 가지 써요.","약속을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L02_basic#1','sci',3,2,'u3','L02','g3_2_sci_u3_L02_basic','lesson_basic','SC3-2-u3-C3',1,'mc','auto','소리가 나는 소리굽쇠에 손을 대면 어떤 느낌이 드나요?',ARRAY['SC3-2-u3-X07','SC3-2-u3-X06']::text[],false,'{"seq":1,"concept":"SC3-2-u3-C3","difficulty":1,"kind":"mc","stem":"소리가 나는 소리굽쇠에 손을 대면 어떤 느낌이 드나요?","options":[{"t":"떨림이 느껴져요","correct":true},{"t":"뜨거워져요","mis":"SC3-2-u3-X07"},{"t":"아무 느낌이 없어요","mis":"SC3-2-u3-X06"},{"t":"물기가 느껴져요","mis":"SC3-2-u3-X07"}],"explanation":["소리가 나고 있어요.","손에 무엇이 느껴질까요?","떨림이 느껴져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L02_basic#2','sci',3,2,'u3','L02','g3_2_sci_u3_L02_basic','lesson_basic','SC3-2-u3-C3',1,'sa','auto','소리가 나는 물체에서 공통으로 찾을 수 있는 것을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC3-2-u3-C3","difficulty":1,"kind":"sa","stem":"소리가 나는 물체에서 공통으로 찾을 수 있는 것을 두 글자로 쓰세요.","answer":["떨림"],"explanation":["소리굽쇠를 떠올려요.","손에 느껴졌어요.","떨림이에요."],"mis":"SC3-2-u3-X06"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L02_basic#3','sci',3,2,'u3','L02','g3_2_sci_u3_L02_basic','lesson_basic','SC3-2-u3-C4',1,'ox','auto','소리는 귀뿐 아니라 눈과 손으로도 관찰할 수 있어요.',ARRAY['SC3-2-u3-X08']::text[],false,'{"seq":3,"concept":"SC3-2-u3-C4","difficulty":1,"kind":"ox","stem":"소리는 귀뿐 아니라 눈과 손으로도 관찰할 수 있어요.","answer":"O","reason_options":[{"t":"튀어 오르는 탁구공은 눈으로, 떨림은 손으로 알 수 있기 때문에","correct":true},{"t":"소리는 귀로만 들을 수 있기 때문에","mis":"SC3-2-u3-X08"}],"mis":"SC3-2-u3-X08","explanation":["탁구공을 떠올려요.","눈으로 봤어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L02_basic#4','sci',3,2,'u3','L02','g3_2_sci_u3_L02_basic','lesson_basic','SC3-2-u3-C4',1,'mc','auto','기타 줄을 튕겨 소리가 날 때 줄은 어떻게 되나요?',ARRAY['SC3-2-u3-X10']::text[],false,'{"seq":4,"concept":"SC3-2-u3-C4","difficulty":1,"kind":"mc","stem":"기타 줄을 튕겨 소리가 날 때 줄은 어떻게 되나요?","options":[{"t":"줄이 떨려요","correct":true},{"t":"줄이 끊어져요","mis":"SC3-2-u3-X10"},{"t":"줄이 가만히 있어요","mis":"SC3-2-u3-X10"},{"t":"줄이 뜨거워져요","mis":"SC3-2-u3-X10"}],"explanation":["소리가 나고 있어요.","줄을 살펴봐요.","줄이 떨려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L02_basic#5','sci',3,2,'u3','L02','g3_2_sci_u3_L02_basic','lesson_basic','SC3-2-u3-C3',2,'match','auto','소리가 나는 소리굽쇠를 대 보았을 때 일어난 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC3-2-u3-C3","difficulty":2,"kind":"match","stem":"소리가 나는 소리굽쇠를 대 보았을 때 일어난 일을 알맞게 이으세요.","pairs":[{"l":"손","r":"떨림이 느껴져요"},{"l":"매달린 탁구공","r":"공이 튀어 올라요"},{"l":"물 표면","r":"주변의 물이 튀어 올라요"}],"mis":"SC3-2-u3-X07","explanation":["관찰 결과를 떠올려요.","손은 느껴요.","공과 물은 튀어 올라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L02_basic#6','sci',3,2,'u3','L02','g3_2_sci_u3_L02_basic','lesson_basic','SC3-2-u3-C4',2,'mc','auto','트라이앵글 소리를 멈추려면 어떻게 해야 하나요?',ARRAY['SC3-2-u3-X09']::text[],false,'{"seq":6,"concept":"SC3-2-u3-C4","difficulty":2,"kind":"mc","stem":"트라이앵글 소리를 멈추려면 어떻게 해야 하나요?","options":[{"t":"손으로 잡아 떨림을 멈춰요","correct":true},{"t":"더 세게 쳐요","mis":"SC3-2-u3-X09"},{"t":"채를 바꿔 쳐요","mis":"SC3-2-u3-X09"},{"t":"멀리 떨어져서 봐요","mis":"SC3-2-u3-X09"}],"explanation":["소리는 떨림이 있을 때 나요.","떨림을 멈춰요.","손으로 잡아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L02_basic#7','sci',3,2,'u3','L02','g3_2_sci_u3_L02_basic','lesson_basic','SC3-2-u3-C3',2,'mc','auto','소리굽쇠 관찰 기록에서 ㉠에 알맞은 말은 무엇인가요?',ARRAY['SC3-2-u3-X07']::text[],false,'{"seq":7,"concept":"SC3-2-u3-C3","difficulty":2,"kind":"mc","stem":"소리굽쇠 관찰 기록에서 ㉠에 알맞은 말은 무엇인가요?","options":[{"t":"떨림","correct":true},{"t":"차가움","mis":"SC3-2-u3-X07"},{"t":"뜨거움","mis":"SC3-2-u3-X07"},{"t":"바람","mis":"SC3-2-u3-X07"}],"explanation":["친 뒤에 손을 댔어요.","소리가 나고 있어요.","떨림이에요."],"asset":{"type":"passage","lines":["손 — 치기 전에 대 보니 딱딱하고 차가웠어요.","손 — 친 뒤에 대 보니 ㉠이 느껴졌어요.","탁구공 — 친 소리굽쇠를 대니 공이 튀어 올랐어요.","물 — 친 소리굽쇠를 대니 주변의 물이 튀어 올랐어요."],"title":"소리굽쇠 관찰 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L02_basic#8','sci',3,2,'u3','L02','g3_2_sci_u3_L02_basic','lesson_basic','SC3-2-u3-C4',2,'blank','auto','「목에 손을 살짝 대고 「아.」 하고 소리를 내면 손에 목의 (    )이 느껴져요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC3-2-u3-X10']::text[],false,'{"seq":8,"concept":"SC3-2-u3-C4","difficulty":2,"kind":"blank","stem":"「목에 손을 살짝 대고 「아.」 하고 소리를 내면 손에 목의 (    )이 느껴져요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"떨림","correct":true},{"t":"물기","mis":"SC3-2-u3-X10"},{"t":"차가움","mis":"SC3-2-u3-X10"},{"t":"딱딱함","mis":"SC3-2-u3-X10"}],"explanation":["목에서 소리가 나요.","소리가 나는 물체를 떠올려요.","떨림이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L02_basic#9','sci',3,2,'u3','L02','g3_2_sci_u3_L02_basic','lesson_basic','SC3-2-u3-C3',2,'ox','auto','치지 않아 소리가 나지 않는 종도 떨림이 있어요.',ARRAY['SC3-2-u3-X06']::text[],false,'{"seq":9,"concept":"SC3-2-u3-C3","difficulty":2,"kind":"ox","stem":"치지 않아 소리가 나지 않는 종도 떨림이 있어요.","answer":"X","reason_options":[{"t":"소리가 날 때만 떨림이 있기 때문에","correct":true},{"t":"종은 언제나 떨리고 있기 때문에","mis":"SC3-2-u3-X06"}],"mis":"SC3-2-u3-X06","explanation":["치지 않았어요.","소리가 나지 않아요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L02_basic#10','sci',3,2,'u3','L02','g3_2_sci_u3_L02_basic','lesson_basic','SC3-2-u3-C4',3,'mc','auto','노래가 나오는 스피커에 대해 바르게 말한 것은 무엇인가요?',ARRAY['SC3-2-u3-X10','SC3-2-u3-X08','SC3-2-u3-X09']::text[],false,'{"seq":10,"concept":"SC3-2-u3-C4","difficulty":3,"kind":"mc","stem":"노래가 나오는 스피커에 대해 바르게 말한 것은 무엇인가요?","options":[{"t":"스피커 막이 떨리고, 손을 대면 떨림이 느껴진다","correct":true},{"t":"스피커는 떨리지 않고 소리만 난다","mis":"SC3-2-u3-X10"},{"t":"스피커 막은 눈으로만 볼 수 있고 손으로는 알 수 없다","mis":"SC3-2-u3-X08"},{"t":"스피커 막을 눌러 떨림을 멈추어도 소리는 그대로 난다","mis":"SC3-2-u3-X09"}],"explanation":["스피커 막을 살펴봐요.","손을 대 봐요.","막이 떨리고 손으로 느껴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L02_challenge#1','sci',3,2,'u3','L02','g3_2_sci_u3_L02_challenge','lesson_challenge','SC3-2-u3-C4',2,'sa','auto','말하는 사람의 몸에서 소리가 날 때 떨리는 곳을 한 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SC3-2-u3-C4","difficulty":2,"kind":"sa","stem":"말하는 사람의 몸에서 소리가 날 때 떨리는 곳을 한 글자로 쓰세요.","answer":["목"],"explanation":["「아.」 하고 소리 내 봐요.","손을 대 봐요.","목이에요."],"mis":"SC3-2-u3-X10"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L02_challenge#2','sci',3,2,'u3','L02','g3_2_sci_u3_L02_challenge','lesson_challenge','SC3-2-u3-C3',2,'mc','auto','소리가 나지 않는 소리굽쇠에 손을 대면 어떤 느낌이 드나요?',ARRAY['SC3-2-u3-X06','SC3-2-u3-X07']::text[],false,'{"seq":2,"concept":"SC3-2-u3-C3","difficulty":2,"kind":"mc","stem":"소리가 나지 않는 소리굽쇠에 손을 대면 어떤 느낌이 드나요?","options":[{"t":"딱딱하고 차갑게 느껴져요","correct":true},{"t":"떨림이 느껴져요","mis":"SC3-2-u3-X06"},{"t":"물이 튀어 올라요","mis":"SC3-2-u3-X07"},{"t":"공이 튀어 올라요","mis":"SC3-2-u3-X07"}],"explanation":["치기 전이에요.","소리가 나지 않아요.","딱딱하고 차가워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L02_challenge#3','sci',3,2,'u3','L02','g3_2_sci_u3_L02_challenge','lesson_challenge','SC3-2-u3-C3',3,'error','auto','소리굽쇠 관찰을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-2-u3-X07','SC3-2-u3-X06','SC3-2-u3-X08']::text[],false,'{"seq":3,"concept":"SC3-2-u3-C3","difficulty":3,"kind":"error","stem":"소리굽쇠 관찰을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「친 소리굽쇠를 물에 대도 물은 그대로야.」","correct":true,"mis_target":"SC3-2-u3-X07"},{"t":"친구 가 — 「친 소리굽쇠에 손을 대니 떨렸어.」","mis":"SC3-2-u3-X06"},{"t":"친구 나 — 「탁구공이 튀어 오르는 것을 눈으로 봤어.」","mis":"SC3-2-u3-X08"}],"explanation":["물에 댄 결과를 떠올려요.","물이 튀어 올랐어요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L02_challenge#4','sci',3,2,'u3','L02','g3_2_sci_u3_L02_challenge','lesson_challenge','SC3-2-u3-C4',3,'mc','auto','관찰한 모습을 「손으로 느낀 관찰인가?」로 나누었을 때 ⭕ 쪽에 들어가는 것끼리 묶은 것은 무엇인가요?',ARRAY['SC3-2-u3-X08']::text[],false,'{"seq":4,"concept":"SC3-2-u3-C4","difficulty":3,"kind":"mc","stem":"관찰한 모습을 「손으로 느낀 관찰인가?」로 나누었을 때 ⭕ 쪽에 들어가는 것끼리 묶은 것은 무엇인가요?","options":[{"t":"소리 나는 소리굽쇠에 손 대기, 「아.」 하는 목에 손 대기","correct":true},{"t":"튀어 오르는 탁구공, 튀어 오르는 물","mis":"SC3-2-u3-X08"},{"t":"튀어 오르는 탁구공, 목에 손 대기","mis":"SC3-2-u3-X08"},{"t":"튀어 오르는 물, 소리굽쇠에 손 대기","mis":"SC3-2-u3-X08"}],"explanation":["손을 쓴 것을 찾아요.","튀어 오르는 것은 눈으로 봐요.","손을 댄 두 가지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L02_challenge#5','sci',3,2,'u3','L02','g3_2_sci_u3_L02_challenge','lesson_challenge','SC3-2-u3-C3',3,'mc','auto','소리굽쇠 관찰 기록으로 알 수 있는 것은 무엇인가요?',ARRAY['SC3-2-u3-X06','SC3-2-u3-X07','SC3-2-u3-X08']::text[],false,'{"seq":5,"concept":"SC3-2-u3-C3","difficulty":3,"kind":"mc","stem":"소리굽쇠 관찰 기록으로 알 수 있는 것은 무엇인가요?","options":[{"t":"소리가 나는 물체는 떨림이 있다","correct":true},{"t":"소리굽쇠는 치기 전에도 떨린다","mis":"SC3-2-u3-X06"},{"t":"소리굽쇠는 물에서만 소리가 난다","mis":"SC3-2-u3-X07"},{"t":"소리는 귀로만 관찰할 수 있다","mis":"SC3-2-u3-X08"}],"explanation":["넷을 모두 읽어요.","친 뒤에만 달라졌어요.","떨림이 있어요."],"asset":{"type":"passage","lines":["손 — 치기 전에 대 보니 딱딱하고 차가웠어요.","손 — 친 뒤에 대 보니 ㉠이 느껴졌어요.","탁구공 — 친 소리굽쇠를 대니 공이 튀어 올랐어요.","물 — 친 소리굽쇠를 대니 주변의 물이 튀어 올랐어요."],"title":"소리굽쇠 관찰 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L02_challenge#6','sci',3,2,'u3','L02','g3_2_sci_u3_L02_challenge','lesson_challenge','SC3-2-u3-C4',3,'match','auto','물체와 소리가 날 때 떨리는 부분을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SC3-2-u3-C4","difficulty":3,"kind":"match","stem":"물체와 소리가 날 때 떨리는 부분을 알맞게 이으세요.","pairs":[{"l":"기타","r":"줄"},{"l":"스피커","r":"막"},{"l":"말하는 사람","r":"목"}],"mis":"SC3-2-u3-X10","explanation":["소리가 나는 곳을 찾아요.","기타는 줄을 튕겨요.","기타-줄, 스피커-막, 사람-목이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L02_challenge#7','sci',3,2,'u3','L02','g3_2_sci_u3_L02_challenge','lesson_challenge','SC3-2-u3-C4',3,'ox','auto','소리가 나는 소리굽쇠를 손으로 꽉 잡으면 소리가 멈춰요.',ARRAY['SC3-2-u3-X09']::text[],false,'{"seq":7,"concept":"SC3-2-u3-C4","difficulty":3,"kind":"ox","stem":"소리가 나는 소리굽쇠를 손으로 꽉 잡으면 소리가 멈춰요.","answer":"O","reason_options":[{"t":"떨림을 멈추면 소리도 멈추기 때문에","correct":true},{"t":"손으로 잡으면 소리가 더 커지기 때문에","mis":"SC3-2-u3-X09"}],"mis":"SC3-2-u3-X09","explanation":["잡으면 떨림이 어떻게 될까요?","떨림이 멈춰요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L02_challenge#8','sci',3,2,'u3','L02','g3_2_sci_u3_L02_challenge','lesson_challenge','SC3-2-u3-C3',4,'mc','auto','「종소리는 어떻게 나는 걸까?」 친구의 물음에 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-2-u3-X06','SC3-2-u3-X08','SC3-2-u3-X09']::text[],false,'{"seq":8,"concept":"SC3-2-u3-C3","difficulty":4,"kind":"mc","stem":"「종소리는 어떻게 나는 걸까?」 친구의 물음에 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「종을 치면 종이 떨리면서 소리가 나. 손을 대 보면 떨림을 느낄 수 있어.」","correct":true},{"t":"「종은 치지 않아도 늘 떨리고 있어서 소리가 나.」","mis":"SC3-2-u3-X06"},{"t":"「종소리는 귀로만 알 수 있어서 손으로는 알 수 없어.」","mis":"SC3-2-u3-X08"},{"t":"「종을 손으로 잡아 떨림을 멈춰도 소리는 계속 나.」","mis":"SC3-2-u3-X09"}],"explanation":["칠 때를 떠올려요.","떨림을 느낄 수 있어요.","첫 번째 답이 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L02_challenge#9','sci',3,2,'u3','L02','g3_2_sci_u3_L02_challenge','lesson_challenge','SC3-2-u3-C4',4,'mc','auto','「지금 떨림이 있는가?」로 나누었어요. 떨림이 있는 쪽에 들어갈 것끼리 바르게 묶은 것은 무엇인가요?',ARRAY['SC3-2-u3-X06','SC3-2-u3-X10']::text[],false,'{"seq":9,"concept":"SC3-2-u3-C4","difficulty":4,"kind":"mc","stem":"「지금 떨림이 있는가?」로 나누었어요. 떨림이 있는 쪽에 들어갈 것끼리 바르게 묶은 것은 무엇인가요?","options":[{"t":"소리가 나는 기타 줄, 노래가 나오는 스피커","correct":true},{"t":"치지 않은 종, 치기 전의 소리굽쇠","mis":"SC3-2-u3-X06"},{"t":"소리가 나는 기타 줄, 치지 않은 종","mis":"SC3-2-u3-X06"},{"t":"노래가 나오는 스피커, 치기 전의 소리굽쇠","mis":"SC3-2-u3-X10"}],"explanation":["지금 소리가 나는지 봐요.","치지 않은 것은 빼요.","기타 줄과 스피커예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L02_challenge#10','sci',3,2,'u3','L02','g3_2_sci_u3_L02_challenge','lesson_challenge','SC3-2-u3-C3',4,'essay','teacher','소리굽쇠를 친 뒤 손·탁구공·물에 대 본 결과를 두 가지 이상 쓰고, 이 결과로 알 수 있는 소리가 나는 물체의 특징을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC3-2-u3-C3","difficulty":4,"kind":"essay","stem":"소리굽쇠를 친 뒤 손·탁구공·물에 대 본 결과를 두 가지 이상 쓰고, 이 결과로 알 수 있는 소리가 나는 물체의 특징을 쓰세요.","answer_guide":{"answer":"예: 친 소리굽쇠에 손을 대니 떨림이 느껴졌고, 매달린 탁구공에 대니 공이 튀어 올랐으며, 물에 대니 물이 튀어 올랐다. 소리가 나는 물체는 떨림이 있다.","scoring_points":["관찰 결과를 두 가지 이상 썼는가","관찰 결과를 바르게 썼는가","소리가 나는 물체는 떨림이 있다고 썼는가"]},"explanation":["기록을 읽어요.","결과를 두 가지 써요.","특징을 써요."],"asset":{"type":"passage","lines":["손 — 치기 전에 대 보니 딱딱하고 차가웠어요.","손 — 친 뒤에 대 보니 ㉠이 느껴졌어요.","탁구공 — 친 소리굽쇠를 대니 공이 튀어 올랐어요.","물 — 친 소리굽쇠를 대니 주변의 물이 튀어 올랐어요."],"title":"소리굽쇠 관찰 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L03_basic#1','sci',3,2,'u3','L03','g3_2_sci_u3_L03_basic','lesson_basic','SC3-2-u3-C5',1,'mc','auto','소리의 크고 작은 정도를 무엇이라고 하나요?',ARRAY['SC3-2-u3-X11']::text[],false,'{"seq":1,"concept":"SC3-2-u3-C5","difficulty":1,"kind":"mc","stem":"소리의 크고 작은 정도를 무엇이라고 하나요?","options":[{"t":"소리의 세기","correct":true},{"t":"소리의 떨림","mis":"SC3-2-u3-X11"},{"t":"소리의 빠르기","mis":"SC3-2-u3-X11"},{"t":"소리의 맛","mis":"SC3-2-u3-X11"}],"explanation":["크고 작은 정도예요.","「세기」예요.","소리의 세기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L03_basic#2','sci',3,2,'u3','L03','g3_2_sci_u3_L03_basic','lesson_basic','SC3-2-u3-C5',1,'sa','auto','「소리의 ○○」는 소리의 크고 작은 정도를 말해요. ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC3-2-u3-C5","difficulty":1,"kind":"sa","stem":"「소리의 ○○」는 소리의 크고 작은 정도를 말해요. ○○에 알맞은 두 글자를 쓰세요.","answer":["세기"],"explanation":["크고 작은 정도예요.","세◯예요.","세기예요."],"mis":"SC3-2-u3-X11"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L03_basic#3','sci',3,2,'u3','L03','g3_2_sci_u3_L03_basic','lesson_basic','SC3-2-u3-C6',1,'ox','auto','작은북을 세게 치면 큰 소리가 나요.',ARRAY['SC3-2-u3-X13']::text[],false,'{"seq":3,"concept":"SC3-2-u3-C6","difficulty":1,"kind":"ox","stem":"작은북을 세게 치면 큰 소리가 나요.","answer":"O","reason_options":[{"t":"세게 치면 북면이 크게 떨리기 때문에","correct":true},{"t":"세게 치면 북면이 작게 떨리기 때문에","mis":"SC3-2-u3-X13"}],"mis":"SC3-2-u3-X13","explanation":["북면을 떠올려요.","크게 떨려요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L03_basic#4','sci',3,2,'u3','L03','g3_2_sci_u3_L03_basic','lesson_basic','SC3-2-u3-C5',1,'mc','auto','작은 소리를 내야 하는 때는 언제인가요?',ARRAY['SC3-2-u3-X12']::text[],false,'{"seq":4,"concept":"SC3-2-u3-C5","difficulty":1,"kind":"mc","stem":"작은 소리를 내야 하는 때는 언제인가요?","options":[{"t":"친구에게 귓속말을 할 때","correct":true},{"t":"멀리 있는 친구를 부를 때","mis":"SC3-2-u3-X12"},{"t":"운동회에서 응원할 때","mis":"SC3-2-u3-X12"},{"t":"친구들 앞에서 발표할 때","mis":"SC3-2-u3-X12"}],"explanation":["옆 친구만 들으면 돼요.","작게 말해요.","귓속말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L03_basic#5','sci',3,2,'u3','L03','g3_2_sci_u3_L03_basic','lesson_basic','SC3-2-u3-C6',2,'match','auto','작은북 실험의 관찰 결과를 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC3-2-u3-C6","difficulty":2,"kind":"match","stem":"작은북 실험의 관찰 결과를 알맞게 이으세요.","pairs":[{"l":"북면이 크게 떨리면","r":"큰 소리가 나요"},{"l":"북면이 작게 떨리면","r":"작은 소리가 나요"},{"l":"퐁퐁이가 높게 튀어 오르면","r":"세게 친 거예요"}],"mis":"SC3-2-u3-X13","explanation":["떨림과 소리를 이어요.","크게 떨리면 커요.","세게 치면 퐁퐁이가 높게 튀어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L03_basic#6','sci',3,2,'u3','L03','g3_2_sci_u3_L03_basic','lesson_basic','SC3-2-u3-C6',2,'mc','auto','작은북 실험 기록에서 큰 소리가 난 것은 무엇인가요?',ARRAY['SC3-2-u3-X15','SC3-2-u3-X13']::text[],false,'{"seq":6,"concept":"SC3-2-u3-C6","difficulty":2,"kind":"mc","stem":"작은북 실험 기록에서 큰 소리가 난 것은 무엇인가요?","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"SC3-2-u3-X15"},{"t":"둘 다 같아요","mis":"SC3-2-u3-X13"},{"t":"알 수 없어요","mis":"SC3-2-u3-X15"}],"explanation":["퐁퐁이 높이를 봐요.","높게 튄 것을 찾아요.","㉮예요."],"asset":{"type":"passage","lines":["㉮ 북채로 세게 쳤어요 — 퐁퐁이가 높게 튀어 올랐어요.","㉯ 북채로 약하게 쳤어요 — 퐁퐁이가 낮게 튀어 올랐어요.","디지털 탐구 도구 — ㉮는 큰 소리, ㉯는 작은 소리로 나왔어요."],"title":"작은북 실험 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L03_basic#7','sci',3,2,'u3','L03','g3_2_sci_u3_L03_basic','lesson_basic','SC3-2-u3-C6',2,'mc','auto','작은북을 약하게 치면 어떻게 되나요?',ARRAY['SC3-2-u3-X13','SC3-2-u3-X14']::text[],false,'{"seq":7,"concept":"SC3-2-u3-C6","difficulty":2,"kind":"mc","stem":"작은북을 약하게 치면 어떻게 되나요?","options":[{"t":"북면이 작게 떨리면서 작은 소리가 나요","correct":true},{"t":"북면이 크게 떨리면서 큰 소리가 나요","mis":"SC3-2-u3-X13"},{"t":"북면이 떨리지 않고 소리만 나요","mis":"SC3-2-u3-X14"},{"t":"북면이 크게 떨리면서 작은 소리가 나요","mis":"SC3-2-u3-X13"}],"explanation":["약하게 쳤어요.","떨림도 작아요.","작게 떨리며 작은 소리가 나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L03_basic#8','sci',3,2,'u3','L03','g3_2_sci_u3_L03_basic','lesson_basic','SC3-2-u3-C6',2,'blank','auto','「소리의 세기는 소리가 나는 물체의 (    ) 크고 작은 정도에 따라 달라져요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC3-2-u3-X13']::text[],false,'{"seq":8,"concept":"SC3-2-u3-C6","difficulty":2,"kind":"blank","stem":"「소리의 세기는 소리가 나는 물체의 (    ) 크고 작은 정도에 따라 달라져요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"떨림이","correct":true},{"t":"색깔이","mis":"SC3-2-u3-X13"},{"t":"무게가","mis":"SC3-2-u3-X13"},{"t":"모양이","mis":"SC3-2-u3-X13"}],"explanation":["북면을 떠올려요.","크게 떨리면 커요.","떨림이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L03_basic#9','sci',3,2,'u3','L03','g3_2_sci_u3_L03_basic','lesson_basic','SC3-2-u3-C6',2,'ox','auto','작은북으로 지나치게 큰 소리를 내도 괜찮아요.',ARRAY['SC3-2-u3-X16']::text[],false,'{"seq":9,"concept":"SC3-2-u3-C6","difficulty":2,"kind":"ox","stem":"작은북으로 지나치게 큰 소리를 내도 괜찮아요.","answer":"X","reason_options":[{"t":"너무 큰 소리는 귀를 다치게 할 수 있기 때문에","correct":true},{"t":"크게 낼수록 실험이 정확하기 때문에","mis":"SC3-2-u3-X16"}],"mis":"SC3-2-u3-X16","explanation":["귀를 떠올려요.","안전 약속이에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L03_basic#10','sci',3,2,'u3','L03','g3_2_sci_u3_L03_basic','lesson_basic','SC3-2-u3-C6',3,'mc','auto','작게 떨리는 심벌즈를 더 크게 떨리게 하면 어떻게 될까요?',ARRAY['SC3-2-u3-X13','SC3-2-u3-X14']::text[],false,'{"seq":10,"concept":"SC3-2-u3-C6","difficulty":3,"kind":"mc","stem":"작게 떨리는 심벌즈를 더 크게 떨리게 하면 어떻게 될까요?","options":[{"t":"소리가 더 커진다","correct":true},{"t":"소리가 더 작아진다","mis":"SC3-2-u3-X13"},{"t":"소리가 멈춘다","mis":"SC3-2-u3-X14"},{"t":"떨림만 커지고 소리는 그대로다","mis":"SC3-2-u3-X13"}],"explanation":["떨림이 커져요.","세기도 달라져요.","소리가 더 커져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L03_challenge#1','sci',3,2,'u3','L03','g3_2_sci_u3_L03_challenge','lesson_challenge','SC3-2-u3-C6',2,'sa','auto','심벌즈를 세게 치면 심벌즈가 크게 떨려요. 이때 나는 소리는 큰 소리인가요, 작은 소리인가요? 「큰」 또는 「작은」으로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SC3-2-u3-C6","difficulty":2,"kind":"sa","stem":"심벌즈를 세게 치면 심벌즈가 크게 떨려요. 이때 나는 소리는 큰 소리인가요, 작은 소리인가요? 「큰」 또는 「작은」으로 쓰세요.","answer":["큰","큰 소리"],"explanation":["세게 쳤어요.","크게 떨렸어요.","큰 소리예요."],"mis":"SC3-2-u3-X13"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L03_challenge#2','sci',3,2,'u3','L03','g3_2_sci_u3_L03_challenge','lesson_challenge','SC3-2-u3-C5',2,'mc','auto','멀리 있는 친구를 부를 때 내는 소리로 알맞은 것은 무엇인가요?',ARRAY['SC3-2-u3-X12']::text[],false,'{"seq":2,"concept":"SC3-2-u3-C5","difficulty":2,"kind":"mc","stem":"멀리 있는 친구를 부를 때 내는 소리로 알맞은 것은 무엇인가요?","options":[{"t":"큰 소리","correct":true},{"t":"작은 소리","mis":"SC3-2-u3-X12"},{"t":"귓속말","mis":"SC3-2-u3-X12"},{"t":"소리를 내지 않는다","mis":"SC3-2-u3-X12"}],"explanation":["멀리까지 들려야 해요.","크게 불러요.","큰 소리예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L03_challenge#3','sci',3,2,'u3','L03','g3_2_sci_u3_L03_challenge','lesson_challenge','SC3-2-u3-C6',3,'error','auto','작은북 실험을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-2-u3-X14','SC3-2-u3-X15','SC3-2-u3-X11']::text[],false,'{"seq":3,"concept":"SC3-2-u3-C6","difficulty":3,"kind":"error","stem":"작은북 실험을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「약하게 친 북은 떨리지 않는데 소리만 났어.」","correct":true,"mis_target":"SC3-2-u3-X14"},{"t":"친구 가 — 「세게 치니 퐁퐁이가 높게 튀어 올랐어.」","mis":"SC3-2-u3-X15"},{"t":"친구 다 — 「디지털 탐구 도구로 크고 작은 정도를 견줄 수 있어.」","mis":"SC3-2-u3-X11"}],"explanation":["약하게 칠 때를 떠올려요.","작게 떨려요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L03_challenge#4','sci',3,2,'u3','L03','g3_2_sci_u3_L03_challenge','lesson_challenge','SC3-2-u3-C6',3,'mc','auto','작은북 실험 기록에서 ㉯를 바르게 설명한 것은 무엇인가요?',ARRAY['SC3-2-u3-X13','SC3-2-u3-X14','SC3-2-u3-X15']::text[],false,'{"seq":4,"concept":"SC3-2-u3-C6","difficulty":3,"kind":"mc","stem":"작은북 실험 기록에서 ㉯를 바르게 설명한 것은 무엇인가요?","options":[{"t":"북면이 작게 떨려 작은 소리가 났다","correct":true},{"t":"북면이 크게 떨려 큰 소리가 났다","mis":"SC3-2-u3-X13"},{"t":"북면이 떨리지 않아 퐁퐁이가 낮게 튀었다","mis":"SC3-2-u3-X14"},{"t":"퐁퐁이가 낮게 튀었으니 세게 친 것이다","mis":"SC3-2-u3-X15"}],"explanation":["㉯ 줄을 읽어요.","약하게 쳤어요.","작게 떨려 작은 소리가 났어요."],"asset":{"type":"passage","lines":["㉮ 북채로 세게 쳤어요 — 퐁퐁이가 높게 튀어 올랐어요.","㉯ 북채로 약하게 쳤어요 — 퐁퐁이가 낮게 튀어 올랐어요.","디지털 탐구 도구 — ㉮는 큰 소리, ㉯는 작은 소리로 나왔어요."],"title":"작은북 실험 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L03_challenge#5','sci',3,2,'u3','L03','g3_2_sci_u3_L03_challenge','lesson_challenge','SC3-2-u3-C5',3,'mc','auto','여러 가지 소리를 「큰 소리가 나는 경우인가?」로 나누었어요. ⭕ 쪽에 들어가는 것끼리 묶은 것은 무엇인가요?',ARRAY['SC3-2-u3-X12']::text[],false,'{"seq":5,"concept":"SC3-2-u3-C5","difficulty":3,"kind":"mc","stem":"여러 가지 소리를 「큰 소리가 나는 경우인가?」로 나누었어요. ⭕ 쪽에 들어가는 것끼리 묶은 것은 무엇인가요?","options":[{"t":"운동회 응원 소리, 폭죽 소리","correct":true},{"t":"친구에게 하는 귓속말, 폭죽 소리","mis":"SC3-2-u3-X12"},{"t":"아기에게 불러 주는 자장가, 응원 소리","mis":"SC3-2-u3-X12"},{"t":"귓속말, 자장가","mis":"SC3-2-u3-X12"}],"explanation":["큰 소리를 찾아요.","귓속말과 자장가는 작아요.","응원 소리와 폭죽 소리예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L03_challenge#6','sci',3,2,'u3','L03','g3_2_sci_u3_L03_challenge','lesson_challenge','SC3-2-u3-C5',3,'match','auto','소리와 그렇게 내는 까닭을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SC3-2-u3-C5","difficulty":3,"kind":"match","stem":"소리와 그렇게 내는 까닭을 알맞게 이으세요.","pairs":[{"l":"발표할 때 큰 소리","r":"친구들 모두 들어야 해요"},{"l":"귓속말할 때 작은 소리","r":"옆 친구만 들으면 돼요"},{"l":"자장가를 작은 소리로","r":"아기가 편히 자야 해요"}],"mis":"SC3-2-u3-X12","explanation":["누가 들어야 하나요?","모두 들어야 하면 커요.","발표-모두, 귓속말-옆 친구, 자장가-아기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L03_challenge#7','sci',3,2,'u3','L03','g3_2_sci_u3_L03_challenge','lesson_challenge','SC3-2-u3-C6',3,'ox','auto','작은 소리가 나는 물체는 떨림이 없어요.',ARRAY['SC3-2-u3-X14']::text[],false,'{"seq":7,"concept":"SC3-2-u3-C6","difficulty":3,"kind":"ox","stem":"작은 소리가 나는 물체는 떨림이 없어요.","answer":"X","reason_options":[{"t":"작은 소리가 날 때도 물체가 작게 떨리기 때문에","correct":true},{"t":"떨림은 큰 소리에만 있기 때문에","mis":"SC3-2-u3-X14"}],"mis":"SC3-2-u3-X14","explanation":["약하게 친 북을 떠올려요.","작게 떨려요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L03_challenge#8','sci',3,2,'u3','L03','g3_2_sci_u3_L03_challenge','lesson_challenge','SC3-2-u3-C6',4,'mc','auto','작은북으로 큰 소리와 작은 소리를 견주는 실험에서 가장 알맞은 방법은 무엇인가요?',ARRAY['SC3-2-u3-X16','SC3-2-u3-X15']::text[],false,'{"seq":8,"concept":"SC3-2-u3-C6","difficulty":4,"kind":"mc","stem":"작은북으로 큰 소리와 작은 소리를 견주는 실험에서 가장 알맞은 방법은 무엇인가요?","options":[{"t":"같은 북을 한 번은 세게, 한 번은 약하게 쳐서 퐁퐁이가 튀는 높이를 견준다","correct":true},{"t":"북채로 북 옆 책상과 의자까지 힘껏 쳐 본다","mis":"SC3-2-u3-X16"},{"t":"귀를 북에 바짝 대고 있는 힘껏 친다","mis":"SC3-2-u3-X16"},{"t":"세게 칠 때 퐁퐁이가 낮게 튀는지 살펴본다","mis":"SC3-2-u3-X15"}],"explanation":["같은 북으로 견줘요.","귀를 지켜요.","세게·약하게 쳐서 견줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L03_challenge#9','sci',3,2,'u3','L03','g3_2_sci_u3_L03_challenge','lesson_challenge','SC3-2-u3-C6',4,'mc','auto','친구가 「심벌즈를 세게 쳤더니 작게 떨리면서 큰 소리가 났어.」라고 말했어요. 바르게 고친 말은 무엇인가요?',ARRAY['SC3-2-u3-X13','SC3-2-u3-X14']::text[],false,'{"seq":9,"concept":"SC3-2-u3-C6","difficulty":4,"kind":"mc","stem":"친구가 「심벌즈를 세게 쳤더니 작게 떨리면서 큰 소리가 났어.」라고 말했어요. 바르게 고친 말은 무엇인가요?","options":[{"t":"「심벌즈를 세게 쳤더니 크게 떨리면서 큰 소리가 났어.」","correct":true},{"t":"「심벌즈를 세게 쳤더니 작게 떨리면서 작은 소리가 났어.」","mis":"SC3-2-u3-X13"},{"t":"「심벌즈를 세게 쳤더니 떨리지 않고 큰 소리가 났어.」","mis":"SC3-2-u3-X14"},{"t":"「심벌즈를 약하게 쳤더니 크게 떨리면서 큰 소리가 났어.」","mis":"SC3-2-u3-X13"}],"explanation":["세게 치면 떨림은?","크게 떨려요.","크게 떨리며 큰 소리예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L03_challenge#10','sci',3,2,'u3','L03','g3_2_sci_u3_L03_challenge','lesson_challenge','SC3-2-u3-C6',4,'essay','teacher','작은북 실험 기록을 보고 북을 치는 세기, 북면의 떨림, 소리의 크기를 이어 쓰고, 실험할 때 지킬 약속 한 가지를 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC3-2-u3-C6","difficulty":4,"kind":"essay","stem":"작은북 실험 기록을 보고 북을 치는 세기, 북면의 떨림, 소리의 크기를 이어 쓰고, 실험할 때 지킬 약속 한 가지를 쓰세요.","answer_guide":{"answer":"예: 북을 세게 치면 북면이 크게 떨려 퐁퐁이가 높게 튀고 큰 소리가 난다. 약하게 치면 북면이 작게 떨려 퐁퐁이가 낮게 튀고 작은 소리가 난다. 지나치게 큰 소리는 귀를 다치게 할 수 있으니 너무 세게 치지 않는다.","scoring_points":["세게 칠 때 떨림과 소리를 썼는가","약하게 칠 때 떨림과 소리를 썼는가","귀를 지키는 약속을 썼는가"]},"explanation":["㉮와 ㉯를 견줘요.","떨림과 이어요.","약속을 써요."],"asset":{"type":"passage","lines":["㉮ 북채로 세게 쳤어요 — 퐁퐁이가 높게 튀어 올랐어요.","㉯ 북채로 약하게 쳤어요 — 퐁퐁이가 낮게 튀어 올랐어요.","디지털 탐구 도구 — ㉮는 큰 소리, ㉯는 작은 소리로 나왔어요."],"title":"작은북 실험 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L04_basic#1','sci',3,2,'u3','L04','g3_2_sci_u3_L04_basic','lesson_basic','SC3-2-u3-C7',1,'mc','auto','소리의 높고 낮은 정도를 무엇이라고 하나요?',ARRAY['SC3-2-u3-X17']::text[],false,'{"seq":1,"concept":"SC3-2-u3-C7","difficulty":1,"kind":"mc","stem":"소리의 높고 낮은 정도를 무엇이라고 하나요?","options":[{"t":"소리의 높낮이","correct":true},{"t":"소리의 세기","mis":"SC3-2-u3-X17"},{"t":"소리의 떨림","mis":"SC3-2-u3-X17"},{"t":"소리의 빠르기","mis":"SC3-2-u3-X17"}],"explanation":["높고 낮은 정도예요.","크고 작은 정도와 달라요.","소리의 높낮이예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L04_basic#2','sci',3,2,'u3','L04','g3_2_sci_u3_L04_basic','lesson_basic','SC3-2-u3-C8',1,'sa','auto','글로켄슈필의 짧은 음판과 긴 음판 가운데 더 높은 소리가 나는 음판은 무엇인가요? 「짧은」 또는 「긴」으로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC3-2-u3-C8","difficulty":1,"kind":"sa","stem":"글로켄슈필의 짧은 음판과 긴 음판 가운데 더 높은 소리가 나는 음판은 무엇인가요? 「짧은」 또는 「긴」으로 쓰세요.","answer":["짧은","짧은 음판"],"explanation":["길이를 견줘요.","짧으면 높아요.","짧은 음판이에요."],"mis":"SC3-2-u3-X19"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L04_basic#3','sci',3,2,'u3','L04','g3_2_sci_u3_L04_basic','lesson_basic','SC3-2-u3-C8',1,'ox','auto','팬 플루트의 긴 관을 불면 낮은 소리가 나요.',ARRAY['SC3-2-u3-X19']::text[],false,'{"seq":3,"concept":"SC3-2-u3-C8","difficulty":1,"kind":"ox","stem":"팬 플루트의 긴 관을 불면 낮은 소리가 나요.","answer":"O","reason_options":[{"t":"소리를 내는 물체가 길면 낮은 소리가 나기 때문에","correct":true},{"t":"긴 관일수록 높은 소리가 나기 때문에","mis":"SC3-2-u3-X19"}],"mis":"SC3-2-u3-X19","explanation":["관의 길이를 봐요.","길면 낮아요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L04_basic#4','sci',3,2,'u3','L04','g3_2_sci_u3_L04_basic','lesson_basic','SC3-2-u3-C7',1,'mc','auto','높은 소리가 나는 경우는 무엇인가요?',ARRAY['SC3-2-u3-X18']::text[],false,'{"seq":4,"concept":"SC3-2-u3-C7","difficulty":1,"kind":"mc","stem":"높은 소리가 나는 경우는 무엇인가요?","options":[{"t":"팬 플루트의 짧은 관을 불 때","correct":true},{"t":"팬 플루트의 긴 관을 불 때","mis":"SC3-2-u3-X18"},{"t":"긴 음판을 두드릴 때","mis":"SC3-2-u3-X18"},{"t":"고무줄을 길게 잡고 튕길 때","mis":"SC3-2-u3-X18"}],"explanation":["짧은 것을 찾아요.","짧으면 높아요.","짧은 관이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L04_basic#5','sci',3,2,'u3','L04','g3_2_sci_u3_L04_basic','lesson_basic','SC3-2-u3-C9',2,'match','auto','악기로 소리를 낸 방법과 달라진 소리를 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC3-2-u3-C9","difficulty":2,"kind":"match","stem":"악기로 소리를 낸 방법과 달라진 소리를 알맞게 이으세요.","pairs":[{"l":"고무줄을 짧게 잡고 튕기기","r":"높은 소리"},{"l":"긴 음판 두드리기","r":"낮은 소리"},{"l":"같은 음판을 세게 치기","r":"높낮이는 같고 세기만 커져요"}],"mis":"SC3-2-u3-X21","explanation":["길이를 먼저 봐요.","세게 치면 세기만 달라요.","짧게-높은, 긴-낮은, 세게-세기만이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L04_basic#6','sci',3,2,'u3','L04','g3_2_sci_u3_L04_basic','lesson_basic','SC3-2-u3-C8',2,'mc','auto','간이 악기 실험 기록에서 더 높은 소리가 난 것은 무엇인가요?',ARRAY['SC3-2-u3-X19','SC3-2-u3-X22','SC3-2-u3-X20']::text[],false,'{"seq":6,"concept":"SC3-2-u3-C8","difficulty":2,"kind":"mc","stem":"간이 악기 실험 기록에서 더 높은 소리가 난 것은 무엇인가요?","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"SC3-2-u3-X19"},{"t":"둘 다 같아요","mis":"SC3-2-u3-X22"},{"t":"알 수 없어요","mis":"SC3-2-u3-X20"}],"explanation":["자 가운데를 누르면 튕기는 고무줄이 짧아요.","짧으면 높아요.","㉮예요."],"asset":{"type":"passage","lines":["㉮ 자 가운데를 누르고 고무줄 아랫부분을 튕겼어요.","㉯ 자 윗부분을 누르고 고무줄 아랫부분을 튕겼어요.","약속 — 두 번 모두 같은 세기로 튕겼어요."],"title":"간이 악기 실험 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L04_basic#7','sci',3,2,'u3','L04','g3_2_sci_u3_L04_basic','lesson_basic','SC3-2-u3-C9',2,'mc','auto','같은 음판을 더 세게 치면 소리는 어떻게 될까요?',ARRAY['SC3-2-u3-X21','SC3-2-u3-X22']::text[],false,'{"seq":7,"concept":"SC3-2-u3-C9","difficulty":2,"kind":"mc","stem":"같은 음판을 더 세게 치면 소리는 어떻게 될까요?","options":[{"t":"높낮이는 같고 소리만 커진다","correct":true},{"t":"소리가 더 높아진다","mis":"SC3-2-u3-X21"},{"t":"소리가 더 낮아진다","mis":"SC3-2-u3-X21"},{"t":"소리가 더 작아진다","mis":"SC3-2-u3-X22"}],"explanation":["같은 음판이에요.","길이는 그대로예요.","세기만 커져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L04_basic#8','sci',3,2,'u3','L04','g3_2_sci_u3_L04_basic','lesson_basic','SC3-2-u3-C8',2,'blank','auto','「소리의 높낮이는 소리가 나는 물체의 (    )에 따라 달라져요. 짧으면 높고, 길면 낮아요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC3-2-u3-X19','SC3-2-u3-X22']::text[],false,'{"seq":8,"concept":"SC3-2-u3-C8","difficulty":2,"kind":"blank","stem":"「소리의 높낮이는 소리가 나는 물체의 (    )에 따라 달라져요. 짧으면 높고, 길면 낮아요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"길이","correct":true},{"t":"색깔","mis":"SC3-2-u3-X19"},{"t":"무게","mis":"SC3-2-u3-X19"},{"t":"떨림의 크기","mis":"SC3-2-u3-X22"}],"explanation":["짧고 긴 것을 말해요.","음판을 떠올려요.","길이예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L04_basic#9','sci',3,2,'u3','L04','g3_2_sci_u3_L04_basic','lesson_basic','SC3-2-u3-C9',2,'ox','auto','소리의 세기와 소리의 높낮이는 같은 뜻이에요.',ARRAY['SC3-2-u3-X22']::text[],false,'{"seq":9,"concept":"SC3-2-u3-C9","difficulty":2,"kind":"ox","stem":"소리의 세기와 소리의 높낮이는 같은 뜻이에요.","answer":"X","reason_options":[{"t":"세기는 크고 작은 정도, 높낮이는 높고 낮은 정도이기 때문에","correct":true},{"t":"큰 소리는 언제나 높은 소리이기 때문에","mis":"SC3-2-u3-X22"}],"mis":"SC3-2-u3-X22","explanation":["두 뜻을 견줘요.","크고 작은 정도와 높고 낮은 정도예요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L04_basic#10','sci',3,2,'u3','L04','g3_2_sci_u3_L04_basic','lesson_basic','SC3-2-u3-C8',3,'mc','auto','간이 악기로 높낮이를 견줄 때 고무줄을 튕기는 방법으로 알맞은 것은 무엇인가요?',ARRAY['SC3-2-u3-X20']::text[],false,'{"seq":10,"concept":"SC3-2-u3-C8","difficulty":3,"kind":"mc","stem":"간이 악기로 높낮이를 견줄 때 고무줄을 튕기는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"두 번 모두 같은 세기로 튕긴다","correct":true},{"t":"높은 소리를 낼 때만 세게 튕긴다","mis":"SC3-2-u3-X20"},{"t":"낮은 소리를 낼 때만 세게 튕긴다","mis":"SC3-2-u3-X20"},{"t":"튕길 때마다 세기를 마음대로 바꾼다","mis":"SC3-2-u3-X20"}],"explanation":["높낮이만 견줘요.","세기는 같게 해요.","같은 세기로 튕겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L04_challenge#1','sci',3,2,'u3','L04','g3_2_sci_u3_L04_challenge','lesson_challenge','SC3-2-u3-C7',2,'sa','auto','피아노 줄을 하나하나 소리 내 보고 알맞은 높낮이의 소리가 나도록 맞추는 사람을 「피아노 ○○○」라고 해요. ○○○에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SC3-2-u3-C7","difficulty":2,"kind":"sa","stem":"피아노 줄을 하나하나 소리 내 보고 알맞은 높낮이의 소리가 나도록 맞추는 사람을 「피아노 ○○○」라고 해요. ○○○에 알맞은 말을 쓰세요.","answer":["조율사"],"explanation":["피아노 소리를 맞춰요.","조◯◯예요.","조율사예요."],"mis":"SC3-2-u3-X17"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L04_challenge#2','sci',3,2,'u3','L04','g3_2_sci_u3_L04_challenge','lesson_challenge','SC3-2-u3-C8',2,'mc','auto','보라색 음판이 초록색 음판보다 짧아요. 더 높은 소리가 나는 음판은 무엇인가요?',ARRAY['SC3-2-u3-X19','SC3-2-u3-X21']::text[],false,'{"seq":2,"concept":"SC3-2-u3-C8","difficulty":2,"kind":"mc","stem":"보라색 음판이 초록색 음판보다 짧아요. 더 높은 소리가 나는 음판은 무엇인가요?","options":[{"t":"보라색 음판","correct":true},{"t":"초록색 음판","mis":"SC3-2-u3-X19"},{"t":"둘 다 같아요","mis":"SC3-2-u3-X19"},{"t":"더 세게 친 음판","mis":"SC3-2-u3-X21"}],"explanation":["길이를 견줘요.","짧으면 높아요.","보라색 음판이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L04_challenge#3','sci',3,2,'u3','L04','g3_2_sci_u3_L04_challenge','lesson_challenge','SC3-2-u3-C9',3,'error','auto','소리의 높낮이를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-2-u3-X21','SC3-2-u3-X19','SC3-2-u3-X18']::text[],false,'{"seq":3,"concept":"SC3-2-u3-C9","difficulty":3,"kind":"error","stem":"소리의 높낮이를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「같은 음판도 세게 치면 더 높은 소리가 나.」","correct":true,"mis_target":"SC3-2-u3-X21"},{"t":"친구 나 — 「짧은 관을 불면 높은 소리가 나.」","mis":"SC3-2-u3-X19"},{"t":"친구 다 — 「긴 음판을 치면 낮은 소리가 나.」","mis":"SC3-2-u3-X18"}],"explanation":["같은 음판이에요.","세게 치면 세기만 커져요.","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L04_challenge#4','sci',3,2,'u3','L04','g3_2_sci_u3_L04_challenge','lesson_challenge','SC3-2-u3-C9',3,'mc','auto','무엇이 달라졌는지 바르게 말한 것은 무엇인가요?',ARRAY['SC3-2-u3-X22']::text[],false,'{"seq":4,"concept":"SC3-2-u3-C9","difficulty":3,"kind":"mc","stem":"무엇이 달라졌는지 바르게 말한 것은 무엇인가요?","options":[{"t":"더 짧은 음판을 치면 높낮이가 달라진다","correct":true},{"t":"북을 더 세게 치면 높낮이가 달라진다","mis":"SC3-2-u3-X22"},{"t":"귓속말로 이야기하면 높낮이가 달라진다","mis":"SC3-2-u3-X22"},{"t":"긴 관을 불면 세기만 달라진다","mis":"SC3-2-u3-X22"}],"explanation":["길이가 달라지면?","높낮이가 달라요.","짧은 음판이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L04_challenge#5','sci',3,2,'u3','L04','g3_2_sci_u3_L04_challenge','lesson_challenge','SC3-2-u3-C8',3,'mc','auto','간이 악기 실험 기록에서 ㉯의 소리를 바르게 설명한 것은 무엇인가요?',ARRAY['SC3-2-u3-X19','SC3-2-u3-X20','SC3-2-u3-X18']::text[],false,'{"seq":5,"concept":"SC3-2-u3-C8","difficulty":3,"kind":"mc","stem":"간이 악기 실험 기록에서 ㉯의 소리를 바르게 설명한 것은 무엇인가요?","options":[{"t":"튕기는 고무줄이 길어 ㉮보다 낮은 소리가 났다","correct":true},{"t":"튕기는 고무줄이 길어 ㉮보다 높은 소리가 났다","mis":"SC3-2-u3-X19"},{"t":"㉮보다 세게 튕겨서 낮은 소리가 났다","mis":"SC3-2-u3-X20"},{"t":"㉮와 같은 높낮이의 소리가 났다","mis":"SC3-2-u3-X18"}],"explanation":["자 윗부분을 눌렀어요.","튕기는 부분이 길어요.","낮은 소리가 났어요."],"asset":{"type":"passage","lines":["㉮ 자 가운데를 누르고 고무줄 아랫부분을 튕겼어요.","㉯ 자 윗부분을 누르고 고무줄 아랫부분을 튕겼어요.","약속 — 두 번 모두 같은 세기로 튕겼어요."],"title":"간이 악기 실험 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L04_challenge#6','sci',3,2,'u3','L04','g3_2_sci_u3_L04_challenge','lesson_challenge','SC3-2-u3-C7',3,'match','auto','기타 줄을 튕긴 방법과 나는 소리를 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SC3-2-u3-C7","difficulty":3,"kind":"match","stem":"기타 줄을 튕긴 방법과 나는 소리를 알맞게 이으세요.","pairs":[{"l":"기타 줄을 짧게 잡고 튕기기","r":"높은 소리"},{"l":"기타 줄을 길게 잡고 튕기기","r":"낮은 소리"},{"l":"같은 자리를 잡고 세게 튕기기","r":"더 큰 소리"}],"mis":"SC3-2-u3-X18","explanation":["길이와 세기를 나눠 봐요.","짧으면 높아요.","짧게-높은, 길게-낮은, 세게-큰 소리예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L04_challenge#7','sci',3,2,'u3','L04','g3_2_sci_u3_L04_challenge','lesson_challenge','SC3-2-u3-C8',3,'ox','auto','고무줄을 길게 잡고 튕길수록 더 높은 소리가 나요.',ARRAY['SC3-2-u3-X19']::text[],false,'{"seq":7,"concept":"SC3-2-u3-C8","difficulty":3,"kind":"ox","stem":"고무줄을 길게 잡고 튕길수록 더 높은 소리가 나요.","answer":"X","reason_options":[{"t":"튕기는 고무줄이 길수록 낮은 소리가 나기 때문에","correct":true},{"t":"긴 물체일수록 높은 소리가 나기 때문에","mis":"SC3-2-u3-X19"}],"mis":"SC3-2-u3-X19","explanation":["길이를 봐요.","길면 낮아요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L04_challenge#8','sci',3,2,'u3','L04','g3_2_sci_u3_L04_challenge','lesson_challenge','SC3-2-u3-C8',4,'mc','auto','칼림바의 음판은 길이가 서로 달라요. 가장 낮은 소리를 내려면 어느 음판을 쳐야 하나요?',ARRAY['SC3-2-u3-X19','SC3-2-u3-X21','SC3-2-u3-X22']::text[],false,'{"seq":8,"concept":"SC3-2-u3-C8","difficulty":4,"kind":"mc","stem":"칼림바의 음판은 길이가 서로 달라요. 가장 낮은 소리를 내려면 어느 음판을 쳐야 하나요?","options":[{"t":"가장 긴 음판","correct":true},{"t":"가장 짧은 음판","mis":"SC3-2-u3-X19"},{"t":"가운데 음판을 아주 세게","mis":"SC3-2-u3-X21"},{"t":"아무 음판이나 약하게","mis":"SC3-2-u3-X22"}],"explanation":["낮은 소리예요.","길면 낮아요.","가장 긴 음판이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L04_challenge#9','sci',3,2,'u3','L04','g3_2_sci_u3_L04_challenge','lesson_challenge','SC3-2-u3-C9',4,'mc','auto','「팬 플루트의 짧은 관을 세게 불었더니 큰 소리가 났어.」 이 말에서 높낮이와 세기를 바르게 정리한 것은 무엇인가요?',ARRAY['SC3-2-u3-X22','SC3-2-u3-X19']::text[],false,'{"seq":9,"concept":"SC3-2-u3-C9","difficulty":4,"kind":"mc","stem":"「팬 플루트의 짧은 관을 세게 불었더니 큰 소리가 났어.」 이 말에서 높낮이와 세기를 바르게 정리한 것은 무엇인가요?","options":[{"t":"짧은 관이라 높은 소리이고, 세게 불어서 큰 소리이다","correct":true},{"t":"세게 불었으니 높은 소리이고, 짧은 관이라 큰 소리이다","mis":"SC3-2-u3-X22"},{"t":"짧은 관이라 낮은 소리이고, 세게 불어서 큰 소리이다","mis":"SC3-2-u3-X19"},{"t":"세게 불어도 관이 짧으면 작은 소리만 난다","mis":"SC3-2-u3-X22"}],"explanation":["길이는 높낮이예요.","세게는 세기예요.","높고 큰 소리예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L04_challenge#10','sci',3,2,'u3','L04','g3_2_sci_u3_L04_challenge','lesson_challenge','SC3-2-u3-C8',4,'essay','teacher','간이 악기 실험 기록을 보고 ㉮와 ㉯ 가운데 높은 소리가 난 것을 까닭과 함께 쓰고, 두 번 모두 같은 세기로 튕긴 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC3-2-u3-C8","difficulty":4,"kind":"essay","stem":"간이 악기 실험 기록을 보고 ㉮와 ㉯ 가운데 높은 소리가 난 것을 까닭과 함께 쓰고, 두 번 모두 같은 세기로 튕긴 까닭을 쓰세요.","answer_guide":{"answer":"예: ㉮에서 더 높은 소리가 났다. 자 가운데를 누르면 튕기는 고무줄이 짧아져 높은 소리가 나기 때문이다. 같은 세기로 튕겨야 소리의 세기는 같게 하고 높낮이만 견줄 수 있다.","scoring_points":["높은 소리가 난 것을 바르게 골랐는가","고무줄 길이와 이어 까닭을 썼는가","같은 세기로 튕긴 까닭을 썼는가"]},"explanation":["누른 곳을 봐요.","길이와 이어요.","세기를 같게 한 까닭을 써요."],"asset":{"type":"passage","lines":["㉮ 자 가운데를 누르고 고무줄 아랫부분을 튕겼어요.","㉯ 자 윗부분을 누르고 고무줄 아랫부분을 튕겼어요.","약속 — 두 번 모두 같은 세기로 튕겼어요."],"title":"간이 악기 실험 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L05_basic#1','sci',3,2,'u3','L05','g3_2_sci_u3_L05_basic','lesson_basic','SC3-2-u3-C11',1,'mc','auto','빈 운동장에서 친구가 부르는 소리는 무엇을 통해 전달되나요?',ARRAY['SC3-2-u3-X25']::text[],false,'{"seq":1,"concept":"SC3-2-u3-C11","difficulty":1,"kind":"mc","stem":"빈 운동장에서 친구가 부르는 소리는 무엇을 통해 전달되나요?","options":[{"t":"공기","correct":true},{"t":"물","mis":"SC3-2-u3-X25"},{"t":"나무","mis":"SC3-2-u3-X25"},{"t":"실","mis":"SC3-2-u3-X25"}],"explanation":["운동장을 떠올려요.","우리 주위에 있어요.","공기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L05_basic#2','sci',3,2,'u3','L05','g3_2_sci_u3_L05_basic','lesson_basic','SC3-2-u3-C11',1,'sa','auto','종이컵 실 전화기에서 친구의 목소리를 전달하는 것을 한 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC3-2-u3-C11","difficulty":1,"kind":"sa","stem":"종이컵 실 전화기에서 친구의 목소리를 전달하는 것을 한 글자로 쓰세요.","answer":["실"],"explanation":["두 종이컵을 이어요.","고체예요.","실이에요."],"mis":"SC3-2-u3-X23"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L05_basic#3','sci',3,2,'u3','L05','g3_2_sci_u3_L05_basic','lesson_basic','SC3-2-u3-C10',1,'ox','auto','책상에 귀를 대면 친구가 책상을 두드리는 소리를 들을 수 있어요.',ARRAY['SC3-2-u3-X23']::text[],false,'{"seq":3,"concept":"SC3-2-u3-C10","difficulty":1,"kind":"ox","stem":"책상에 귀를 대면 친구가 책상을 두드리는 소리를 들을 수 있어요.","answer":"O","reason_options":[{"t":"소리가 고체인 책상을 통해 전달되기 때문에","correct":true},{"t":"소리는 공기로만 전달되기 때문에","mis":"SC3-2-u3-X23"}],"mis":"SC3-2-u3-X23","explanation":["책상에 귀를 대요.","책상이 소리를 전해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L05_basic#4','sci',3,2,'u3','L05','g3_2_sci_u3_L05_basic','lesson_basic','SC3-2-u3-C11',1,'mc','auto','공기가 없는 우주에서 목소리를 들을 수 없는 까닭은 무엇인가요?',ARRAY['SC3-2-u3-X26']::text[],false,'{"seq":4,"concept":"SC3-2-u3-C11","difficulty":1,"kind":"mc","stem":"공기가 없는 우주에서 목소리를 들을 수 없는 까닭은 무엇인가요?","options":[{"t":"소리를 전달하는 물질이 없어서","correct":true},{"t":"우주가 너무 추워서","mis":"SC3-2-u3-X26"},{"t":"우주가 깜깜해서","mis":"SC3-2-u3-X26"},{"t":"우주복이 무거워서","mis":"SC3-2-u3-X26"}],"explanation":["공기가 없어요.","전달할 물질을 떠올려요.","물질이 없어서예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L05_basic#5','sci',3,2,'u3','L05','g3_2_sci_u3_L05_basic','lesson_basic','SC3-2-u3-C11',2,'match','auto','소리를 전달한 물질과 그 상태를 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC3-2-u3-C11","difficulty":2,"kind":"match","stem":"소리를 전달한 물질과 그 상태를 알맞게 이으세요.","pairs":[{"l":"실 전화기의 실","r":"고체"},{"l":"수조의 물","r":"액체"},{"l":"교실의 공기","r":"기체"}],"mis":"SC3-2-u3-X25","explanation":["물질의 상태를 떠올려요.","실은 단단해요.","실-고체, 물-액체, 공기-기체예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L05_basic#6','sci',3,2,'u3','L05','g3_2_sci_u3_L05_basic','lesson_basic','SC3-2-u3-C10',2,'mc','auto','소리를 들은 경험에서 액체를 통해 소리가 전달된 것은 무엇인가요?',ARRAY['SC3-2-u3-X25']::text[],false,'{"seq":6,"concept":"SC3-2-u3-C10","difficulty":2,"kind":"mc","stem":"소리를 들은 경험에서 액체를 통해 소리가 전달된 것은 무엇인가요?","options":[{"t":"㉡","correct":true},{"t":"㉠","mis":"SC3-2-u3-X25"},{"t":"㉢","mis":"SC3-2-u3-X25"},{"t":"㉣","mis":"SC3-2-u3-X25"}],"explanation":["액체를 찾아요.","물속 스피커예요.","㉡이에요."],"asset":{"type":"passage","lines":["㉠ 책상에 귀를 대고 친구가 두드리는 소리를 들었어요.","㉡ 물속 방수 스피커 소리를 관으로 들었어요.","㉢ 종이컵 실 전화기로 친구 목소리를 들었어요.","㉣ 빈 운동장에서 친구가 부르는 소리를 들었어요."],"title":"소리를 들은 경험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L05_basic#7','sci',3,2,'u3','L05','g3_2_sci_u3_L05_basic','lesson_basic','SC3-2-u3-C10',2,'mc','auto','책상에 귀를 대고 두드리는 소리를 들을 때 알맞은 방법은 무엇인가요?',ARRAY['SC3-2-u3-X24']::text[],false,'{"seq":7,"concept":"SC3-2-u3-C10","difficulty":2,"kind":"mc","stem":"책상에 귀를 대고 두드리는 소리를 들을 때 알맞은 방법은 무엇인가요?","options":[{"t":"반대쪽 귀를 손으로 막는다","correct":true},{"t":"양쪽 귀를 모두 연다","mis":"SC3-2-u3-X24"},{"t":"귀를 책상에서 떼고 듣는다","mis":"SC3-2-u3-X24"},{"t":"친구에게 크게 말해 달라고 한다","mis":"SC3-2-u3-X24"}],"explanation":["책상으로 오는 소리만 들어요.","공기로 오는 소리를 막아요.","반대쪽 귀를 막아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L05_basic#8','sci',3,2,'u3','L05','g3_2_sci_u3_L05_basic','lesson_basic','SC3-2-u3-C11',2,'blank','auto','「우리가 듣는 대부분의 소리는 기체인 (    )를 통해 전달돼요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC3-2-u3-X25']::text[],false,'{"seq":8,"concept":"SC3-2-u3-C11","difficulty":2,"kind":"blank","stem":"「우리가 듣는 대부분의 소리는 기체인 (    )를 통해 전달돼요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"공기","correct":true},{"t":"물","mis":"SC3-2-u3-X25"},{"t":"책상","mis":"SC3-2-u3-X25"},{"t":"실","mis":"SC3-2-u3-X25"}],"explanation":["기체를 찾아요.","교실에도 있어요.","공기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L05_basic#9','sci',3,2,'u3','L05','g3_2_sci_u3_L05_basic','lesson_basic','SC3-2-u3-C11',2,'ox','auto','소리는 기체를 통해서만 전달돼요.',ARRAY['SC3-2-u3-X23']::text[],false,'{"seq":9,"concept":"SC3-2-u3-C11","difficulty":2,"kind":"ox","stem":"소리는 기체를 통해서만 전달돼요.","answer":"X","reason_options":[{"t":"고체, 액체, 기체 상태의 여러 가지 물질을 통해 전달되기 때문에","correct":true},{"t":"고체와 액체는 소리를 막기만 하기 때문에","mis":"SC3-2-u3-X23"}],"mis":"SC3-2-u3-X23","explanation":["책상과 물을 떠올려요.","고체와 액체도 전해요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L05_basic#10','sci',3,2,'u3','L05','g3_2_sci_u3_L05_basic','lesson_basic','SC3-2-u3-C11',3,'mc','auto','바닷속 잠수부에게 배 소리를 전달하는 물질의 상태는 무엇인가요?',ARRAY['SC3-2-u3-X25','SC3-2-u3-X23','SC3-2-u3-X26']::text[],false,'{"seq":10,"concept":"SC3-2-u3-C11","difficulty":3,"kind":"mc","stem":"바닷속 잠수부에게 배 소리를 전달하는 물질의 상태는 무엇인가요?","options":[{"t":"액체","correct":true},{"t":"고체","mis":"SC3-2-u3-X25"},{"t":"기체","mis":"SC3-2-u3-X23"},{"t":"전달되지 않는다","mis":"SC3-2-u3-X26"}],"explanation":["바닷속이에요.","바닷물을 떠올려요.","액체예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L05_challenge#1','sci',3,2,'u3','L05','g3_2_sci_u3_L05_challenge','lesson_challenge','SC3-2-u3-C10',2,'sa','auto','물속 방수 스피커 실험에서 소리를 전달한 액체를 한 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SC3-2-u3-C10","difficulty":2,"kind":"sa","stem":"물속 방수 스피커 실험에서 소리를 전달한 액체를 한 글자로 쓰세요.","answer":["물"],"explanation":["수조에 담겨 있어요.","액체예요.","물이에요."],"mis":"SC3-2-u3-X23"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L05_challenge#2','sci',3,2,'u3','L05','g3_2_sci_u3_L05_challenge','lesson_challenge','SC3-2-u3-C11',2,'mc','auto','소리를 들은 경험에서 기체를 통해 소리가 전달된 것은 무엇인가요?',ARRAY['SC3-2-u3-X25']::text[],false,'{"seq":2,"concept":"SC3-2-u3-C11","difficulty":2,"kind":"mc","stem":"소리를 들은 경험에서 기체를 통해 소리가 전달된 것은 무엇인가요?","options":[{"t":"㉣","correct":true},{"t":"㉠","mis":"SC3-2-u3-X25"},{"t":"㉡","mis":"SC3-2-u3-X25"},{"t":"㉢","mis":"SC3-2-u3-X25"}],"explanation":["기체는 공기예요.","운동장에서 들었어요.","㉣이에요."],"asset":{"type":"passage","lines":["㉠ 책상에 귀를 대고 친구가 두드리는 소리를 들었어요.","㉡ 물속 방수 스피커 소리를 관으로 들었어요.","㉢ 종이컵 실 전화기로 친구 목소리를 들었어요.","㉣ 빈 운동장에서 친구가 부르는 소리를 들었어요."],"title":"소리를 들은 경험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L05_challenge#3','sci',3,2,'u3','L05','g3_2_sci_u3_L05_challenge','lesson_challenge','SC3-2-u3-C11',3,'error','auto','소리의 전달을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-2-u3-X26','SC3-2-u3-X25','SC3-2-u3-X23']::text[],false,'{"seq":3,"concept":"SC3-2-u3-C11","difficulty":3,"kind":"error","stem":"소리의 전달을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「우주에서는 너무 추워서 목소리가 얼어붙어 안 들려.」","correct":true,"mis_target":"SC3-2-u3-X26"},{"t":"친구 가 — 「실 전화기는 고체인 실로 소리가 전달돼.」","mis":"SC3-2-u3-X25"},{"t":"친구 나 — 「물속에서도 소리가 전달돼.」","mis":"SC3-2-u3-X23"}],"explanation":["우주에는 공기가 없어요.","전달할 물질이 없어요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L05_challenge#4','sci',3,2,'u3','L05','g3_2_sci_u3_L05_challenge','lesson_challenge','SC3-2-u3-C11',3,'mc','auto','소리를 들은 경험 ㉠~㉣에서 고체를 통해 소리가 전달된 것끼리 묶은 것은 무엇인가요?',ARRAY['SC3-2-u3-X25']::text[],false,'{"seq":4,"concept":"SC3-2-u3-C11","difficulty":3,"kind":"mc","stem":"소리를 들은 경험 ㉠~㉣에서 고체를 통해 소리가 전달된 것끼리 묶은 것은 무엇인가요?","options":[{"t":"㉠, ㉢","correct":true},{"t":"㉡, ㉣","mis":"SC3-2-u3-X25"},{"t":"㉠, ㉡","mis":"SC3-2-u3-X25"},{"t":"㉢, ㉣","mis":"SC3-2-u3-X25"}],"explanation":["고체를 찾아요.","책상과 실이에요.","㉠, ㉢이에요."],"asset":{"type":"passage","lines":["㉠ 책상에 귀를 대고 친구가 두드리는 소리를 들었어요.","㉡ 물속 방수 스피커 소리를 관으로 들었어요.","㉢ 종이컵 실 전화기로 친구 목소리를 들었어요.","㉣ 빈 운동장에서 친구가 부르는 소리를 들었어요."],"title":"소리를 들은 경험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L05_challenge#5','sci',3,2,'u3','L05','g3_2_sci_u3_L05_challenge','lesson_challenge','SC3-2-u3-C10',3,'mc','auto','물속 방수 스피커 소리를 관으로 들었어요. 이때 소리는 무엇을 통해 전달되었나요?',ARRAY['SC3-2-u3-X23','SC3-2-u3-X26']::text[],false,'{"seq":5,"concept":"SC3-2-u3-C10","difficulty":3,"kind":"mc","stem":"물속 방수 스피커 소리를 관으로 들었어요. 이때 소리는 무엇을 통해 전달되었나요?","options":[{"t":"물과 관 속 공기","correct":true},{"t":"관 속 공기만","mis":"SC3-2-u3-X23"},{"t":"물만","mis":"SC3-2-u3-X23"},{"t":"아무것도 거치지 않았다","mis":"SC3-2-u3-X26"}],"explanation":["스피커는 물속에 있어요.","관 속에는 공기가 있어요.","물과 관 속 공기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L05_challenge#6','sci',3,2,'u3','L05','g3_2_sci_u3_L05_challenge','lesson_challenge','SC3-2-u3-C11',3,'match','auto','상황과 소리를 전달한 물질의 상태를 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SC3-2-u3-C11","difficulty":3,"kind":"match","stem":"상황과 소리를 전달한 물질의 상태를 알맞게 이으세요.","pairs":[{"l":"나무 책상을 두드리는 소리","r":"고체"},{"l":"바닷속 잠수부가 듣는 배 소리","r":"액체"},{"l":"하늘을 나는 새소리","r":"기체"}],"mis":"SC3-2-u3-X25","explanation":["무엇을 통해 왔나요?","바닷속은 물이에요.","책상-고체, 바닷물-액체, 공기-기체예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L05_challenge#7','sci',3,2,'u3','L05','g3_2_sci_u3_L05_challenge','lesson_challenge','SC3-2-u3-C10',3,'ox','auto','소리가 나는 곳에서 떨어져 있어도 소리를 들을 수 있는 것은 소리가 물질을 통해 전달되기 때문이에요.',ARRAY['SC3-2-u3-X26']::text[],false,'{"seq":7,"concept":"SC3-2-u3-C10","difficulty":3,"kind":"ox","stem":"소리가 나는 곳에서 떨어져 있어도 소리를 들을 수 있는 것은 소리가 물질을 통해 전달되기 때문이에요.","answer":"O","reason_options":[{"t":"공기, 물, 책상 같은 물질이 소리를 전달하기 때문에","correct":true},{"t":"소리는 아무것도 없어도 저절로 날아오기 때문에","mis":"SC3-2-u3-X26"}],"mis":"SC3-2-u3-X26","explanation":["떨어져 있어요.","물질이 전해 줘요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L05_challenge#8','sci',3,2,'u3','L05','g3_2_sci_u3_L05_challenge','lesson_challenge','SC3-2-u3-C11',4,'mc','auto','「소리를 전하는 물질인가?」로 나누었을 때 ⭕ 쪽에 들어가는 것끼리 묶은 것은 무엇인가요?',ARRAY['SC3-2-u3-X26','SC3-2-u3-X23']::text[],false,'{"seq":8,"concept":"SC3-2-u3-C11","difficulty":4,"kind":"mc","stem":"「소리를 전하는 물질인가?」로 나누었을 때 ⭕ 쪽에 들어가는 것끼리 묶은 것은 무엇인가요?","options":[{"t":"나무, 물, 공기","correct":true},{"t":"나무, 물, 텅 빈 우주","mis":"SC3-2-u3-X26"},{"t":"공기, 텅 빈 우주","mis":"SC3-2-u3-X26"},{"t":"공기만","mis":"SC3-2-u3-X23"}],"explanation":["물질을 찾아요.","텅 빈 우주는 물질이 없어요.","나무, 물, 공기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L05_challenge#9','sci',3,2,'u3','L05','g3_2_sci_u3_L05_challenge','lesson_challenge','SC3-2-u3-C10',4,'mc','auto','책상 실험과 물속 스피커 실험을 함께 보고 내린 결론으로 가장 알맞은 것은 무엇인가요?',ARRAY['SC3-2-u3-X23','SC3-2-u3-X25','SC3-2-u3-X26']::text[],false,'{"seq":9,"concept":"SC3-2-u3-C10","difficulty":4,"kind":"mc","stem":"책상 실험과 물속 스피커 실험을 함께 보고 내린 결론으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"소리는 고체와 액체를 통해서도 전달된다","correct":true},{"t":"소리는 공기를 통해서만 전달된다","mis":"SC3-2-u3-X23"},{"t":"소리는 책상을 통해서만 전달된다","mis":"SC3-2-u3-X25"},{"t":"소리는 물질이 없어도 전달된다","mis":"SC3-2-u3-X26"}],"explanation":["두 실험을 견줘요.","책상과 물이에요.","고체와 액체도 전해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L05_challenge#10','sci',3,2,'u3','L05','g3_2_sci_u3_L05_challenge','lesson_challenge','SC3-2-u3-C11',4,'essay','teacher','소리를 들은 경험 ㉠~㉣에서 소리를 전달한 물질을 고체·액체·기체로 나누어 쓰고, 우주에서 목소리를 들을 수 없는 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC3-2-u3-C11","difficulty":4,"kind":"essay","stem":"소리를 들은 경험 ㉠~㉣에서 소리를 전달한 물질을 고체·액체·기체로 나누어 쓰고, 우주에서 목소리를 들을 수 없는 까닭을 쓰세요.","answer_guide":{"answer":"예: ㉠ 책상과 ㉢ 실은 고체, ㉡ 물은 액체, ㉣ 공기는 기체를 통해 소리가 전달되었다. 우주에는 소리를 전달할 물질이 없어서 목소리를 들을 수 없다.","scoring_points":["고체를 통해 전달된 경험을 바르게 골랐는가","액체와 기체를 통해 전달된 경험을 바르게 골랐는가","우주에서 들을 수 없는 까닭을 썼는가"]},"explanation":["넷을 하나씩 봐요.","상태로 나눠요.","우주의 까닭을 써요."],"asset":{"type":"passage","lines":["㉠ 책상에 귀를 대고 친구가 두드리는 소리를 들었어요.","㉡ 물속 방수 스피커 소리를 관으로 들었어요.","㉢ 종이컵 실 전화기로 친구 목소리를 들었어요.","㉣ 빈 운동장에서 친구가 부르는 소리를 들었어요."],"title":"소리를 들은 경험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L06_basic#1','sci',3,2,'u3','L06','g3_2_sci_u3_L06_basic','lesson_basic','SC3-2-u3-C12',1,'mc','auto','사람에게 불쾌감이나 고통을 주는 소리를 무엇이라고 하나요?',ARRAY['SC3-2-u3-X27']::text[],false,'{"seq":1,"concept":"SC3-2-u3-C12","difficulty":1,"kind":"mc","stem":"사람에게 불쾌감이나 고통을 주는 소리를 무엇이라고 하나요?","options":[{"t":"소음","correct":true},{"t":"음악","mis":"SC3-2-u3-X27"},{"t":"떨림","mis":"SC3-2-u3-X27"},{"t":"높낮이","mis":"SC3-2-u3-X27"}],"explanation":["불편한 소리예요.","소◯이에요.","소음이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L06_basic#2','sci',3,2,'u3','L06','g3_2_sci_u3_L06_basic','lesson_basic','SC3-2-u3-C12',1,'sa','auto','불쾌감이나 고통을 주는 소리를 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC3-2-u3-C12","difficulty":1,"kind":"sa","stem":"불쾌감이나 고통을 주는 소리를 두 글자로 쓰세요.","answer":["소음"],"explanation":["시끄러워 불편해요.","소◯이에요.","소음이에요."],"mis":"SC3-2-u3-X27"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L06_basic#3','sci',3,2,'u3','L06','g3_2_sci_u3_L06_basic','lesson_basic','SC3-2-u3-C13',1,'ox','auto','바닥에 매트를 깔면 뛰는 발소리를 줄일 수 있어요.',ARRAY['SC3-2-u3-X30']::text[],false,'{"seq":3,"concept":"SC3-2-u3-C13","difficulty":1,"kind":"ox","stem":"바닥에 매트를 깔면 뛰는 발소리를 줄일 수 있어요.","answer":"O","reason_options":[{"t":"매트가 소리를 잘 전달되지 않게 하기 때문에","correct":true},{"t":"매트가 소리를 더 크게 만들기 때문에","mis":"SC3-2-u3-X30"}],"mis":"SC3-2-u3-X30","explanation":["발소리가 바닥을 지나요.","매트가 막아요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L06_basic#4','sci',3,2,'u3','L06','g3_2_sci_u3_L06_basic','lesson_basic','SC3-2-u3-C13',1,'mc','auto','소음을 줄이는 방법이 아닌 것은 무엇인가요?',ARRAY['SC3-2-u3-X30']::text[],false,'{"seq":4,"concept":"SC3-2-u3-C13","difficulty":1,"kind":"mc","stem":"소음을 줄이는 방법이 아닌 것은 무엇인가요?","options":[{"t":"음악 소리를 더 크게 튼다","correct":true},{"t":"바닥에 매트를 깐다","mis":"SC3-2-u3-X30"},{"t":"도로에 방음벽을 세운다","mis":"SC3-2-u3-X30"},{"t":"창문에 커튼을 단다","mis":"SC3-2-u3-X30"}],"explanation":["줄이는지 따져요.","더 크게 하면 늘어요.","음악을 크게 트는 거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L06_basic#5','sci',3,2,'u3','L06','g3_2_sci_u3_L06_basic','lesson_basic','SC3-2-u3-C13',2,'match','auto','소음과 줄이는 방법을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC3-2-u3-C13","difficulty":2,"kind":"match","stem":"소음과 줄이는 방법을 알맞게 이으세요.","pairs":[{"l":"위층에서 뛰는 발소리","r":"바닥에 매트를 깔아요"},{"l":"자동차 경적 소리","r":"도로에 방음벽을 세워요"},{"l":"옆방에서 가구를 끄는 소리","r":"가구 밑에 카펫을 깔아요"}],"mis":"SC3-2-u3-X32","explanation":["소음이 나는 곳을 봐요.","도로에는 방음벽이에요.","발소리-매트, 경적-방음벽, 가구-카펫이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L06_basic#6','sci',3,2,'u3','L06','g3_2_sci_u3_L06_basic','lesson_basic','SC3-2-u3-C13',2,'mc','auto','소음과 줄이는 방법 조사에서 소리의 세기를 줄이는 방법은 무엇인가요?',ARRAY['SC3-2-u3-X31']::text[],false,'{"seq":6,"concept":"SC3-2-u3-C13","difficulty":2,"kind":"mc","stem":"소음과 줄이는 방법 조사에서 소리의 세기를 줄이는 방법은 무엇인가요?","options":[{"t":"㉡","correct":true},{"t":"㉠","mis":"SC3-2-u3-X31"},{"t":"㉢","mis":"SC3-2-u3-X31"},{"t":"㉣","mis":"SC3-2-u3-X31"}],"explanation":["소리를 작게 하는 것을 찾아요.","스피커예요.","㉡이에요."],"asset":{"type":"passage","lines":["㉠ 위층에서 뛰는 발소리 — 바닥에 매트를 깔아요.","㉡ 길거리 노랫소리 — 스피커 소리를 줄여요.","㉢ 자동차 경적 소리 — 도로에 방음벽을 세워요.","㉣ 옆방에서 가구를 끄는 소리 — 가구 밑에 카펫을 깔아요."],"title":"소음과 줄이는 방법 조사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L06_basic#7','sci',3,2,'u3','L06','g3_2_sci_u3_L06_basic','lesson_basic','SC3-2-u3-C12',2,'mc','auto','같은 소리를 두고 사람마다 느끼는 것으로 알맞은 것은 무엇인가요?',ARRAY['SC3-2-u3-X29']::text[],false,'{"seq":7,"concept":"SC3-2-u3-C12","difficulty":2,"kind":"mc","stem":"같은 소리를 두고 사람마다 느끼는 것으로 알맞은 것은 무엇인가요?","options":[{"t":"누군가에게 좋은 소리가 다른 사람에게는 소음일 수 있다","correct":true},{"t":"같은 소리는 누구에게나 똑같이 소음이다","mis":"SC3-2-u3-X29"},{"t":"큰 소리는 누구에게나 좋은 소리이다","mis":"SC3-2-u3-X29"},{"t":"사람마다 소리를 다르게 느끼는 일은 없다","mis":"SC3-2-u3-X29"}],"explanation":["사람마다 달라요.","좋아하는 소리가 달라요.","누군가에겐 소음일 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L06_basic#8','sci',3,2,'u3','L06','g3_2_sci_u3_L06_basic','lesson_basic','SC3-2-u3-C13',2,'blank','auto','「집 창틀에 (    )을 달면 바깥 자동차 소리가 집 안으로 잘 전달되지 않아요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC3-2-u3-X30']::text[],false,'{"seq":8,"concept":"SC3-2-u3-C13","difficulty":2,"kind":"blank","stem":"「집 창틀에 (    )을 달면 바깥 자동차 소리가 집 안으로 잘 전달되지 않아요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"이중창","correct":true},{"t":"스피커","mis":"SC3-2-u3-X30"},{"t":"확성기","mis":"SC3-2-u3-X30"},{"t":"종","mis":"SC3-2-u3-X30"}],"explanation":["창틀에 달아요.","창이 두 겹이에요.","이중창이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L06_basic#9','sci',3,2,'u3','L06','g3_2_sci_u3_L06_basic','lesson_basic','SC3-2-u3-C12',2,'ox','auto','소리는 모두 나쁘니 없애야 해요.',ARRAY['SC3-2-u3-X28']::text[],false,'{"seq":9,"concept":"SC3-2-u3-C12","difficulty":2,"kind":"ox","stem":"소리는 모두 나쁘니 없애야 해요.","answer":"X","reason_options":[{"t":"소리는 우리에게 소중하고, 불쾌감이나 고통을 주는 소리만 소음이기 때문에","correct":true},{"t":"모든 소리는 소음이기 때문에","mis":"SC3-2-u3-X28"}],"mis":"SC3-2-u3-X28","explanation":["좋아하는 소리를 떠올려요.","소리는 소중해요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L06_basic#10','sci',3,2,'u3','L06','g3_2_sci_u3_L06_basic','lesson_basic','SC3-2-u3-C13',3,'mc','auto','「소리가 잘 전달되지 않게 하는 방법인가?」로 나누었을 때 ⭕ 쪽에 들어가는 것끼리 묶은 것은 무엇인가요?',ARRAY['SC3-2-u3-X31']::text[],false,'{"seq":10,"concept":"SC3-2-u3-C13","difficulty":3,"kind":"mc","stem":"「소리가 잘 전달되지 않게 하는 방법인가?」로 나누었을 때 ⭕ 쪽에 들어가는 것끼리 묶은 것은 무엇인가요?","options":[{"t":"바닥에 매트 깔기, 창틀에 이중창 달기","correct":true},{"t":"스피커 소리 줄이기, 텔레비전 소리 줄이기","mis":"SC3-2-u3-X31"},{"t":"스피커 소리 줄이기, 바닥에 매트 깔기","mis":"SC3-2-u3-X31"},{"t":"텔레비전 소리 줄이기, 이중창 달기","mis":"SC3-2-u3-X31"}],"explanation":["막는 방법을 찾아요.","소리 줄이기는 세기예요.","매트와 이중창이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L06_challenge#1','sci',3,2,'u3','L06','g3_2_sci_u3_L06_challenge','lesson_challenge','SC3-2-u3-C13',2,'sa','auto','도로 옆에 세워 자동차 소리가 마을로 잘 전달되지 않게 하는 벽을 세 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SC3-2-u3-C13","difficulty":2,"kind":"sa","stem":"도로 옆에 세워 자동차 소리가 마을로 잘 전달되지 않게 하는 벽을 세 글자로 쓰세요.","answer":["방음벽"],"explanation":["도로 옆에 세워요.","방◯◯이에요.","방음벽이에요."],"mis":"SC3-2-u3-X30"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L06_challenge#2','sci',3,2,'u3','L06','g3_2_sci_u3_L06_challenge','lesson_challenge','SC3-2-u3-C13',2,'mc','auto','교실 창문에 커튼을 다는 것은 어떤 방법으로 소음을 줄이는 것인가요?',ARRAY['SC3-2-u3-X31','SC3-2-u3-X30']::text[],false,'{"seq":2,"concept":"SC3-2-u3-C13","difficulty":2,"kind":"mc","stem":"교실 창문에 커튼을 다는 것은 어떤 방법으로 소음을 줄이는 것인가요?","options":[{"t":"소리가 잘 전달되지 않게 하는 방법","correct":true},{"t":"소리의 세기를 줄이는 방법","mis":"SC3-2-u3-X31"},{"t":"소리를 더 높게 하는 방법","mis":"SC3-2-u3-X30"},{"t":"소음을 줄이는 방법이 아니다","mis":"SC3-2-u3-X30"}],"explanation":["커튼이 무엇을 하나요?","운동장 소리를 막아요.","잘 전달되지 않게 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L06_challenge#3','sci',3,2,'u3','L06','g3_2_sci_u3_L06_challenge','lesson_challenge','SC3-2-u3-C12',3,'error','auto','소음을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-2-u3-X29','SC3-2-u3-X27','SC3-2-u3-X28']::text[],false,'{"seq":3,"concept":"SC3-2-u3-C12","difficulty":3,"kind":"error","stem":"소음을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「내가 좋아하는 노래니까 누구에게도 소음이 아니야.」","correct":true,"mis_target":"SC3-2-u3-X29"},{"t":"친구 가 — 「불쾌감을 주는 소리를 소음이라고 해.」","mis":"SC3-2-u3-X27"},{"t":"친구 다 — 「소리는 소중하니까 모두 없앨 필요는 없어.」","mis":"SC3-2-u3-X28"}],"explanation":["사람마다 달라요.","누군가에겐 소음이에요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L06_challenge#4','sci',3,2,'u3','L06','g3_2_sci_u3_L06_challenge','lesson_challenge','SC3-2-u3-C13',3,'mc','auto','소음과 줄이는 방법 조사 ㉠~㉣에서 소리가 잘 전달되지 않게 하는 방법끼리 묶은 것은 무엇인가요?',ARRAY['SC3-2-u3-X31']::text[],false,'{"seq":4,"concept":"SC3-2-u3-C13","difficulty":3,"kind":"mc","stem":"소음과 줄이는 방법 조사 ㉠~㉣에서 소리가 잘 전달되지 않게 하는 방법끼리 묶은 것은 무엇인가요?","options":[{"t":"㉠, ㉢, ㉣","correct":true},{"t":"㉡, ㉢","mis":"SC3-2-u3-X31"},{"t":"㉠, ㉡","mis":"SC3-2-u3-X31"},{"t":"㉡만","mis":"SC3-2-u3-X31"}],"explanation":["막는 방법을 찾아요.","스피커만 세기예요.","㉠, ㉢, ㉣이에요."],"asset":{"type":"passage","lines":["㉠ 위층에서 뛰는 발소리 — 바닥에 매트를 깔아요.","㉡ 길거리 노랫소리 — 스피커 소리를 줄여요.","㉢ 자동차 경적 소리 — 도로에 방음벽을 세워요.","㉣ 옆방에서 가구를 끄는 소리 — 가구 밑에 카펫을 깔아요."],"title":"소음과 줄이는 방법 조사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L06_challenge#5','sci',3,2,'u3','L06','g3_2_sci_u3_L06_challenge','lesson_challenge','SC3-2-u3-C12',3,'mc','auto','소음을 바르게 설명한 것은 무엇인가요?',ARRAY['SC3-2-u3-X28','SC3-2-u3-X27']::text[],false,'{"seq":5,"concept":"SC3-2-u3-C12","difficulty":3,"kind":"mc","stem":"소음을 바르게 설명한 것은 무엇인가요?","options":[{"t":"사람에게 불쾌감이나 고통을 주는 소리","correct":true},{"t":"크기와 관계없이 모든 소리","mis":"SC3-2-u3-X28"},{"t":"소리가 나는 물체의 떨림","mis":"SC3-2-u3-X27"},{"t":"소리의 높고 낮은 정도","mis":"SC3-2-u3-X27"}],"explanation":["불편한 소리예요.","모든 소리가 아니에요.","불쾌감이나 고통을 주는 소리예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L06_challenge#6','sci',3,2,'u3','L06','g3_2_sci_u3_L06_challenge','lesson_challenge','SC3-2-u3-C13',3,'match','auto','소음을 줄이는 방법과 그 방법이 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SC3-2-u3-C13","difficulty":3,"kind":"match","stem":"소음을 줄이는 방법과 그 방법이 하는 일을 알맞게 이으세요.","pairs":[{"l":"텔레비전 소리 줄이기","r":"소리의 세기를 줄여요"},{"l":"도로에 방음벽 세우기","r":"자동차 소리가 마을로 잘 전달되지 않게 해요"},{"l":"바닥에 매트 깔기","r":"발소리가 아래층으로 잘 전달되지 않게 해요"}],"mis":"SC3-2-u3-X31","explanation":["작게 하나요, 막나요?","텔레비전은 작게 해요.","방음벽과 매트는 막아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L06_challenge#7','sci',3,2,'u3','L06','g3_2_sci_u3_L06_challenge','lesson_challenge','SC3-2-u3-C13',3,'ox','auto','같은 소음이라도 줄이는 방법은 여러 가지일 수 있어요.',ARRAY['SC3-2-u3-X32']::text[],false,'{"seq":7,"concept":"SC3-2-u3-C13","difficulty":3,"kind":"ox","stem":"같은 소음이라도 줄이는 방법은 여러 가지일 수 있어요.","answer":"O","reason_options":[{"t":"소리의 세기를 줄이거나 잘 전달되지 않게 하는 등 여러 방법이 있기 때문에","correct":true},{"t":"소음마다 줄이는 방법은 딱 하나뿐이기 때문에","mis":"SC3-2-u3-X32"}],"mis":"SC3-2-u3-X32","explanation":["길거리 노랫소리를 떠올려요.","방법이 여럿이에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L06_challenge#8','sci',3,2,'u3','L06','g3_2_sci_u3_L06_challenge','lesson_challenge','SC3-2-u3-C13',4,'mc','auto','길거리 노랫소리가 커서 전화 목소리가 잘 들리지 않아요. 알맞은 방법은 무엇인가요?',ARRAY['SC3-2-u3-X30','SC3-2-u3-X32']::text[],false,'{"seq":8,"concept":"SC3-2-u3-C13","difficulty":4,"kind":"mc","stem":"길거리 노랫소리가 커서 전화 목소리가 잘 들리지 않아요. 알맞은 방법은 무엇인가요?","options":[{"t":"스피커 소리를 줄이거나 방음벽이 있는 곳에서 노래한다","correct":true},{"t":"스피커 소리를 더 키워 전화 목소리를 덮는다","mis":"SC3-2-u3-X30"},{"t":"창문을 활짝 열어 소리가 잘 빠져나가게 한다","mis":"SC3-2-u3-X30"},{"t":"집 바닥에 매트를 깔아 길거리 소리를 줄인다","mis":"SC3-2-u3-X32"}],"explanation":["노랫소리가 문제예요.","작게 하거나 막아요.","스피커 소리 줄이기·방음벽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L06_challenge#9','sci',3,2,'u3','L06','g3_2_sci_u3_L06_challenge','lesson_challenge','SC3-2-u3-C12',4,'mc','auto','「피아노 소리가 좋아서 밤늦게까지 크게 쳤어.」 이 말에 대해 가장 알맞게 말한 것은 무엇인가요?',ARRAY['SC3-2-u3-X29','SC3-2-u3-X28','SC3-2-u3-X27']::text[],false,'{"seq":9,"concept":"SC3-2-u3-C12","difficulty":4,"kind":"mc","stem":"「피아노 소리가 좋아서 밤늦게까지 크게 쳤어.」 이 말에 대해 가장 알맞게 말한 것은 무엇인가요?","options":[{"t":"「나에게는 좋은 소리라도 잠자려는 사람에게는 소음이 될 수 있어.」","correct":true},{"t":"「피아노 소리는 음악이라 누구에게도 소음이 아니야.」","mis":"SC3-2-u3-X29"},{"t":"「피아노 소리도 소리니까 모두 없애야 해.」","mis":"SC3-2-u3-X28"},{"t":"「큰 소리는 모두 소음이니 피아노를 치지 마.」","mis":"SC3-2-u3-X27"}],"explanation":["밤늦은 시간이에요.","사람마다 달라요.","누군가에겐 소음이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L06_challenge#10','sci',3,2,'u3','L06','g3_2_sci_u3_L06_challenge','lesson_challenge','SC3-2-u3-C13',4,'essay','teacher','소음과 줄이는 방법 조사에서 두 가지를 골라, 각각 소리의 세기를 줄이는 방법인지 소리가 잘 전달되지 않게 하는 방법인지 쓰고, 소음의 뜻을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC3-2-u3-C13","difficulty":4,"kind":"essay","stem":"소음과 줄이는 방법 조사에서 두 가지를 골라, 각각 소리의 세기를 줄이는 방법인지 소리가 잘 전달되지 않게 하는 방법인지 쓰고, 소음의 뜻을 쓰세요.","answer_guide":{"answer":"예: ㉡ 스피커 소리를 줄이는 것은 소리의 세기를 줄이는 방법이다. ㉢ 도로에 방음벽을 세우는 것은 소리가 잘 전달되지 않게 하는 방법이다. 소음은 사람에게 불쾌감이나 고통을 주는 소리이다.","scoring_points":["두 가지를 골랐는가","두 가지 방법을 바르게 나누었는가","소음의 뜻을 바르게 썼는가"]},"explanation":["두 가지를 골라요.","세기인지 전달인지 나눠요.","소음의 뜻을 써요."],"asset":{"type":"passage","lines":["㉠ 위층에서 뛰는 발소리 — 바닥에 매트를 깔아요.","㉡ 길거리 노랫소리 — 스피커 소리를 줄여요.","㉢ 자동차 경적 소리 — 도로에 방음벽을 세워요.","㉣ 옆방에서 가구를 끄는 소리 — 가구 밑에 카펫을 깔아요."],"title":"소음과 줄이는 방법 조사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L07_basic#1','sci',3,2,'u3','L07','g3_2_sci_u3_L07_basic','lesson_basic','SC3-2-u3-C14',1,'mc','auto','늦은 시각에 세탁기를 켜면 어떤 문제가 생길 수 있나요?',ARRAY['SC3-2-u3-X34']::text[],false,'{"seq":1,"concept":"SC3-2-u3-C14","difficulty":1,"kind":"mc","stem":"늦은 시각에 세탁기를 켜면 어떤 문제가 생길 수 있나요?","options":[{"t":"아래층 사람이 시끄러워 잠을 못 잔다","correct":true},{"t":"빨래가 더 깨끗해진다","mis":"SC3-2-u3-X34"},{"t":"세탁기가 조용해진다","mis":"SC3-2-u3-X34"},{"t":"아무 문제가 없다","mis":"SC3-2-u3-X34"}],"explanation":["늦은 시각이에요.","아래층을 떠올려요.","잠을 못 자요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L07_basic#2','sci',3,2,'u3','L07','g3_2_sci_u3_L07_basic','lesson_basic','SC3-2-u3-C14',1,'sa','auto','집 안에서 걷거나 뛰는 소리가 바닥에 잘 전달되지 않게 신는 것을 하나 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC3-2-u3-C14","difficulty":1,"kind":"sa","stem":"집 안에서 걷거나 뛰는 소리가 바닥에 잘 전달되지 않게 신는 것을 하나 쓰세요.","answer":["슬리퍼","실내화","양말"],"explanation":["발에 신어요.","집 안에서 신어요.","슬리퍼·실내화·양말이에요."],"mis":"SC3-2-u3-X32"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L07_basic#3','sci',3,2,'u3','L07','g3_2_sci_u3_L07_basic','lesson_basic','SC3-2-u3-C15',1,'ox','auto','공동체의 소음 문제는 모두 함께 노력해야 줄일 수 있어요.',ARRAY['SC3-2-u3-X34']::text[],false,'{"seq":3,"concept":"SC3-2-u3-C15","difficulty":1,"kind":"ox","stem":"공동체의 소음 문제는 모두 함께 노력해야 줄일 수 있어요.","answer":"O","reason_options":[{"t":"작은 실천이 모여 이웃을 편안하게 만들기 때문에","correct":true},{"t":"소음은 한 사람만 조심하면 모두 사라지기 때문에","mis":"SC3-2-u3-X34"}],"mis":"SC3-2-u3-X34","explanation":["공동체를 떠올려요.","함께 노력해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L07_basic#4','sci',3,2,'u3','L07','g3_2_sci_u3_L07_basic','lesson_basic','SC3-2-u3-C14',1,'mc','auto','모둠이 실천할 방법을 고를 때 알맞은 기준은 무엇인가요?',ARRAY['SC3-2-u3-X33']::text[],false,'{"seq":4,"concept":"SC3-2-u3-C14","difficulty":1,"kind":"mc","stem":"모둠이 실천할 방법을 고를 때 알맞은 기준은 무엇인가요?","options":[{"t":"우리가 실천할 수 있는 방법","correct":true},{"t":"가장 어려운 방법","mis":"SC3-2-u3-X33"},{"t":"돈이 가장 많이 드는 방법","mis":"SC3-2-u3-X33"},{"t":"아무 방법이나","mis":"SC3-2-u3-X33"}],"explanation":["직접 해야 해요.","할 수 있어야 해요.","실천할 수 있는 방법이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L07_basic#5','sci',3,2,'u3','L07','g3_2_sci_u3_L07_basic','lesson_basic','SC3-2-u3-C14',2,'match','auto','층간 소음과 실천 방법을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC3-2-u3-C14","difficulty":2,"kind":"match","stem":"층간 소음과 실천 방법을 알맞게 이으세요.","pairs":[{"l":"텔레비전의 큰 소리","r":"소리의 세기를 줄여요"},{"l":"세탁기가 흔들리는 소리","r":"밑에 고무 받침대를 붙여요"},{"l":"집 안의 발소리","r":"슬리퍼를 신어요"}],"mis":"SC3-2-u3-X32","explanation":["소음을 하나씩 봐요.","세탁기는 받침대예요.","텔레비전-세기, 세탁기-받침대, 발소리-슬리퍼예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L07_basic#6','sci',3,2,'u3','L07','g3_2_sci_u3_L07_basic','lesson_basic','SC3-2-u3-C15',2,'mc','auto','어느 모둠의 실천 계획에서 ㉠에 알맞은 말은 무엇인가요?',ARRAY['SC3-2-u3-X35']::text[],false,'{"seq":6,"concept":"SC3-2-u3-C15","difficulty":2,"kind":"mc","stem":"어느 모둠의 실천 계획에서 ㉠에 알맞은 말은 무엇인가요?","options":[{"t":"보완할 점","correct":true},{"t":"다른 모둠의 흉","mis":"SC3-2-u3-X35"},{"t":"비밀","mis":"SC3-2-u3-X35"},{"t":"가장 비싼 물건","mis":"SC3-2-u3-X35"}],"explanation":["잘한 점과 함께 담아요.","더 고칠 점이에요.","보완할 점이에요."],"asset":{"type":"passage","lines":["문제 — 늦은 밤 세탁기 소리로 아래층이 잠을 못 자요.","방법 — 세탁기 밑에 고무 받침대를 붙여요.","실천 — 일주일 동안 실천표에 매일 기록해요.","나누기 — 잘한 점과 ㉠을 담아 소개 자료를 만들어요."],"title":"어느 모둠의 실천 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L07_basic#7','sci',3,2,'u3','L07','g3_2_sci_u3_L07_basic','lesson_basic','SC3-2-u3-C15',2,'mc','auto','정한 방법을 실천할 때 알맞은 것은 무엇인가요?',ARRAY['SC3-2-u3-X35']::text[],false,'{"seq":7,"concept":"SC3-2-u3-C15","difficulty":2,"kind":"mc","stem":"정한 방법을 실천할 때 알맞은 것은 무엇인가요?","options":[{"t":"일주일 동안 실천하며 실천표에 매일 기록한다","correct":true},{"t":"하루만 실천하고 기록하지 않는다","mis":"SC3-2-u3-X35"},{"t":"생각날 때만 가끔 기록한다","mis":"SC3-2-u3-X35"},{"t":"실천하지 않고 기록만 채운다","mis":"SC3-2-u3-X35"}],"explanation":["꾸준히 해요.","매일 적어요.","매일 기록해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L07_basic#8','sci',3,2,'u3','L07','g3_2_sci_u3_L07_basic','lesson_basic','SC3-2-u3-C14',2,'blank','auto','「세탁기 밑에 (    )를 붙이면 바닥을 두드리는 소리가 잘 전달되지 않아요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC3-2-u3-X32']::text[],false,'{"seq":8,"concept":"SC3-2-u3-C14","difficulty":2,"kind":"blank","stem":"「세탁기 밑에 (    )를 붙이면 바닥을 두드리는 소리가 잘 전달되지 않아요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"고무 받침대","correct":true},{"t":"스피커","mis":"SC3-2-u3-X32"},{"t":"종","mis":"SC3-2-u3-X32"},{"t":"확성기","mis":"SC3-2-u3-X32"}],"explanation":["세탁기 밑이에요.","고무로 만들어요.","고무 받침대예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L07_basic#9','sci',3,2,'u3','L07','g3_2_sci_u3_L07_basic','lesson_basic','SC3-2-u3-C14',2,'ox','auto','집에 혼자 있을 때는 텔레비전을 마음껏 크게 틀어도 괜찮아요.',ARRAY['SC3-2-u3-X34']::text[],false,'{"seq":9,"concept":"SC3-2-u3-C14","difficulty":2,"kind":"ox","stem":"집에 혼자 있을 때는 텔레비전을 마음껏 크게 틀어도 괜찮아요.","answer":"X","reason_options":[{"t":"내 집의 큰 소리가 이웃에게는 소음이 될 수 있기 때문에","correct":true},{"t":"혼자 있으면 소리가 다른 집에 들리지 않기 때문에","mis":"SC3-2-u3-X34"}],"mis":"SC3-2-u3-X34","explanation":["이웃을 떠올려요.","소리는 벽과 바닥을 지나요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L07_basic#10','sci',3,2,'u3','L07','g3_2_sci_u3_L07_basic','lesson_basic','SC3-2-u3-C15',3,'mc','auto','실천 소개 자료로 알맞지 않은 것은 무엇인가요?',ARRAY['SC3-2-u3-X35']::text[],false,'{"seq":10,"concept":"SC3-2-u3-C15","difficulty":3,"kind":"mc","stem":"실천 소개 자료로 알맞지 않은 것은 무엇인가요?","options":[{"t":"다른 모둠을 흉보는 내용","correct":true},{"t":"도화지에 그린 그림","mis":"SC3-2-u3-X35"},{"t":"스마트 기기로 만든 동영상","mis":"SC3-2-u3-X35"},{"t":"실천하며 느낀 잘한 점","mis":"SC3-2-u3-X35"}],"explanation":["소개 자료를 떠올려요.","서로 배워요.","흉보는 내용이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L07_challenge#1','sci',3,2,'u3','L07','g3_2_sci_u3_L07_challenge','lesson_challenge','SC3-2-u3-C5',2,'mc','auto','노랫말 맞히기 음표 ②를 옳게 고친 것은 무엇인가요?',ARRAY['SC3-2-u3-X11','SC3-2-u3-X22']::text[],false,'{"seq":1,"concept":"SC3-2-u3-C5","difficulty":2,"kind":"mc","stem":"노랫말 맞히기 음표 ②를 옳게 고친 것은 무엇인가요?","options":[{"t":"소리의 크고 작은 정도는 세기예요","correct":true},{"t":"소리의 크고 작은 정도는 떨림이에요","mis":"SC3-2-u3-X11"},{"t":"소리의 높고 낮은 정도는 세기예요","mis":"SC3-2-u3-X22"},{"t":"소리의 크고 작은 정도는 빠르기예요","mis":"SC3-2-u3-X11"}],"explanation":["②를 읽어요.","크고 작은 정도예요.","세기예요."],"asset":{"type":"passage","lines":["① 소리가 나는 트라이앵글은 떨려요.","② 소리의 크고 작은 정도는 높낮이예요.","③ 짧은 음판을 치면 낮은 소리가 나요.","④ 선생님 목소리는 공기를 통해 전달돼요.","⑤ 방음벽으로 소음을 줄일 수 있어요."],"title":"노랫말 맞히기 음표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L07_challenge#2','sci',3,2,'u3','L07','g3_2_sci_u3_L07_challenge','lesson_challenge','SC3-2-u3-C8',2,'mc','auto','노랫말 맞히기 음표 ③을 옳게 고친 것은 무엇인가요?',ARRAY['SC3-2-u3-X19','SC3-2-u3-X21']::text[],false,'{"seq":2,"concept":"SC3-2-u3-C8","difficulty":2,"kind":"mc","stem":"노랫말 맞히기 음표 ③을 옳게 고친 것은 무엇인가요?","options":[{"t":"짧은 음판을 치면 높은 소리가 나요","correct":true},{"t":"긴 음판을 치면 높은 소리가 나요","mis":"SC3-2-u3-X19"},{"t":"짧은 음판을 세게 치면 낮은 소리가 나요","mis":"SC3-2-u3-X21"},{"t":"짧은 음판은 소리가 나지 않아요","mis":"SC3-2-u3-X19"}],"explanation":["③을 읽어요.","짧으면 높아요.","높은 소리가 나요."],"asset":{"type":"passage","lines":["① 소리가 나는 트라이앵글은 떨려요.","② 소리의 크고 작은 정도는 높낮이예요.","③ 짧은 음판을 치면 낮은 소리가 나요.","④ 선생님 목소리는 공기를 통해 전달돼요.","⑤ 방음벽으로 소음을 줄일 수 있어요."],"title":"노랫말 맞히기 음표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L07_challenge#3','sci',3,2,'u3','L07','g3_2_sci_u3_L07_challenge','lesson_challenge','SC3-2-u3-C15',3,'error','auto','실천 소개 자료를 살펴보며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-2-u3-X35','SC3-2-u3-X34']::text[],false,'{"seq":3,"concept":"SC3-2-u3-C15","difficulty":3,"kind":"error","stem":"실천 소개 자료를 살펴보며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「저 모둠은 그림이 엉망이네. 우리가 훨씬 나아.」","correct":true,"mis_target":"SC3-2-u3-X35"},{"t":"친구 나 — 「실천표를 매일 꼼꼼히 적은 점이 좋아.」","mis":"SC3-2-u3-X35"},{"t":"친구 다 — 「주말에도 실천하면 더 좋겠어.」","mis":"SC3-2-u3-X34"}],"explanation":["잘한 점을 먼저 말해요.","흉보지 않아요.","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L07_challenge#4','sci',3,2,'u3','L07','g3_2_sci_u3_L07_challenge','lesson_challenge','SC3-2-u3-C14',3,'mc','auto','실천 방법을 「소리가 잘 전달되지 않게 하는가?」로 나누었을 때 ⭕ 쪽에 들어가는 것끼리 묶은 것은 무엇인가요?',ARRAY['SC3-2-u3-X31']::text[],false,'{"seq":4,"concept":"SC3-2-u3-C14","difficulty":3,"kind":"mc","stem":"실천 방법을 「소리가 잘 전달되지 않게 하는가?」로 나누었을 때 ⭕ 쪽에 들어가는 것끼리 묶은 것은 무엇인가요?","options":[{"t":"슬리퍼 신기, 세탁기에 고무 받침대 붙이기","correct":true},{"t":"텔레비전 소리 줄이기, 스피커 소리 줄이기","mis":"SC3-2-u3-X31"},{"t":"텔레비전 소리 줄이기, 슬리퍼 신기","mis":"SC3-2-u3-X31"},{"t":"스피커 소리 줄이기, 양말 신고 걷기","mis":"SC3-2-u3-X31"}],"explanation":["바닥으로 가는 소리를 막아요.","소리 줄이기는 세기예요.","슬리퍼와 받침대예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L07_challenge#5','sci',3,2,'u3','L07','g3_2_sci_u3_L07_challenge','lesson_challenge','SC3-2-u3-C3',3,'mc','auto','노랫말 맞히기 음표 가운데 옳은 것끼리 묶은 것은 무엇인가요?',ARRAY['SC3-2-u3-X22','SC3-2-u3-X19']::text[],false,'{"seq":5,"concept":"SC3-2-u3-C3","difficulty":3,"kind":"mc","stem":"노랫말 맞히기 음표 가운데 옳은 것끼리 묶은 것은 무엇인가요?","options":[{"t":"①, ④, ⑤","correct":true},{"t":"①, ②, ③","mis":"SC3-2-u3-X22"},{"t":"②, ③, ④","mis":"SC3-2-u3-X19"},{"t":"③, ④, ⑤","mis":"SC3-2-u3-X19"}],"explanation":["하나씩 따져요.","②, ③은 옳지 않아요.","①, ④, ⑤예요."],"asset":{"type":"passage","lines":["① 소리가 나는 트라이앵글은 떨려요.","② 소리의 크고 작은 정도는 높낮이예요.","③ 짧은 음판을 치면 낮은 소리가 나요.","④ 선생님 목소리는 공기를 통해 전달돼요.","⑤ 방음벽으로 소음을 줄일 수 있어요."],"title":"노랫말 맞히기 음표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L07_challenge#6','sci',3,2,'u3','L07','g3_2_sci_u3_L07_challenge','lesson_challenge','SC3-2-u3-C15',3,'match','auto','실천 과정에서 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SC3-2-u3-C15","difficulty":3,"kind":"match","stem":"실천 과정에서 하는 일을 알맞게 이으세요.","pairs":[{"l":"방법 정하기","r":"우리가 할 수 있는 방법을 골라요"},{"l":"실천하기","r":"실천표에 매일 기록해요"},{"l":"소개하기","r":"잘한 점과 보완할 점을 담아 자료를 만들어요"}],"mis":"SC3-2-u3-X35","explanation":["차례를 떠올려요.","실천하며 기록해요.","정하기-고르기, 실천-기록, 소개-자료예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L07_challenge#7','sci',3,2,'u3','L07','g3_2_sci_u3_L07_challenge','lesson_challenge','SC3-2-u3-C14',3,'ox','auto','층간 소음을 줄이려면 아래층 사람만 조심하면 돼요.',ARRAY['SC3-2-u3-X34']::text[],false,'{"seq":7,"concept":"SC3-2-u3-C14","difficulty":3,"kind":"ox","stem":"층간 소음을 줄이려면 아래층 사람만 조심하면 돼요.","answer":"X","reason_options":[{"t":"위층과 아래층 모두 함께 노력해야 하기 때문에","correct":true},{"t":"소리는 아래층에서만 생기기 때문에","mis":"SC3-2-u3-X34"}],"mis":"SC3-2-u3-X34","explanation":["누가 소리를 내나요?","모두 낼 수 있어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L07_challenge#8','sci',3,2,'u3','L07','g3_2_sci_u3_L07_challenge','lesson_challenge','SC3-2-u3-C14',4,'mc','auto','어느 모둠의 실천 계획 속 문제를 해결하는 다른 방법으로 가장 알맞은 것은 무엇인가요?',ARRAY['SC3-2-u3-X32','SC3-2-u3-X34','SC3-2-u3-X33']::text[],false,'{"seq":8,"concept":"SC3-2-u3-C14","difficulty":4,"kind":"mc","stem":"어느 모둠의 실천 계획 속 문제를 해결하는 다른 방법으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"늦은 밤에는 세탁기를 켜지 않고 낮에 빨래한다","correct":true},{"t":"고무 받침대를 떼고 세탁기를 더 오래 돌린다","mis":"SC3-2-u3-X32"},{"t":"아래층에 귀마개를 주고 밤마다 세탁기를 켠다","mis":"SC3-2-u3-X34"},{"t":"비싼 새 세탁기를 사야만 해결된다","mis":"SC3-2-u3-X33"}],"explanation":["문제는 늦은 밤이에요.","실천할 수 있어야 해요.","낮에 빨래해요."],"asset":{"type":"passage","lines":["문제 — 늦은 밤 세탁기 소리로 아래층이 잠을 못 자요.","방법 — 세탁기 밑에 고무 받침대를 붙여요.","실천 — 일주일 동안 실천표에 매일 기록해요.","나누기 — 잘한 점과 ㉠을 담아 소개 자료를 만들어요."],"title":"어느 모둠의 실천 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L07_challenge#9','sci',3,2,'u3','L07','g3_2_sci_u3_L07_challenge','lesson_challenge','SC3-2-u3-C15',4,'mc','auto','일주일 동안 실천한 뒤 소개 자료에 담을 내용으로 가장 알맞은 것은 무엇인가요?',ARRAY['SC3-2-u3-X35','SC3-2-u3-X34']::text[],false,'{"seq":9,"concept":"SC3-2-u3-C15","difficulty":4,"kind":"mc","stem":"일주일 동안 실천한 뒤 소개 자료에 담을 내용으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"「매일 실내화를 신었더니 아래층에서 조용해졌다고 했어요. 주말에 깜빡한 점은 다음에 고칠게요.」","correct":true},{"t":"「우리 모둠이 가장 잘했으니 다른 모둠은 볼 필요 없어요.」","mis":"SC3-2-u3-X35"},{"t":"「기록은 안 했지만 아마 잘했을 거예요.」","mis":"SC3-2-u3-X35"},{"t":"「혼자 있을 때는 소리를 마음껏 냈어요.」","mis":"SC3-2-u3-X34"}],"explanation":["잘한 점과 보완할 점이에요.","기록이 있어야 해요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L07_challenge#10','sci',3,2,'u3','L07','g3_2_sci_u3_L07_challenge','lesson_challenge','SC3-2-u3-C14',4,'essay','teacher','우리 집이나 교실에서 생길 수 있는 소음 하나를 쓰고, 이를 줄이려고 실천할 방법을 소음을 줄이는 두 가지 방법 가운데 하나와 이어 쓰세요. 그리고 실천한 것을 어떻게 기록하고 나눌지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC3-2-u3-C14","difficulty":4,"kind":"essay","stem":"우리 집이나 교실에서 생길 수 있는 소음 하나를 쓰고, 이를 줄이려고 실천할 방법을 소음을 줄이는 두 가지 방법 가운데 하나와 이어 쓰세요. 그리고 실천한 것을 어떻게 기록하고 나눌지 쓰세요.","answer_guide":{"answer":"예: 집 안에서 뛰는 발소리가 아래층에 소음이 될 수 있다. 실내화를 신으면 발소리가 바닥으로 잘 전달되지 않게 할 수 있다. 일주일 동안 실천표에 매일 기록하고, 잘한 점과 보완할 점을 소개 자료로 만들어 나눈다.","scoring_points":["생활 속 소음을 썼는가","실천 방법을 두 가지 방법 가운데 하나와 이어 썼는가","기록하고 나누는 방법을 썼는가"]},"explanation":["소음을 떠올려요.","방법과 이어요.","기록과 나누기를 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L08_basic#1','sci',3,2,'u3','L08','g3_2_sci_u3_L08_basic','lesson_basic','SC3-2-u3-C16',1,'mc','auto','귀로 듣는 소리를 눈으로 볼 수 있게 해 주는 기기는 무엇인가요?',ARRAY['SC3-2-u3-X36']::text[],false,'{"seq":1,"concept":"SC3-2-u3-C16","difficulty":1,"kind":"mc","stem":"귀로 듣는 소리를 눈으로 볼 수 있게 해 주는 기기는 무엇인가요?","options":[{"t":"음향 카메라","correct":true},{"t":"확성기","mis":"SC3-2-u3-X36"},{"t":"스피커","mis":"SC3-2-u3-X36"},{"t":"소리굽쇠","mis":"SC3-2-u3-X36"}],"explanation":["소리를 눈으로 봐요.","카메라예요.","음향 카메라예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L08_basic#2','sci',3,2,'u3','L08','g3_2_sci_u3_L08_basic','lesson_basic','SC3-2-u3-C16',1,'sa','auto','음향 카메라에 여러 개가 달려 있는 장치를 세 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC3-2-u3-C16","difficulty":1,"kind":"sa","stem":"음향 카메라에 여러 개가 달려 있는 장치를 세 글자로 쓰세요.","answer":["마이크"],"explanation":["소리를 받는 장치예요.","마◯◯예요.","마이크예요."],"mis":"SC3-2-u3-X36"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L08_basic#3','sci',3,2,'u3','L08','g3_2_sci_u3_L08_basic','lesson_basic','SC3-2-u3-C16',1,'ox','auto','음향 카메라는 화면 속에 소리가 나는 곳을 색깔로 나타내요.',ARRAY['SC3-2-u3-X36']::text[],false,'{"seq":3,"concept":"SC3-2-u3-C16","difficulty":1,"kind":"ox","stem":"음향 카메라는 화면 속에 소리가 나는 곳을 색깔로 나타내요.","answer":"O","reason_options":[{"t":"소리를 눈으로 볼 수 있게 해 주는 기기이기 때문에","correct":true},{"t":"소리를 크게 키워 주는 기기이기 때문에","mis":"SC3-2-u3-X36"}],"mis":"SC3-2-u3-X36","explanation":["화면을 떠올려요.","색깔로 보여 줘요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L08_basic#4','sci',3,2,'u3','L08','g3_2_sci_u3_L08_basic','lesson_basic','SC3-2-u3-C17',1,'mc','auto','인공지능 음향 카메라로 할 수 있는 일은 무엇인가요?',ARRAY['SC3-2-u3-X38']::text[],false,'{"seq":4,"concept":"SC3-2-u3-C17","difficulty":1,"kind":"mc","stem":"인공지능 음향 카메라로 할 수 있는 일은 무엇인가요?","options":[{"t":"자동차의 고장 난 곳을 빠르게 찾는다","correct":true},{"t":"음악을 대신 연주한다","mis":"SC3-2-u3-X38"},{"t":"소리를 영원히 저장한다","mis":"SC3-2-u3-X38"},{"t":"비를 내리게 한다","mis":"SC3-2-u3-X38"}],"explanation":["고장 난 곳을 떠올려요.","소리로 찾아요.","고장 난 곳을 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L08_basic#5','sci',3,2,'u3','L08','g3_2_sci_u3_L08_basic','lesson_basic','SC3-2-u3-C17',2,'match','auto','낱말과 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC3-2-u3-C17","difficulty":2,"kind":"match","stem":"낱말과 뜻을 알맞게 이으세요.","pairs":[{"l":"인공지능","r":"생각하는 능력 등을 컴퓨터 프로그램이 대신하는 기술"},{"l":"음향 카메라","r":"소리가 나는 곳을 색깔로 나타내는 기기"},{"l":"마이크","r":"음향 카메라에 여러 개가 달려 있어요"}],"mis":"SC3-2-u3-X39","explanation":["뜻을 하나씩 떠올려요.","컴퓨터 프로그램은 인공지능이에요.","인공지능-기술, 음향 카메라-기기, 마이크-여러 개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L08_basic#6','sci',3,2,'u3','L08','g3_2_sci_u3_L08_basic','lesson_basic','SC3-2-u3-C16',2,'mc','auto','음향 카메라 알아보기에서 화면의 색깔이 달라지는 까닭은 무엇인가요?',ARRAY['SC3-2-u3-X37']::text[],false,'{"seq":6,"concept":"SC3-2-u3-C16","difficulty":2,"kind":"mc","stem":"음향 카메라 알아보기에서 화면의 색깔이 달라지는 까닭은 무엇인가요?","options":[{"t":"소리의 세기나 높낮이가 달라서","correct":true},{"t":"그날의 날씨가 달라서","mis":"SC3-2-u3-X37"},{"t":"카메라의 겉 색깔이 달라서","mis":"SC3-2-u3-X37"},{"t":"화면을 보는 사람이 달라서","mis":"SC3-2-u3-X37"}],"explanation":["색깔 줄을 읽어요.","소리의 성질이에요.","세기나 높낮이예요."],"asset":{"type":"passage","lines":["음향 카메라 — 여러 개의 마이크가 달려 있어요.","화면 — 소리가 나는 곳이 색깔로 나타나요.","색깔 — 소리의 세기나 높낮이에 따라 달라져요.","인공지능 — 섞인 소리 속에서 소리마다 세기와 높낮이를 구별해요."],"title":"음향 카메라 알아보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L08_basic#7','sci',3,2,'u3','L08','g3_2_sci_u3_L08_basic','lesson_basic','SC3-2-u3-C17',2,'mc','auto','여러 소리가 섞여 고장 난 곳을 찾기 어려울 때 인공지능 음향 카메라가 도와주는 까닭은 무엇인가요?',ARRAY['SC3-2-u3-X36','SC3-2-u3-X38']::text[],false,'{"seq":7,"concept":"SC3-2-u3-C17","difficulty":2,"kind":"mc","stem":"여러 소리가 섞여 고장 난 곳을 찾기 어려울 때 인공지능 음향 카메라가 도와주는 까닭은 무엇인가요?","options":[{"t":"섞인 소리 속에서 소리마다 세기와 높낮이를 구별하기 때문에","correct":true},{"t":"소리를 모두 없애 주기 때문에","mis":"SC3-2-u3-X36"},{"t":"고장 난 곳을 저절로 고쳐 주기 때문에","mis":"SC3-2-u3-X38"},{"t":"소리를 더 크게 키우기 때문에","mis":"SC3-2-u3-X36"}],"explanation":["섞인 소리예요.","구별해요.","세기와 높낮이를 구별해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L08_basic#8','sci',3,2,'u3','L08','g3_2_sci_u3_L08_basic','lesson_basic','SC3-2-u3-C16',2,'blank','auto','「음향 카메라는 귀로 듣는 소리를 (    ) 수 있게 해 줘요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC3-2-u3-X36']::text[],false,'{"seq":8,"concept":"SC3-2-u3-C16","difficulty":2,"kind":"blank","stem":"「음향 카메라는 귀로 듣는 소리를 (    ) 수 있게 해 줘요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"눈으로 볼","correct":true},{"t":"코로 맡을","mis":"SC3-2-u3-X36"},{"t":"손으로 만질","mis":"SC3-2-u3-X36"},{"t":"혀로 맛볼","mis":"SC3-2-u3-X36"}],"explanation":["화면에 나타나요.","눈을 써요.","눈으로 볼 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L08_basic#9','sci',3,2,'u3','L08','g3_2_sci_u3_L08_basic','lesson_basic','SC3-2-u3-C17',2,'ox','auto','인공지능은 사람의 생각하는 능력 등을 컴퓨터 프로그램이 대신하게 만든 기술이에요.',ARRAY['SC3-2-u3-X39']::text[],false,'{"seq":9,"concept":"SC3-2-u3-C17","difficulty":2,"kind":"ox","stem":"인공지능은 사람의 생각하는 능력 등을 컴퓨터 프로그램이 대신하게 만든 기술이에요.","answer":"O","reason_options":[{"t":"인공지능 음향 카메라가 섞인 소리를 구별하는 것도 이 기술 덕분이기 때문에","correct":true},{"t":"인공지능은 소리를 크게 키우는 장치이기 때문에","mis":"SC3-2-u3-X39"}],"mis":"SC3-2-u3-X39","explanation":["뜻을 떠올려요.","컴퓨터 프로그램이에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L08_basic#10','sci',3,2,'u3','L08','g3_2_sci_u3_L08_basic','lesson_basic','SC3-2-u3-C17',3,'mc','auto','음향 카메라를 단 무인 비행기로 할 수 있을 것 같은 일은 무엇인가요?',ARRAY['SC3-2-u3-X38','SC3-2-u3-X36']::text[],false,'{"seq":10,"concept":"SC3-2-u3-C17","difficulty":3,"kind":"mc","stem":"음향 카메라를 단 무인 비행기로 할 수 있을 것 같은 일은 무엇인가요?","options":[{"t":"재난 때 조난자의 위치를 찾는다","correct":true},{"t":"비를 내리게 한다","mis":"SC3-2-u3-X38"},{"t":"바닷물을 깨끗하게 한다","mis":"SC3-2-u3-X38"},{"t":"모든 소음을 없앤다","mis":"SC3-2-u3-X36"}],"explanation":["하늘에서 소리를 찾아요.","도움이 필요한 사람이에요.","조난자를 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L08_challenge#1','sci',3,2,'u3','L08','g3_2_sci_u3_L08_challenge','lesson_challenge','SC3-2-u3-C16',2,'sa','auto','음향 카메라 화면에서 소리가 나는 곳은 무엇으로 나타나나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SC3-2-u3-C16","difficulty":2,"kind":"sa","stem":"음향 카메라 화면에서 소리가 나는 곳은 무엇으로 나타나나요? 두 글자로 쓰세요.","answer":["색깔"],"explanation":["화면을 떠올려요.","빨강, 파랑 같은 거예요.","색깔이에요."],"mis":"SC3-2-u3-X37"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L08_challenge#2','sci',3,2,'u3','L08','g3_2_sci_u3_L08_challenge','lesson_challenge','SC3-2-u3-C16',2,'mc','auto','음향 카메라를 바르게 설명한 것은 무엇인가요?',ARRAY['SC3-2-u3-X36']::text[],false,'{"seq":2,"concept":"SC3-2-u3-C16","difficulty":2,"kind":"mc","stem":"음향 카메라를 바르게 설명한 것은 무엇인가요?","options":[{"t":"소리가 나는 곳을 색깔로 나타내는 기기","correct":true},{"t":"소리를 크게 만드는 기기","mis":"SC3-2-u3-X36"},{"t":"소리를 없애는 기기","mis":"SC3-2-u3-X36"},{"t":"사진을 찍으면 노래가 나오는 기기","mis":"SC3-2-u3-X36"}],"explanation":["눈으로 봐요.","색깔로 나타내요.","소리가 나는 곳을 보여 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L08_challenge#3','sci',3,2,'u3','L08','g3_2_sci_u3_L08_challenge','lesson_challenge','SC3-2-u3-C16',3,'error','auto','음향 카메라를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-2-u3-X37','SC3-2-u3-X36','SC3-2-u3-X39']::text[],false,'{"seq":3,"concept":"SC3-2-u3-C16","difficulty":3,"kind":"error","stem":"음향 카메라를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「화면 색깔은 카메라 겉 색깔에 따라 바뀌어.」","correct":true,"mis_target":"SC3-2-u3-X37"},{"t":"친구 가 — 「여러 개의 마이크가 달려 있어.」","mis":"SC3-2-u3-X36"},{"t":"친구 다 — 「인공지능으로 섞인 소리를 구별할 수 있어.」","mis":"SC3-2-u3-X39"}],"explanation":["색깔이 바뀌는 까닭이에요.","세기와 높낮이예요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L08_challenge#4','sci',3,2,'u3','L08','g3_2_sci_u3_L08_challenge','lesson_challenge','SC3-2-u3-C9',3,'mc','auto','음향 카메라 화면의 색깔과 관계있는 소리의 성질끼리 묶은 것은 무엇인가요?',ARRAY['SC3-2-u3-X37']::text[],false,'{"seq":4,"concept":"SC3-2-u3-C9","difficulty":3,"kind":"mc","stem":"음향 카메라 화면의 색깔과 관계있는 소리의 성질끼리 묶은 것은 무엇인가요?","options":[{"t":"소리의 세기와 높낮이","correct":true},{"t":"날씨와 계절","mis":"SC3-2-u3-X37"},{"t":"카메라의 크기와 무게","mis":"SC3-2-u3-X37"},{"t":"소리를 들은 사람의 수","mis":"SC3-2-u3-X37"}],"explanation":["소리의 성질이에요.","배운 두 가지예요.","세기와 높낮이예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L08_challenge#5','sci',3,2,'u3','L08','g3_2_sci_u3_L08_challenge','lesson_challenge','SC3-2-u3-C17',3,'mc','auto','「인공지능 음향 카메라가 하는 일인가?」로 나누었어요. ⭕ 쪽에 들어가는 것끼리 묶은 것은 무엇인가요?',ARRAY['SC3-2-u3-X38','SC3-2-u3-X36']::text[],false,'{"seq":5,"concept":"SC3-2-u3-C17","difficulty":3,"kind":"mc","stem":"「인공지능 음향 카메라가 하는 일인가?」로 나누었어요. ⭕ 쪽에 들어가는 것끼리 묶은 것은 무엇인가요?","options":[{"t":"자동차의 고장 난 곳 찾기, 기계의 고장 난 부분 소리 찾기","correct":true},{"t":"소리를 귀로만 듣기, 자동차 고장 찾기","mis":"SC3-2-u3-X38"},{"t":"소리를 더 크게 키우기, 기계 고장 찾기","mis":"SC3-2-u3-X36"},{"t":"소리를 귀로만 듣기, 소리 없애기","mis":"SC3-2-u3-X36"}],"explanation":["고장 난 곳을 찾아요.","귀로만 듣는 건 아니에요.","자동차와 기계예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L08_challenge#6','sci',3,2,'u3','L08','g3_2_sci_u3_L08_challenge','lesson_challenge','SC3-2-u3-C9',3,'match','auto','물체의 모습과 나는 소리를 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SC3-2-u3-C9","difficulty":3,"kind":"match","stem":"물체의 모습과 나는 소리를 알맞게 이으세요.","pairs":[{"l":"물체가 크게 떨려요","r":"큰 소리"},{"l":"물체의 길이가 짧아요","r":"높은 소리"},{"l":"물체의 길이가 길어요","r":"낮은 소리"}],"mis":"SC3-2-u3-X22","explanation":["떨림은 세기예요.","길이는 높낮이예요.","크게 떨림-큰, 짧음-높은, 긺-낮은 소리예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L08_challenge#7','sci',3,2,'u3','L08','g3_2_sci_u3_L08_challenge','lesson_challenge','SC3-2-u3-C16',3,'ox','auto','음향 카메라는 소리를 크게 키워 주는 기계예요.',ARRAY['SC3-2-u3-X36']::text[],false,'{"seq":7,"concept":"SC3-2-u3-C16","difficulty":3,"kind":"ox","stem":"음향 카메라는 소리를 크게 키워 주는 기계예요.","answer":"X","reason_options":[{"t":"소리가 나는 곳을 색깔로 보여 주는 기기이기 때문에","correct":true},{"t":"화면 색깔이 진할수록 소리를 키우기 때문에","mis":"SC3-2-u3-X36"}],"mis":"SC3-2-u3-X36","explanation":["무엇을 하는 기기인가요?","보여 줘요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L08_challenge#8','sci',3,2,'u3','L08','g3_2_sci_u3_L08_challenge','lesson_challenge','SC3-2-u3-C17',4,'mc','auto','음향 카메라 알아보기를 보고 자동차 수리에 쓰면 좋은 까닭을 가장 바르게 말한 것은 무엇인가요?',ARRAY['SC3-2-u3-X36','SC3-2-u3-X38','SC3-2-u3-X37']::text[],false,'{"seq":8,"concept":"SC3-2-u3-C17","difficulty":4,"kind":"mc","stem":"음향 카메라 알아보기를 보고 자동차 수리에 쓰면 좋은 까닭을 가장 바르게 말한 것은 무엇인가요?","options":[{"t":"섞인 소리 속에서 고장 난 곳의 소리를 찾아 수리할 곳을 빨리 알 수 있다","correct":true},{"t":"자동차 소리를 모두 없애 조용하게 고칠 수 있다","mis":"SC3-2-u3-X36"},{"t":"카메라가 고장 난 곳을 저절로 고친다","mis":"SC3-2-u3-X38"},{"t":"화면 색깔이 날씨를 알려 주어 수리 날을 정한다","mis":"SC3-2-u3-X37"}],"explanation":["섞인 소리예요.","인공지능이 구별해요.","고장 난 곳을 빨리 알아요."],"asset":{"type":"passage","lines":["음향 카메라 — 여러 개의 마이크가 달려 있어요.","화면 — 소리가 나는 곳이 색깔로 나타나요.","색깔 — 소리의 세기나 높낮이에 따라 달라져요.","인공지능 — 섞인 소리 속에서 소리마다 세기와 높낮이를 구별해요."],"title":"음향 카메라 알아보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L08_challenge#9','sci',3,2,'u3','L08','g3_2_sci_u3_L08_challenge','lesson_challenge','SC3-2-u3-C16',4,'mc','auto','음향 카메라를 우리 생활에 쓰는 생각으로 가장 알맞은 것은 무엇인가요?',ARRAY['SC3-2-u3-X36','SC3-2-u3-X37','SC3-2-u3-X38']::text[],false,'{"seq":9,"concept":"SC3-2-u3-C16","difficulty":4,"kind":"mc","stem":"음향 카메라를 우리 생활에 쓰는 생각으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"교실에서 어디서 큰 소리가 나는지 화면으로 찾아 소음을 줄인다","correct":true},{"t":"음향 카메라로 소리를 크게 키워 운동장까지 들리게 한다","mis":"SC3-2-u3-X36"},{"t":"화면 색깔로 내일 날씨를 알아본다","mis":"SC3-2-u3-X37"},{"t":"음향 카메라가 사람 대신 노래를 부르게 한다","mis":"SC3-2-u3-X38"}],"explanation":["소리가 나는 곳을 찾아요.","색깔로 보여요.","큰 소리 나는 곳 찾기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_L08_challenge#10','sci',3,2,'u3','L08','g3_2_sci_u3_L08_challenge','lesson_challenge','SC3-2-u3-C16',4,'essay','teacher','음향 카메라가 소리를 어떻게 보여 주는지 소리의 세기·높낮이와 이어 쓰고, 음향 카메라를 쓸 수 있는 곳을 한 가지 생각해 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC3-2-u3-C16","difficulty":4,"kind":"essay","stem":"음향 카메라가 소리를 어떻게 보여 주는지 소리의 세기·높낮이와 이어 쓰고, 음향 카메라를 쓸 수 있는 곳을 한 가지 생각해 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 음향 카메라는 여러 개의 마이크가 달려 있고, 화면 속에 소리가 나는 곳을 색깔로 나타내며, 소리의 세기나 높낮이에 따라 색깔이 달라진다. 무인 비행기에 달면 재난 때 소리를 내는 조난자의 위치를 찾을 수 있다.","scoring_points":["소리가 나는 곳을 색깔로 보여 준다고 썼는가","색깔이 세기·높낮이에 따라 달라진다고 썼는가","쓸 수 있는 곳을 까닭과 함께 썼는가"]},"explanation":["화면을 떠올려요.","색깔과 성질을 이어요.","쓸 곳을 생각해요."],"asset":{"type":"passage","lines":["음향 카메라 — 여러 개의 마이크가 달려 있어요.","화면 — 소리가 나는 곳이 색깔로 나타나요.","색깔 — 소리의 세기나 높낮이에 따라 달라져요.","인공지능 — 섞인 소리 속에서 소리마다 세기와 높낮이를 구별해요."],"title":"음향 카메라 알아보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_a#1','sci',3,2,'u3','','g3_2_sci_u3_review_a','unit_review','SC3-2-u3-C1',1,'mc','auto','솔빛반 일기 ①에서 빗소리처럼 들린 소리는 어떻게 냈나요?',ARRAY['SC3-2-u3-X05','SC3-2-u3-X02']::text[],false,'{"seq":1,"concept":"SC3-2-u3-C1","difficulty":1,"kind":"mc","stem":"솔빛반 일기 ①에서 빗소리처럼 들린 소리는 어떻게 냈나요?","options":[{"t":"쌀을 넣은 페트병을 흔들어서","correct":true},{"t":"페트병을 연필로 문질러서","mis":"SC3-2-u3-X05"},{"t":"병 입구를 입으로 불어서","mis":"SC3-2-u3-X02"},{"t":"나무판을 자로 두드려서","mis":"SC3-2-u3-X02"}],"explanation":["첫 줄을 읽어요.","쌀이 부딪혀요.","흔들어서 냈어요."],"asset":{"type":"passage","lines":["쌀을 넣은 페트병을 흔들었더니 빗소리처럼 들렸다.","같은 페트병을 연필 옆면으로 문질렀더니 다른 소리가 났다.","약속 — 가위·유리컵은 쓰지 않고, 소리를 너무 크게 내지 않기"],"title":"솔빛반 일기 ① 소리 내기 놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_a#2','sci',3,2,'u3','','g3_2_sci_u3_review_a','unit_review','SC3-2-u3-C3',1,'mc','auto','솔빛반 일기 ②에서 친 소리굽쇠를 물 표면에 대니 어떻게 되었나요?',ARRAY['SC3-2-u3-X07']::text[],false,'{"seq":2,"concept":"SC3-2-u3-C3","difficulty":1,"kind":"mc","stem":"솔빛반 일기 ②에서 친 소리굽쇠를 물 표면에 대니 어떻게 되었나요?","options":[{"t":"물이 튀어 올랐다","correct":true},{"t":"물이 얼었다","mis":"SC3-2-u3-X07"},{"t":"물이 그대로였다","mis":"SC3-2-u3-X07"},{"t":"물이 뜨거워졌다","mis":"SC3-2-u3-X07"}],"explanation":["첫 줄을 읽어요.","떨림 때문이에요.","물이 튀어 올랐어요."],"asset":{"type":"passage","lines":["친 소리굽쇠를 물 표면에 대니 물이 튀어 올랐다.","목에 손을 대고 「아.」 하고 소리를 내니 떨림이 느껴졌다.","소리 나는 소리굽쇠를 손으로 꽉 잡으니 소리가 멈췄다."],"title":"솔빛반 일기 ② 소리굽쇠 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_a#3','sci',3,2,'u3','','g3_2_sci_u3_review_a','unit_review','SC3-2-u3-C6',1,'mc','auto','솔빛반 일기 ③에서 더 큰 소리가 난 작은북은 무엇인가요?',ARRAY['SC3-2-u3-X15','SC3-2-u3-X13']::text[],false,'{"seq":3,"concept":"SC3-2-u3-C6","difficulty":1,"kind":"mc","stem":"솔빛반 일기 ③에서 더 큰 소리가 난 작은북은 무엇인가요?","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"SC3-2-u3-X15"},{"t":"둘 다 같다","mis":"SC3-2-u3-X13"},{"t":"알 수 없다","mis":"SC3-2-u3-X15"}],"explanation":["퐁퐁이 높이를 봐요.","높게 튀었어요.","㉮예요."],"asset":{"type":"passage","lines":["㉮ 세게 친 작은북 — 퐁퐁이가 높게 튀어 올랐다.","㉯ 약하게 친 작은북 — 퐁퐁이가 낮게 튀어 올랐다.","디지털 탐구 도구로 두 소리의 크고 작은 정도를 견주었다."],"title":"솔빛반 일기 ③ 작은북 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_a#4','sci',3,2,'u3','','g3_2_sci_u3_review_a','unit_review','SC3-2-u3-C8',1,'mc','auto','솔빛반 일기 ④의 칼림바에서 가장 높은 소리가 나는 음판은 무엇인가요?',ARRAY['SC3-2-u3-X19','SC3-2-u3-X22']::text[],false,'{"seq":4,"concept":"SC3-2-u3-C8","difficulty":1,"kind":"mc","stem":"솔빛반 일기 ④의 칼림바에서 가장 높은 소리가 나는 음판은 무엇인가요?","options":[{"t":"가장 짧은 음판","correct":true},{"t":"가장 긴 음판","mis":"SC3-2-u3-X19"},{"t":"가운데 음판","mis":"SC3-2-u3-X19"},{"t":"모든 음판이 같다","mis":"SC3-2-u3-X22"}],"explanation":["길이가 달라요.","짧으면 높아요.","가장 짧은 음판이에요."],"asset":{"type":"passage","lines":["칼림바 — 길이가 서로 다른 음판을 하나씩 튕겼다.","팬 플루트 — 짧은 관과 긴 관을 차례로 불었다.","같은 음판을 세게도 쳐 보고 약하게도 쳐 보았다."],"title":"솔빛반 일기 ④ 칼림바와 팬 플루트"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_a#5','sci',3,2,'u3','','g3_2_sci_u3_review_a','unit_review','SC3-2-u3-C11',1,'mc','auto','솔빛반 일기 ⑤의 ㉢에서 목소리를 전달한 실은 어떤 상태의 물질인가요?',ARRAY['SC3-2-u3-X25','SC3-2-u3-X26']::text[],false,'{"seq":5,"concept":"SC3-2-u3-C11","difficulty":1,"kind":"mc","stem":"솔빛반 일기 ⑤의 ㉢에서 목소리를 전달한 실은 어떤 상태의 물질인가요?","options":[{"t":"고체","correct":true},{"t":"액체","mis":"SC3-2-u3-X25"},{"t":"기체","mis":"SC3-2-u3-X25"},{"t":"물질이 아니다","mis":"SC3-2-u3-X26"}],"explanation":["실을 떠올려요.","모양이 있어요.","고체예요."],"asset":{"type":"passage","lines":["㉠ 책상 끝에 귀를 대고 두드리는 소리를 셌다.","㉡ 수조 속 방수 스피커 소리를 관으로 들었다.","㉢ 실 전화기로 친구 목소리를 들었다.","선생님 — 「우주에서는 목소리를 들을 수 없어요.」"],"title":"솔빛반 일기 ⑤ 소리 전달 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_a#6','sci',3,2,'u3','','g3_2_sci_u3_review_a','unit_review','SC3-2-u3-C12',1,'mc','auto','솔빛반 일기 ⑥에서 책 읽기를 어렵게 한 소음은 무엇인가요?',ARRAY['SC3-2-u3-X27']::text[],false,'{"seq":6,"concept":"SC3-2-u3-C12","difficulty":1,"kind":"mc","stem":"솔빛반 일기 ⑥에서 책 읽기를 어렵게 한 소음은 무엇인가요?","options":[{"t":"공사장 소리","correct":true},{"t":"새소리","mis":"SC3-2-u3-X27"},{"t":"책장 넘기는 소리","mis":"SC3-2-u3-X27"},{"t":"친구의 작은 목소리","mis":"SC3-2-u3-X27"}],"explanation":["첫 줄을 읽어요.","너무 커요.","공사장 소리예요."],"asset":{"type":"passage","lines":["도서관 옆 공사장 소리가 너무 커서 책 읽기 어려웠다.","친구 가 — 「나는 빗소리가 좋아.」","친구 나 — 「나는 빗소리가 시끄러워.」","반 의견 — 공사장 주위에 방음벽을 세우면 좋겠다."],"title":"솔빛반 일기 ⑥ 소음 조사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_a#7','sci',3,2,'u3','','g3_2_sci_u3_review_a','unit_review','SC3-2-u3-C15',1,'mc','auto','솔빛반 일기 ⑦에서 일주일 동안 실천한 것을 어디에 기록했나요?',ARRAY['SC3-2-u3-X35']::text[],false,'{"seq":7,"concept":"SC3-2-u3-C15","difficulty":1,"kind":"mc","stem":"솔빛반 일기 ⑦에서 일주일 동안 실천한 것을 어디에 기록했나요?","options":[{"t":"실천표","correct":true},{"t":"달력에 가끔","mis":"SC3-2-u3-X35"},{"t":"기록하지 않았다","mis":"SC3-2-u3-X35"},{"t":"다른 모둠 공책","mis":"SC3-2-u3-X35"}],"explanation":["둘째 줄을 읽어요.","매일 적었어요.","실천표예요."],"asset":{"type":"passage","lines":["방법 — 집 안에서 실내화 신기, 텔레비전 소리 줄이기","실천표 — 일주일 동안 매일 기록했다.","잘한 점 — 아래층에서 조용해졌다고 고마워했다.","보완할 점 — 주말에 기록을 빠뜨렸다."],"title":"솔빛반 일기 ⑦ 실천 소개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_a#8','sci',3,2,'u3','','g3_2_sci_u3_review_a','unit_review','SC3-2-u3-C16',1,'mc','auto','솔빛반 일기 ⑧에서 화면 속 자동차 앞부분이 빨갛게 빛난 까닭은 무엇인가요?',ARRAY['SC3-2-u3-X37','SC3-2-u3-X36']::text[],false,'{"seq":8,"concept":"SC3-2-u3-C16","difficulty":1,"kind":"mc","stem":"솔빛반 일기 ⑧에서 화면 속 자동차 앞부분이 빨갛게 빛난 까닭은 무엇인가요?","options":[{"t":"그곳에서 소리가 나고 있어서","correct":true},{"t":"자동차가 빨간색이어서","mis":"SC3-2-u3-X37"},{"t":"날씨가 더워서","mis":"SC3-2-u3-X37"},{"t":"카메라가 소리를 키워서","mis":"SC3-2-u3-X36"}],"explanation":["음향 카메라예요.","소리가 나는 곳을 보여 줘요.","소리가 나고 있어서예요."],"asset":{"type":"passage","lines":["화면 속 자동차 앞부분이 빨갛게 빛났다.","여러 소리가 섞여 있었지만 고장 난 곳을 빨리 찾았다.","더 생각 — 무인 비행기에 달면 조난자를 찾을 수 있을 것 같다."],"title":"솔빛반 일기 ⑧ 음향 카메라 영상"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_a#9','sci',3,2,'u3','','g3_2_sci_u3_review_a','unit_review','SC3-2-u3-C1',2,'match','auto','솔빛반 소리 내기 놀이에서 쓴 물체와 소리 낸 방법을 알맞게 이으세요.','{}'::text[],false,'{"seq":9,"concept":"SC3-2-u3-C1","difficulty":2,"kind":"match","stem":"솔빛반 소리 내기 놀이에서 쓴 물체와 소리 낸 방법을 알맞게 이으세요.","pairs":[{"l":"나무판","r":"자로 두드려요"},{"l":"비닐봉지","r":"두 손으로 비벼요"},{"l":"쌀 넣은 페트병","r":"흔들어요"}],"mis":"SC3-2-u3-X02","explanation":["물체를 하나씩 떠올려요.","비닐봉지는 비벼요.","나무판-두드리기, 비닐봉지-비비기, 페트병-흔들기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_a#10','sci',3,2,'u3','','g3_2_sci_u3_review_a','unit_review','SC3-2-u3-C3',2,'mc','auto','「소리가 나는 물체인가?」로 나누었을 때 ✕ 쪽에 들어가는 것은 무엇인가요?',ARRAY['SC3-2-u3-X06']::text[],false,'{"seq":10,"concept":"SC3-2-u3-C3","difficulty":2,"kind":"mc","stem":"「소리가 나는 물체인가?」로 나누었을 때 ✕ 쪽에 들어가는 것은 무엇인가요?","options":[{"t":"치지 않은 종","correct":true},{"t":"소리가 나는 기타 줄","mis":"SC3-2-u3-X06"},{"t":"노래가 나오는 스피커","mis":"SC3-2-u3-X06"},{"t":"「아.」 하고 소리 내는 목","mis":"SC3-2-u3-X06"}],"explanation":["지금 소리가 나는지 봐요.","치지 않았어요.","치지 않은 종이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_a#11','sci',3,2,'u3','','g3_2_sci_u3_review_a','unit_review','SC3-2-u3-C6',2,'mc','auto','솔빛반 일기 ③에서 ㉮와 ㉯를 견준 결과로 알맞은 것은 무엇인가요?',ARRAY['SC3-2-u3-X13','SC3-2-u3-X14']::text[],false,'{"seq":11,"concept":"SC3-2-u3-C6","difficulty":2,"kind":"mc","stem":"솔빛반 일기 ③에서 ㉮와 ㉯를 견준 결과로 알맞은 것은 무엇인가요?","options":[{"t":"㉮가 ㉯보다 크게 떨려 큰 소리가 났다","correct":true},{"t":"㉯가 ㉮보다 크게 떨려 큰 소리가 났다","mis":"SC3-2-u3-X13"},{"t":"둘 다 떨림이 같았다","mis":"SC3-2-u3-X13"},{"t":"㉯는 떨리지 않았다","mis":"SC3-2-u3-X14"}],"explanation":["퐁퐁이 높이를 견줘요.","㉮가 높게 튀었어요.","㉮가 크게 떨렸어요."],"asset":{"type":"passage","lines":["㉮ 세게 친 작은북 — 퐁퐁이가 높게 튀어 올랐다.","㉯ 약하게 친 작은북 — 퐁퐁이가 낮게 튀어 올랐다.","디지털 탐구 도구로 두 소리의 크고 작은 정도를 견주었다."],"title":"솔빛반 일기 ③ 작은북 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_a#12','sci',3,2,'u3','','g3_2_sci_u3_review_a','unit_review','SC3-2-u3-C9',2,'mc','auto','솔빛반 일기 ④에서 같은 음판을 세게도 약하게도 쳤을 때 달라진 것은 무엇인가요?',ARRAY['SC3-2-u3-X21','SC3-2-u3-X22']::text[],false,'{"seq":12,"concept":"SC3-2-u3-C9","difficulty":2,"kind":"mc","stem":"솔빛반 일기 ④에서 같은 음판을 세게도 약하게도 쳤을 때 달라진 것은 무엇인가요?","options":[{"t":"소리의 세기","correct":true},{"t":"소리의 높낮이","mis":"SC3-2-u3-X21"},{"t":"음판의 길이","mis":"SC3-2-u3-X22"},{"t":"아무것도 달라지지 않았다","mis":"SC3-2-u3-X22"}],"explanation":["같은 음판이에요.","치는 세기만 달라요.","소리의 세기예요."],"asset":{"type":"passage","lines":["칼림바 — 길이가 서로 다른 음판을 하나씩 튕겼다.","팬 플루트 — 짧은 관과 긴 관을 차례로 불었다.","같은 음판을 세게도 쳐 보고 약하게도 쳐 보았다."],"title":"솔빛반 일기 ④ 칼림바와 팬 플루트"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_a#13','sci',3,2,'u3','','g3_2_sci_u3_review_a','unit_review','SC3-2-u3-C11',2,'mc','auto','솔빛반 일기 ⑤의 ㉠~㉢ 가운데 액체를 통해 소리가 전달된 것은 무엇인가요?',ARRAY['SC3-2-u3-X25','SC3-2-u3-X23']::text[],false,'{"seq":13,"concept":"SC3-2-u3-C11","difficulty":2,"kind":"mc","stem":"솔빛반 일기 ⑤의 ㉠~㉢ 가운데 액체를 통해 소리가 전달된 것은 무엇인가요?","options":[{"t":"㉡","correct":true},{"t":"㉠","mis":"SC3-2-u3-X25"},{"t":"㉢","mis":"SC3-2-u3-X25"},{"t":"없다","mis":"SC3-2-u3-X23"}],"explanation":["액체를 찾아요.","수조의 물이에요.","㉡이에요."],"asset":{"type":"passage","lines":["㉠ 책상 끝에 귀를 대고 두드리는 소리를 셌다.","㉡ 수조 속 방수 스피커 소리를 관으로 들었다.","㉢ 실 전화기로 친구 목소리를 들었다.","선생님 — 「우주에서는 목소리를 들을 수 없어요.」"],"title":"솔빛반 일기 ⑤ 소리 전달 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_a#14','sci',3,2,'u3','','g3_2_sci_u3_review_a','unit_review','SC3-2-u3-C13',2,'mc','auto','솔빛반 일기 ⑥에서 반 친구들이 고른 방법은 어떤 방법인가요?',ARRAY['SC3-2-u3-X31','SC3-2-u3-X30']::text[],false,'{"seq":14,"concept":"SC3-2-u3-C13","difficulty":2,"kind":"mc","stem":"솔빛반 일기 ⑥에서 반 친구들이 고른 방법은 어떤 방법인가요?","options":[{"t":"소리가 잘 전달되지 않게 하는 방법","correct":true},{"t":"소리의 세기를 줄이는 방법","mis":"SC3-2-u3-X31"},{"t":"소리를 더 크게 하는 방법","mis":"SC3-2-u3-X30"},{"t":"소음을 줄이는 방법이 아니다","mis":"SC3-2-u3-X30"}],"explanation":["방음벽이에요.","소리를 막아요.","잘 전달되지 않게 해요."],"asset":{"type":"passage","lines":["도서관 옆 공사장 소리가 너무 커서 책 읽기 어려웠다.","친구 가 — 「나는 빗소리가 좋아.」","친구 나 — 「나는 빗소리가 시끄러워.」","반 의견 — 공사장 주위에 방음벽을 세우면 좋겠다."],"title":"솔빛반 일기 ⑥ 소음 조사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_a#15','sci',3,2,'u3','','g3_2_sci_u3_review_a','unit_review','SC3-2-u3-C15',2,'mc','auto','솔빛반 일기 ⑦의 「보완할 점」을 고치는 방법으로 가장 알맞은 것은 무엇인가요?',ARRAY['SC3-2-u3-X35']::text[],false,'{"seq":15,"concept":"SC3-2-u3-C15","difficulty":2,"kind":"mc","stem":"솔빛반 일기 ⑦의 「보완할 점」을 고치는 방법으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"주말에도 기록하도록 알림을 정해 둔다","correct":true},{"t":"주말 칸은 지어서 채운다","mis":"SC3-2-u3-X35"},{"t":"기록을 그만둔다","mis":"SC3-2-u3-X35"},{"t":"다른 모둠 기록을 베낀다","mis":"SC3-2-u3-X35"}],"explanation":["주말에 빠뜨렸어요.","잊지 않게 해요.","알림을 정해요."],"asset":{"type":"passage","lines":["방법 — 집 안에서 실내화 신기, 텔레비전 소리 줄이기","실천표 — 일주일 동안 매일 기록했다.","잘한 점 — 아래층에서 조용해졌다고 고마워했다.","보완할 점 — 주말에 기록을 빠뜨렸다."],"title":"솔빛반 일기 ⑦ 실천 소개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_a#16','sci',3,2,'u3','','g3_2_sci_u3_review_a','unit_review','SC3-2-u3-C16',2,'mc','auto','솔빛반 일기 ⑧의 영상으로 알 수 있는 음향 카메라의 특징은 무엇인가요?',ARRAY['SC3-2-u3-X36','SC3-2-u3-X37','SC3-2-u3-X38']::text[],false,'{"seq":16,"concept":"SC3-2-u3-C16","difficulty":2,"kind":"mc","stem":"솔빛반 일기 ⑧의 영상으로 알 수 있는 음향 카메라의 특징은 무엇인가요?","options":[{"t":"소리가 나는 곳을 화면에 색깔로 보여 준다","correct":true},{"t":"소리를 더 크게 만든다","mis":"SC3-2-u3-X36"},{"t":"자동차 색을 바꾼다","mis":"SC3-2-u3-X37"},{"t":"고장 난 곳을 저절로 고친다","mis":"SC3-2-u3-X38"}],"explanation":["첫 줄을 읽어요.","빨갛게 빛났어요.","색깔로 보여 줘요."],"asset":{"type":"passage","lines":["화면 속 자동차 앞부분이 빨갛게 빛났다.","여러 소리가 섞여 있었지만 고장 난 곳을 빨리 찾았다.","더 생각 — 무인 비행기에 달면 조난자를 찾을 수 있을 것 같다."],"title":"솔빛반 일기 ⑧ 음향 카메라 영상"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_a#17','sci',3,2,'u3','','g3_2_sci_u3_review_a','unit_review','SC3-2-u3-C2',3,'error','auto','솔빛반 일기 ①을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-2-u3-X03','SC3-2-u3-X01','SC3-2-u3-X05']::text[],false,'{"seq":17,"concept":"SC3-2-u3-C2","difficulty":3,"kind":"error","stem":"솔빛반 일기 ①을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「유리컵을 숟가락으로 세게 치면 더 재미있는 소리가 날 거야.」","correct":true,"mis_target":"SC3-2-u3-X03"},{"t":"친구 가 — 「페트병은 방법을 바꾸면 다른 소리가 나.」","mis":"SC3-2-u3-X01"},{"t":"친구 나 — 「쌀을 넣고 흔든 소리가 빗소리 같았어.」","mis":"SC3-2-u3-X05"}],"explanation":["약속을 떠올려요.","유리는 쓰지 않아요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["쌀을 넣은 페트병을 흔들었더니 빗소리처럼 들렸다.","같은 페트병을 연필 옆면으로 문질렀더니 다른 소리가 났다.","약속 — 가위·유리컵은 쓰지 않고, 소리를 너무 크게 내지 않기"],"title":"솔빛반 일기 ① 소리 내기 놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_a#18','sci',3,2,'u3','','g3_2_sci_u3_review_a','unit_review','SC3-2-u3-C6',3,'error','auto','솔빛반 일기 ③을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-2-u3-X15','SC3-2-u3-X13','SC3-2-u3-X14']::text[],false,'{"seq":18,"concept":"SC3-2-u3-C6","difficulty":3,"kind":"error","stem":"솔빛반 일기 ③을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「㉯는 퐁퐁이가 낮게 튀었으니 더 세게 친 거야.」","correct":true,"mis_target":"SC3-2-u3-X15"},{"t":"친구 가 — 「㉮는 북면이 크게 떨렸어.」","mis":"SC3-2-u3-X13"},{"t":"친구 다 — 「㉯도 북면이 작게 떨렸어.」","mis":"SC3-2-u3-X14"}],"explanation":["㉯는 약하게 쳤어요.","낮게 튀었어요.","친구 나가 잘못 말했어요."],"asset":{"type":"passage","lines":["㉮ 세게 친 작은북 — 퐁퐁이가 높게 튀어 올랐다.","㉯ 약하게 친 작은북 — 퐁퐁이가 낮게 튀어 올랐다.","디지털 탐구 도구로 두 소리의 크고 작은 정도를 견주었다."],"title":"솔빛반 일기 ③ 작은북 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_a#19','sci',3,2,'u3','','g3_2_sci_u3_review_a','unit_review','SC3-2-u3-C8',3,'error','auto','솔빛반 일기 ④를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-2-u3-X19','SC3-2-u3-X18','SC3-2-u3-X21']::text[],false,'{"seq":19,"concept":"SC3-2-u3-C8","difficulty":3,"kind":"error","stem":"솔빛반 일기 ④를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「칼림바는 긴 음판일수록 높은 소리가 나.」","correct":true,"mis_target":"SC3-2-u3-X19"},{"t":"친구 나 — 「팬 플루트는 짧은 관이 높은 소리야.」","mis":"SC3-2-u3-X18"},{"t":"친구 다 — 「같은 음판을 세게 치면 소리만 커져.」","mis":"SC3-2-u3-X21"}],"explanation":["길이를 떠올려요.","길면 낮아요.","친구 가가 잘못 말했어요."],"asset":{"type":"passage","lines":["칼림바 — 길이가 서로 다른 음판을 하나씩 튕겼다.","팬 플루트 — 짧은 관과 긴 관을 차례로 불었다.","같은 음판을 세게도 쳐 보고 약하게도 쳐 보았다."],"title":"솔빛반 일기 ④ 칼림바와 팬 플루트"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_a#20','sci',3,2,'u3','','g3_2_sci_u3_review_a','unit_review','SC3-2-u3-C11',3,'error','auto','솔빛반 일기 ⑤를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-2-u3-X23','SC3-2-u3-X25']::text[],false,'{"seq":20,"concept":"SC3-2-u3-C11","difficulty":3,"kind":"error","stem":"솔빛반 일기 ⑤를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「㉠은 귀를 책상에 댔지만 소리는 공기로만 왔어.」","correct":true,"mis_target":"SC3-2-u3-X23"},{"t":"친구 가 — 「㉢은 고체인 실로 소리가 전달됐어.」","mis":"SC3-2-u3-X25"},{"t":"친구 나 — 「㉡은 액체인 물로도 소리가 전달됐어.」","mis":"SC3-2-u3-X25"}],"explanation":["㉠은 책상이에요.","고체도 전해요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["㉠ 책상 끝에 귀를 대고 두드리는 소리를 셌다.","㉡ 수조 속 방수 스피커 소리를 관으로 들었다.","㉢ 실 전화기로 친구 목소리를 들었다.","선생님 — 「우주에서는 목소리를 들을 수 없어요.」"],"title":"솔빛반 일기 ⑤ 소리 전달 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_a#21','sci',3,2,'u3','','g3_2_sci_u3_review_a','unit_review','SC3-2-u3-C13',3,'error','auto','솔빛반 일기 ⑥의 공사장 소음을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-2-u3-X30','SC3-2-u3-X31']::text[],false,'{"seq":21,"concept":"SC3-2-u3-C13","difficulty":3,"kind":"error","stem":"솔빛반 일기 ⑥의 공사장 소음을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「도서관 창문을 활짝 열어 소리를 내보내자.」","correct":true,"mis_target":"SC3-2-u3-X30"},{"t":"친구 가 — 「공사장 주위에 방음벽을 세우자.」","mis":"SC3-2-u3-X31"},{"t":"친구 다 — 「도서관 창문을 닫고 커튼을 치자.」","mis":"SC3-2-u3-X31"}],"explanation":["창문을 열면?","소리가 더 들어와요.","친구 나가 잘못 말했어요."],"asset":{"type":"passage","lines":["도서관 옆 공사장 소리가 너무 커서 책 읽기 어려웠다.","친구 가 — 「나는 빗소리가 좋아.」","친구 나 — 「나는 빗소리가 시끄러워.」","반 의견 — 공사장 주위에 방음벽을 세우면 좋겠다."],"title":"솔빛반 일기 ⑥ 소음 조사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_a#22','sci',3,2,'u3','','g3_2_sci_u3_review_a','unit_review','SC3-2-u3-C15',3,'error','auto','솔빛반 일기 ⑦을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-2-u3-X35','SC3-2-u3-X34']::text[],false,'{"seq":22,"concept":"SC3-2-u3-C15","difficulty":3,"kind":"error","stem":"솔빛반 일기 ⑦을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「주말 기록을 빠뜨렸으니 실천이 다 소용없어.」","correct":true,"mis_target":"SC3-2-u3-X35"},{"t":"친구 나 — 「아래층에서 고마워했으니 잘한 점이야.」","mis":"SC3-2-u3-X34"},{"t":"친구 다 — 「주말에도 기록하도록 알림을 정하자.」","mis":"SC3-2-u3-X35"}],"explanation":["보완할 점은 고치면 돼요.","잘한 점도 있어요.","친구 가가 잘못 말했어요."],"asset":{"type":"passage","lines":["방법 — 집 안에서 실내화 신기, 텔레비전 소리 줄이기","실천표 — 일주일 동안 매일 기록했다.","잘한 점 — 아래층에서 조용해졌다고 고마워했다.","보완할 점 — 주말에 기록을 빠뜨렸다."],"title":"솔빛반 일기 ⑦ 실천 소개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_a#23','sci',3,2,'u3','','g3_2_sci_u3_review_a','unit_review','SC3-2-u3-C3',4,'essay','teacher','솔빛반 일기 ②를 보고 소리가 나는 물체의 특징을 관찰 결과 두 가지와 함께 쓰고, 소리를 멈추게 하는 방법과 그 까닭을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"SC3-2-u3-C3","difficulty":4,"kind":"essay","stem":"솔빛반 일기 ②를 보고 소리가 나는 물체의 특징을 관찰 결과 두 가지와 함께 쓰고, 소리를 멈추게 하는 방법과 그 까닭을 쓰세요.","answer_guide":{"answer":"예: 친 소리굽쇠를 물 표면에 대니 물이 튀어 올랐고, 「아.」 하고 소리를 낼 때 목에 손을 대니 떨림이 느껴졌다. 소리가 나는 물체는 떨림이 있다. 소리굽쇠를 손으로 꽉 잡으면 떨림이 멈추어 소리도 멈춘다.","scoring_points":["관찰 결과 두 가지를 썼는가","소리가 나는 물체는 떨림이 있다고 썼는가","소리를 멈추는 방법을 떨림과 이어 썼는가"]},"explanation":["일기를 읽어요.","특징을 써요.","멈추는 방법을 써요."],"asset":{"type":"passage","lines":["친 소리굽쇠를 물 표면에 대니 물이 튀어 올랐다.","목에 손을 대고 「아.」 하고 소리를 내니 떨림이 느껴졌다.","소리 나는 소리굽쇠를 손으로 꽉 잡으니 소리가 멈췄다."],"title":"솔빛반 일기 ② 소리굽쇠 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_a#24','sci',3,2,'u3','','g3_2_sci_u3_review_a','unit_review','SC3-2-u3-C4',4,'mc','auto','「소리가 나는 물체는 떨림이 있다」를 확인하는 방법으로 가장 알맞은 것은 무엇인가요?',ARRAY['SC3-2-u3-X08','SC3-2-u3-X06','SC3-2-u3-X09']::text[],false,'{"seq":24,"concept":"SC3-2-u3-C4","difficulty":4,"kind":"mc","stem":"「소리가 나는 물체는 떨림이 있다」를 확인하는 방법으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"소리가 날 때와 나지 않을 때 소리굽쇠에 손을 대 보고 견준다","correct":true},{"t":"소리굽쇠를 귀로만 듣고 결과를 적는다","mis":"SC3-2-u3-X08"},{"t":"치지 않은 소리굽쇠만 손으로 만져 본다","mis":"SC3-2-u3-X06"},{"t":"소리굽쇠를 손으로 잡은 채 쳐서 떨림을 막는다","mis":"SC3-2-u3-X09"}],"explanation":["견주어야 알 수 있어요.","소리가 날 때와 안 날 때예요.","두 경우를 견줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_a#25','sci',3,2,'u3','','g3_2_sci_u3_review_a','unit_review','SC3-2-u3-C13',4,'essay','teacher','솔빛반 일기 ⑥의 공사장 소음을 줄이는 방법을 두 가지 방법에 맞게 하나씩 쓰고, 같은 빗소리를 두고 두 친구의 생각이 다른 까닭을 소음의 뜻과 이어 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC3-2-u3-C13","difficulty":4,"kind":"essay","stem":"솔빛반 일기 ⑥의 공사장 소음을 줄이는 방법을 두 가지 방법에 맞게 하나씩 쓰고, 같은 빗소리를 두고 두 친구의 생각이 다른 까닭을 소음의 뜻과 이어 쓰세요.","answer_guide":{"answer":"예: 공사 기계 소리를 작게 하는 것은 소리의 세기를 줄이는 방법이고, 공사장 주위에 방음벽을 세우는 것은 소리가 잘 전달되지 않게 하는 방법이다. 소음은 불쾌감이나 고통을 주는 소리인데, 같은 빗소리도 친구 가에게는 좋은 소리이고 친구 나에게는 불쾌한 소리라서 생각이 다르다.","scoring_points":["세기를 줄이는 방법을 썼는가","잘 전달되지 않게 하는 방법을 썼는가","생각이 다른 까닭을 소음의 뜻과 이어 썼는가"]},"explanation":["두 방법을 떠올려요.","하나씩 써요.","소음의 뜻과 이어요."],"asset":{"type":"passage","lines":["도서관 옆 공사장 소리가 너무 커서 책 읽기 어려웠다.","친구 가 — 「나는 빗소리가 좋아.」","친구 나 — 「나는 빗소리가 시끄러워.」","반 의견 — 공사장 주위에 방음벽을 세우면 좋겠다."],"title":"솔빛반 일기 ⑥ 소음 조사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_b#1','sci',3,2,'u3','','g3_2_sci_u3_review_b','unit_review','SC3-2-u3-C2',1,'sa','auto','솔빛반 일기 ①의 약속에서 쓰지 않기로 한 물체를 하나 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SC3-2-u3-C2","difficulty":1,"kind":"sa","stem":"솔빛반 일기 ①의 약속에서 쓰지 않기로 한 물체를 하나 쓰세요.","answer":["가위","유리컵"],"explanation":["약속 줄을 읽어요.","다칠 수 있어요.","가위나 유리컵이에요."],"asset":{"type":"passage","lines":["쌀을 넣은 페트병을 흔들었더니 빗소리처럼 들렸다.","같은 페트병을 연필 옆면으로 문질렀더니 다른 소리가 났다.","약속 — 가위·유리컵은 쓰지 않고, 소리를 너무 크게 내지 않기"],"title":"솔빛반 일기 ① 소리 내기 놀이"},"mis":"SC3-2-u3-X03"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_b#2','sci',3,2,'u3','','g3_2_sci_u3_review_b','unit_review','SC3-2-u3-C3',1,'sa','auto','솔빛반 일기 ②에서 목에 손을 댔을 때 느낀 것을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC3-2-u3-C3","difficulty":1,"kind":"sa","stem":"솔빛반 일기 ②에서 목에 손을 댔을 때 느낀 것을 두 글자로 쓰세요.","answer":["떨림"],"explanation":["둘째 줄을 읽어요.","소리가 날 때 느껴요.","떨림이에요."],"asset":{"type":"passage","lines":["친 소리굽쇠를 물 표면에 대니 물이 튀어 올랐다.","목에 손을 대고 「아.」 하고 소리를 내니 떨림이 느껴졌다.","소리 나는 소리굽쇠를 손으로 꽉 잡으니 소리가 멈췄다."],"title":"솔빛반 일기 ② 소리굽쇠 관찰"},"mis":"SC3-2-u3-X06"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_b#3','sci',3,2,'u3','','g3_2_sci_u3_review_b','unit_review','SC3-2-u3-C5',1,'sa','auto','응원 소리와 귓속말은 소리의 무엇이 다른가요? 「소리의 ○○」에서 ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SC3-2-u3-C5","difficulty":1,"kind":"sa","stem":"응원 소리와 귓속말은 소리의 무엇이 다른가요? 「소리의 ○○」에서 ○○에 알맞은 두 글자를 쓰세요.","answer":["세기"],"explanation":["크고 작은 정도예요.","세◯예요.","세기예요."],"mis":"SC3-2-u3-X11"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_b#4','sci',3,2,'u3','','g3_2_sci_u3_review_b','unit_review','SC3-2-u3-C7',1,'sa','auto','소리의 높고 낮은 정도를 「소리의 ○○○」라고 해요. ○○○에 알맞은 세 글자를 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC3-2-u3-C7","difficulty":1,"kind":"sa","stem":"소리의 높고 낮은 정도를 「소리의 ○○○」라고 해요. ○○○에 알맞은 세 글자를 쓰세요.","answer":["높낮이"],"explanation":["높고 낮은 정도예요.","높◯◯예요.","높낮이예요."],"mis":"SC3-2-u3-X17"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_b#5','sci',3,2,'u3','','g3_2_sci_u3_review_b','unit_review','SC3-2-u3-C11',1,'sa','auto','솔빛반 일기 ⑤의 ㉡에서 수조에 담겨 소리를 전달한 액체를 한 글자로 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"SC3-2-u3-C11","difficulty":1,"kind":"sa","stem":"솔빛반 일기 ⑤의 ㉡에서 수조에 담겨 소리를 전달한 액체를 한 글자로 쓰세요.","answer":["물"],"explanation":["수조에 있어요.","액체예요.","물이에요."],"asset":{"type":"passage","lines":["㉠ 책상 끝에 귀를 대고 두드리는 소리를 셌다.","㉡ 수조 속 방수 스피커 소리를 관으로 들었다.","㉢ 실 전화기로 친구 목소리를 들었다.","선생님 — 「우주에서는 목소리를 들을 수 없어요.」"],"title":"솔빛반 일기 ⑤ 소리 전달 실험"},"mis":"SC3-2-u3-X23"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_b#6','sci',3,2,'u3','','g3_2_sci_u3_review_b','unit_review','SC3-2-u3-C13',1,'sa','auto','솔빛반 일기 ⑥에서 반 친구들이 공사장 주위에 세우자고 한 것을 세 글자로 쓰세요.','{}'::text[],false,'{"seq":6,"concept":"SC3-2-u3-C13","difficulty":1,"kind":"sa","stem":"솔빛반 일기 ⑥에서 반 친구들이 공사장 주위에 세우자고 한 것을 세 글자로 쓰세요.","answer":["방음벽"],"explanation":["마지막 줄을 읽어요.","방◯◯이에요.","방음벽이에요."],"asset":{"type":"passage","lines":["도서관 옆 공사장 소리가 너무 커서 책 읽기 어려웠다.","친구 가 — 「나는 빗소리가 좋아.」","친구 나 — 「나는 빗소리가 시끄러워.」","반 의견 — 공사장 주위에 방음벽을 세우면 좋겠다."],"title":"솔빛반 일기 ⑥ 소음 조사"},"mis":"SC3-2-u3-X30"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_b#7','sci',3,2,'u3','','g3_2_sci_u3_review_b','unit_review','SC3-2-u3-C14',1,'sa','auto','솔빛반 일기 ⑦에서 발소리를 줄이려고 집 안에서 신은 것을 세 글자로 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"SC3-2-u3-C14","difficulty":1,"kind":"sa","stem":"솔빛반 일기 ⑦에서 발소리를 줄이려고 집 안에서 신은 것을 세 글자로 쓰세요.","answer":["실내화"],"explanation":["첫 줄을 읽어요.","실◯◯예요.","실내화예요."],"asset":{"type":"passage","lines":["방법 — 집 안에서 실내화 신기, 텔레비전 소리 줄이기","실천표 — 일주일 동안 매일 기록했다.","잘한 점 — 아래층에서 조용해졌다고 고마워했다.","보완할 점 — 주말에 기록을 빠뜨렸다."],"title":"솔빛반 일기 ⑦ 실천 소개"},"mis":"SC3-2-u3-X32"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_b#8','sci',3,2,'u3','','g3_2_sci_u3_review_b','unit_review','SC3-2-u3-C16',1,'sa','auto','소리가 나는 곳을 화면에 색깔로 보여 주는 기기를 「○○ 카메라」라고 해요. ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SC3-2-u3-C16","difficulty":1,"kind":"sa","stem":"소리가 나는 곳을 화면에 색깔로 보여 주는 기기를 「○○ 카메라」라고 해요. ○○에 알맞은 두 글자를 쓰세요.","answer":["음향"],"explanation":["소리를 찍어요.","음◯이에요.","음향이에요."],"mis":"SC3-2-u3-X36"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_b#9','sci',3,2,'u3','','g3_2_sci_u3_review_b','unit_review','SC3-2-u3-C2',2,'mc','auto','솔빛반 일기 ①의 약속에 맞게 행동한 것은 무엇인가요?',ARRAY['SC3-2-u3-X03']::text[],false,'{"seq":9,"concept":"SC3-2-u3-C2","difficulty":2,"kind":"mc","stem":"솔빛반 일기 ①의 약속에 맞게 행동한 것은 무엇인가요?","options":[{"t":"알루미늄 캔을 손가락으로 톡톡 두드린다","correct":true},{"t":"유리컵을 숟가락으로 세게 친다","mis":"SC3-2-u3-X03"},{"t":"가위를 흔들어 소리를 낸다","mis":"SC3-2-u3-X03"},{"t":"친구 귀에 대고 크게 소리친다","mis":"SC3-2-u3-X03"}],"explanation":["약속 줄을 읽어요.","다치지 않아요.","캔을 두드려요."],"asset":{"type":"passage","lines":["쌀을 넣은 페트병을 흔들었더니 빗소리처럼 들렸다.","같은 페트병을 연필 옆면으로 문질렀더니 다른 소리가 났다.","약속 — 가위·유리컵은 쓰지 않고, 소리를 너무 크게 내지 않기"],"title":"솔빛반 일기 ① 소리 내기 놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_b#10','sci',3,2,'u3','','g3_2_sci_u3_review_b','unit_review','SC3-2-u3-C4',2,'match','auto','관찰한 것과 쓴 감각을 알맞게 이으세요.','{}'::text[],false,'{"seq":10,"concept":"SC3-2-u3-C4","difficulty":2,"kind":"match","stem":"관찰한 것과 쓴 감각을 알맞게 이으세요.","pairs":[{"l":"튀어 오르는 탁구공","r":"눈으로 봐요"},{"l":"소리굽쇠의 떨림","r":"손으로 느껴요"},{"l":"소리굽쇠의 소리","r":"귀로 들어요"}],"mis":"SC3-2-u3-X08","explanation":["감각을 나눠요.","튀어 오르는 건 봐요.","탁구공-눈, 떨림-손, 소리-귀예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_b#11','sci',3,2,'u3','','g3_2_sci_u3_review_b','unit_review','SC3-2-u3-C5',2,'match','auto','상황과 알맞은 소리를 이으세요.','{}'::text[],false,'{"seq":11,"concept":"SC3-2-u3-C5","difficulty":2,"kind":"match","stem":"상황과 알맞은 소리를 이으세요.","pairs":[{"l":"운동회에서 응원하기","r":"큰 소리"},{"l":"도서관에서 친구에게 말하기","r":"작은 소리"},{"l":"먼 곳의 친구를 부르기","r":"멀리까지 들리는 큰 소리"}],"mis":"SC3-2-u3-X12","explanation":["누가 들어야 하나요?","도서관은 조용해요.","응원-큰, 도서관-작은, 먼 곳-멀리까지 큰 소리예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_b#12','sci',3,2,'u3','','g3_2_sci_u3_review_b','unit_review','SC3-2-u3-C8',2,'match','auto','악기와 높은 소리를 내는 방법을 알맞게 이으세요.','{}'::text[],false,'{"seq":12,"concept":"SC3-2-u3-C8","difficulty":2,"kind":"match","stem":"악기와 높은 소리를 내는 방법을 알맞게 이으세요.","pairs":[{"l":"팬 플루트","r":"짧은 관을 불어요"},{"l":"글로켄슈필","r":"짧은 음판을 두드려요"},{"l":"고무줄 간이 악기","r":"고무줄을 짧게 잡고 튕겨요"}],"mis":"SC3-2-u3-X19","explanation":["높은 소리예요.","짧은 것을 써요.","셋 다 짧은 쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_b#13','sci',3,2,'u3','','g3_2_sci_u3_review_b','unit_review','SC3-2-u3-C11',2,'match','auto','물질과 그 상태를 알맞게 이으세요.','{}'::text[],false,'{"seq":13,"concept":"SC3-2-u3-C11","difficulty":2,"kind":"match","stem":"물질과 그 상태를 알맞게 이으세요.","pairs":[{"l":"나무 책상","r":"고체"},{"l":"바닷물","r":"액체"},{"l":"운동장의 공기","r":"기체"}],"mis":"SC3-2-u3-X25","explanation":["상태를 떠올려요.","바닷물은 흘러요.","책상-고체, 바닷물-액체, 공기-기체예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_b#14','sci',3,2,'u3','','g3_2_sci_u3_review_b','unit_review','SC3-2-u3-C13',2,'match','auto','소음과 알맞은 줄이는 방법을 이으세요.','{}'::text[],false,'{"seq":14,"concept":"SC3-2-u3-C13","difficulty":2,"kind":"match","stem":"소음과 알맞은 줄이는 방법을 이으세요.","pairs":[{"l":"운동장에서 들어오는 소리","r":"교실 창문에 커튼을 달아요"},{"l":"길거리 스피커의 큰 노랫소리","r":"스피커 소리를 줄여요"},{"l":"바깥 자동차 소리","r":"창틀에 이중창을 달아요"}],"mis":"SC3-2-u3-X32","explanation":["소음이 오는 곳을 봐요.","스피커는 작게 해요.","운동장-커튼, 스피커-줄이기, 자동차-이중창이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_b#15','sci',3,2,'u3','','g3_2_sci_u3_review_b','unit_review','SC3-2-u3-C14',2,'match','auto','층간 소음과 줄이는 실천을 알맞게 이으세요.','{}'::text[],false,'{"seq":15,"concept":"SC3-2-u3-C14","difficulty":2,"kind":"match","stem":"층간 소음과 줄이는 실천을 알맞게 이으세요.","pairs":[{"l":"늦은 밤 세탁기 소리","r":"고무 받침대를 붙여요"},{"l":"크게 틀어 놓은 텔레비전","r":"소리를 작게 해요"},{"l":"집 안에서 걷는 발걸음","r":"양말이나 실내화를 신어요"}],"mis":"SC3-2-u3-X32","explanation":["소음을 하나씩 봐요.","발걸음은 신어요.","세탁기-받침대, 텔레비전-작게, 발걸음-실내화예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_b#16','sci',3,2,'u3','','g3_2_sci_u3_review_b','unit_review','SC3-2-u3-C17',2,'match','auto','음향 카메라를 쓸 수 있는 곳과 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":16,"concept":"SC3-2-u3-C17","difficulty":2,"kind":"match","stem":"음향 카메라를 쓸 수 있는 곳과 하는 일을 알맞게 이으세요.","pairs":[{"l":"자동차 수리","r":"고장 난 곳을 빠르게 찾아요"},{"l":"기계 점검","r":"고장 난 부분의 소리를 찾아요"},{"l":"무인 비행기","r":"재난 때 조난자의 위치를 찾아요"}],"mis":"SC3-2-u3-X38","explanation":["쓰임을 떠올려요.","하늘에서는 조난자예요.","자동차-고장, 기계-부분, 비행기-조난자예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_b#17','sci',3,2,'u3','','g3_2_sci_u3_review_b','unit_review','SC3-2-u3-C3',3,'mc','auto','솔빛반 일기 ①의 페트병과 ②의 소리굽쇠가 소리를 낼 때의 공통점으로 알맞은 것은 무엇인가요?',ARRAY['SC3-2-u3-X01','SC3-2-u3-X06','SC3-2-u3-X08']::text[],false,'{"seq":17,"concept":"SC3-2-u3-C3","difficulty":3,"kind":"mc","stem":"솔빛반 일기 ①의 페트병과 ②의 소리굽쇠가 소리를 낼 때의 공통점으로 알맞은 것은 무엇인가요?","options":[{"t":"소리가 날 때 떨림이 있다","correct":true},{"t":"둘 다 한 가지 소리만 낸다","mis":"SC3-2-u3-X01"},{"t":"둘 다 소리가 나지 않을 때도 떨린다","mis":"SC3-2-u3-X06"},{"t":"둘 다 귀로만 관찰할 수 있다","mis":"SC3-2-u3-X08"}],"explanation":["소리가 나는 물체예요.","공통 특징이에요.","떨림이 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_b#18','sci',3,2,'u3','','g3_2_sci_u3_review_b','unit_review','SC3-2-u3-C9',3,'mc','auto','같은 작은북을 세게 칠 때와 약하게 칠 때 달라지는 것은 무엇인가요?',ARRAY['SC3-2-u3-X21','SC3-2-u3-X13']::text[],false,'{"seq":18,"concept":"SC3-2-u3-C9","difficulty":3,"kind":"mc","stem":"같은 작은북을 세게 칠 때와 약하게 칠 때 달라지는 것은 무엇인가요?","options":[{"t":"북면이 떨리는 크기와 소리의 세기","correct":true},{"t":"북의 길이와 소리의 높낮이","mis":"SC3-2-u3-X21"},{"t":"소리의 높낮이만","mis":"SC3-2-u3-X21"},{"t":"아무것도 달라지지 않는다","mis":"SC3-2-u3-X13"}],"explanation":["같은 북이에요.","치는 세기가 달라요.","떨림의 크기와 세기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_b#19','sci',3,2,'u3','','g3_2_sci_u3_review_b','unit_review','SC3-2-u3-C9',3,'mc','auto','「높은 소리」와 「큰 소리」를 바르게 견준 것은 무엇인가요?',ARRAY['SC3-2-u3-X22']::text[],false,'{"seq":19,"concept":"SC3-2-u3-C9","difficulty":3,"kind":"mc","stem":"「높은 소리」와 「큰 소리」를 바르게 견준 것은 무엇인가요?","options":[{"t":"높은 소리는 높낮이, 큰 소리는 세기에 대한 말이다","correct":true},{"t":"둘 다 세기에 대한 말이다","mis":"SC3-2-u3-X22"},{"t":"둘 다 높낮이에 대한 말이다","mis":"SC3-2-u3-X22"},{"t":"높은 소리는 세기, 큰 소리는 높낮이에 대한 말이다","mis":"SC3-2-u3-X22"}],"explanation":["높고 낮음, 크고 작음이에요.","서로 달라요.","높낮이와 세기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_b#20','sci',3,2,'u3','','g3_2_sci_u3_review_b','unit_review','SC3-2-u3-C11',3,'mc','auto','솔빛반 일기 ⑤의 ㉠~㉢에서 소리를 전달한 물질의 상태를 바르게 짝지은 것은 무엇인가요?',ARRAY['SC3-2-u3-X23','SC3-2-u3-X25']::text[],false,'{"seq":20,"concept":"SC3-2-u3-C11","difficulty":3,"kind":"mc","stem":"솔빛반 일기 ⑤의 ㉠~㉢에서 소리를 전달한 물질의 상태를 바르게 짝지은 것은 무엇인가요?","options":[{"t":"㉠ 고체 · ㉡ 액체 · ㉢ 고체","correct":true},{"t":"㉠ 기체 · ㉡ 액체 · ㉢ 기체","mis":"SC3-2-u3-X23"},{"t":"㉠ 고체 · ㉡ 기체 · ㉢ 액체","mis":"SC3-2-u3-X25"},{"t":"㉠ 액체 · ㉡ 고체 · ㉢ 고체","mis":"SC3-2-u3-X25"}],"explanation":["책상, 물, 실이에요.","상태를 떠올려요.","고체·액체·고체예요."],"asset":{"type":"passage","lines":["㉠ 책상 끝에 귀를 대고 두드리는 소리를 셌다.","㉡ 수조 속 방수 스피커 소리를 관으로 들었다.","㉢ 실 전화기로 친구 목소리를 들었다.","선생님 — 「우주에서는 목소리를 들을 수 없어요.」"],"title":"솔빛반 일기 ⑤ 소리 전달 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_b#21','sci',3,2,'u3','','g3_2_sci_u3_review_b','unit_review','SC3-2-u3-C13',3,'mc','auto','공사장 소음을 줄이는 방법을 두 가지 방법으로 바르게 나눈 것은 무엇인가요?',ARRAY['SC3-2-u3-X31','SC3-2-u3-X30']::text[],false,'{"seq":21,"concept":"SC3-2-u3-C13","difficulty":3,"kind":"mc","stem":"공사장 소음을 줄이는 방법을 두 가지 방법으로 바르게 나눈 것은 무엇인가요?","options":[{"t":"공사 기계 소리 작게 하기 — 세기 줄이기 · 방음벽 세우기 — 잘 전달되지 않게 하기","correct":true},{"t":"공사 기계 소리 작게 하기 — 잘 전달되지 않게 하기 · 방음벽 세우기 — 세기 줄이기","mis":"SC3-2-u3-X31"},{"t":"두 가지 모두 세기 줄이기","mis":"SC3-2-u3-X31"},{"t":"두 가지 모두 소음을 줄이는 방법이 아니다","mis":"SC3-2-u3-X30"}],"explanation":["작게 하나요, 막나요?","방음벽은 막아요.","작게-세기, 방음벽-전달이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_b#22','sci',3,2,'u3','','g3_2_sci_u3_review_b','unit_review','SC3-2-u3-C16',3,'mc','auto','음향 카메라와 우리 귀를 견준 것으로 알맞은 것은 무엇인가요?',ARRAY['SC3-2-u3-X36','SC3-2-u3-X37']::text[],false,'{"seq":22,"concept":"SC3-2-u3-C16","difficulty":3,"kind":"mc","stem":"음향 카메라와 우리 귀를 견준 것으로 알맞은 것은 무엇인가요?","options":[{"t":"귀는 소리를 듣고, 음향 카메라는 소리가 나는 곳을 눈으로 보게 해 준다","correct":true},{"t":"귀도 소리를 색깔로 본다","mis":"SC3-2-u3-X36"},{"t":"음향 카메라는 소리를 크게 키워 귀에 들려준다","mis":"SC3-2-u3-X36"},{"t":"음향 카메라는 날씨에 따라 색을 바꾼다","mis":"SC3-2-u3-X37"}],"explanation":["귀는 들어요.","카메라는 보여 줘요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_b#23','sci',3,2,'u3','','g3_2_sci_u3_review_b','unit_review','SC3-2-u3-C6',4,'essay','teacher','솔빛반 일기 ③을 보고 ㉮와 ㉯의 소리를 북면의 떨림과 이어 견주고, 큰 소리를 낼 때 지킬 약속을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"SC3-2-u3-C6","difficulty":4,"kind":"essay","stem":"솔빛반 일기 ③을 보고 ㉮와 ㉯의 소리를 북면의 떨림과 이어 견주고, 큰 소리를 낼 때 지킬 약속을 쓰세요.","answer_guide":{"answer":"예: ㉮는 세게 쳐서 북면이 크게 떨렸고 퐁퐁이가 높게 튀며 큰 소리가 났다. ㉯는 약하게 쳐서 북면이 작게 떨렸고 퐁퐁이가 낮게 튀며 작은 소리가 났다. 너무 큰 소리는 귀를 다치게 할 수 있으니 지나치게 세게 치지 않는다.","scoring_points":["㉮의 떨림과 소리를 썼는가","㉯의 떨림과 소리를 썼는가","귀를 지키는 약속을 썼는가"]},"explanation":["㉮와 ㉯를 견줘요.","떨림과 이어요.","약속을 써요."],"asset":{"type":"passage","lines":["㉮ 세게 친 작은북 — 퐁퐁이가 높게 튀어 올랐다.","㉯ 약하게 친 작은북 — 퐁퐁이가 낮게 튀어 올랐다.","디지털 탐구 도구로 두 소리의 크고 작은 정도를 견주었다."],"title":"솔빛반 일기 ③ 작은북 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_b#24','sci',3,2,'u3','','g3_2_sci_u3_review_b','unit_review','SC3-2-u3-C9',4,'mc','auto','친구가 「작은북을 세게 쳤더니 높은 소리가 났어.」라고 말했어요. 바르게 고친 말과 까닭으로 알맞은 것은 무엇인가요?',ARRAY['SC3-2-u3-X21','SC3-2-u3-X13']::text[],false,'{"seq":24,"concept":"SC3-2-u3-C9","difficulty":4,"kind":"mc","stem":"친구가 「작은북을 세게 쳤더니 높은 소리가 났어.」라고 말했어요. 바르게 고친 말과 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"「큰 소리가 났어.」 — 세게 치면 떨림이 커져 소리의 세기가 커지기 때문이다","correct":true},{"t":"「낮은 소리가 났어.」 — 세게 치면 소리가 낮아지기 때문이다","mis":"SC3-2-u3-X21"},{"t":"「작은 소리가 났어.」 — 세게 치면 떨림이 작아지기 때문이다","mis":"SC3-2-u3-X13"},{"t":"고칠 것이 없다 — 세게 치면 소리가 높아지기 때문이다","mis":"SC3-2-u3-X21"}],"explanation":["세게 쳤어요.","세기가 달라져요.","큰 소리예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_b#25','sci',3,2,'u3','','g3_2_sci_u3_review_b','unit_review','SC3-2-u3-C15',4,'essay','teacher','솔빛반 일기 ⑦을 보고 이 모둠의 실천에서 잘한 점과 보완할 점을 하나씩 쓰고, 공동체의 소음 문제를 함께 해결해야 하는 까닭을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC3-2-u3-C15","difficulty":4,"kind":"essay","stem":"솔빛반 일기 ⑦을 보고 이 모둠의 실천에서 잘한 점과 보완할 점을 하나씩 쓰고, 공동체의 소음 문제를 함께 해결해야 하는 까닭을 쓰세요.","answer_guide":{"answer":"예: 잘한 점은 일주일 동안 실내화를 신고 텔레비전 소리를 줄여 아래층이 조용해진 것이다. 보완할 점은 주말에 기록을 빠뜨린 것이라 알림을 정해 두면 좋겠다. 내 집의 소리도 이웃에게 소음이 될 수 있으니 모두 함께 노력해야 한다.","scoring_points":["잘한 점을 썼는가","보완할 점을 고칠 방법과 함께 썼는가","함께 해결해야 하는 까닭을 썼는가"]},"explanation":["일기를 읽어요.","잘한 점부터 써요.","까닭을 써요."],"asset":{"type":"passage","lines":["방법 — 집 안에서 실내화 신기, 텔레비전 소리 줄이기","실천표 — 일주일 동안 매일 기록했다.","잘한 점 — 아래층에서 조용해졌다고 고마워했다.","보완할 점 — 주말에 기록을 빠뜨렸다."],"title":"솔빛반 일기 ⑦ 실천 소개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_c#1','sci',3,2,'u3','','g3_2_sci_u3_review_c','unit_review','SC3-2-u3-C1',1,'ox','auto','솔빛반 일기 ①처럼 같은 페트병으로도 서로 다른 소리를 낼 수 있어요.',ARRAY['SC3-2-u3-X01']::text[],false,'{"seq":1,"concept":"SC3-2-u3-C1","difficulty":1,"kind":"ox","stem":"솔빛반 일기 ①처럼 같은 페트병으로도 서로 다른 소리를 낼 수 있어요.","answer":"O","reason_options":[{"t":"흔들거나 문지르는 것처럼 방법을 바꾸면 다른 소리가 나기 때문에","correct":true},{"t":"한 물체는 한 가지 소리만 내기 때문에","mis":"SC3-2-u3-X01"}],"mis":"SC3-2-u3-X01","explanation":["두 줄을 견줘요.","방법이 달라요.","그래서 O예요."],"asset":{"type":"passage","lines":["쌀을 넣은 페트병을 흔들었더니 빗소리처럼 들렸다.","같은 페트병을 연필 옆면으로 문질렀더니 다른 소리가 났다.","약속 — 가위·유리컵은 쓰지 않고, 소리를 너무 크게 내지 않기"],"title":"솔빛반 일기 ① 소리 내기 놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_c#2','sci',3,2,'u3','','g3_2_sci_u3_review_c','unit_review','SC3-2-u3-C4',1,'ox','auto','솔빛반 일기 ②에서 소리굽쇠를 손으로 꽉 잡으니 소리가 멈췄어요.',ARRAY['SC3-2-u3-X09']::text[],false,'{"seq":2,"concept":"SC3-2-u3-C4","difficulty":1,"kind":"ox","stem":"솔빛반 일기 ②에서 소리굽쇠를 손으로 꽉 잡으니 소리가 멈췄어요.","answer":"O","reason_options":[{"t":"떨림을 멈추면 소리도 멈추기 때문에","correct":true},{"t":"손이 소리를 빨아들이기 때문에","mis":"SC3-2-u3-X09"}],"mis":"SC3-2-u3-X09","explanation":["셋째 줄을 읽어요.","떨림이 멈췄어요.","그래서 O예요."],"asset":{"type":"passage","lines":["친 소리굽쇠를 물 표면에 대니 물이 튀어 올랐다.","목에 손을 대고 「아.」 하고 소리를 내니 떨림이 느껴졌다.","소리 나는 소리굽쇠를 손으로 꽉 잡으니 소리가 멈췄다."],"title":"솔빛반 일기 ② 소리굽쇠 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_c#3','sci',3,2,'u3','','g3_2_sci_u3_review_c','unit_review','SC3-2-u3-C6',1,'ox','auto','솔빛반 일기 ③의 ㉯는 북면이 작게 떨려 작은 소리가 났어요.',ARRAY['SC3-2-u3-X14']::text[],false,'{"seq":3,"concept":"SC3-2-u3-C6","difficulty":1,"kind":"ox","stem":"솔빛반 일기 ③의 ㉯는 북면이 작게 떨려 작은 소리가 났어요.","answer":"O","reason_options":[{"t":"약하게 치면 북면이 작게 떨리기 때문에","correct":true},{"t":"약하게 치면 북면이 떨리지 않기 때문에","mis":"SC3-2-u3-X14"}],"mis":"SC3-2-u3-X14","explanation":["㉯를 읽어요.","약하게 쳤어요.","그래서 O예요."],"asset":{"type":"passage","lines":["㉮ 세게 친 작은북 — 퐁퐁이가 높게 튀어 올랐다.","㉯ 약하게 친 작은북 — 퐁퐁이가 낮게 튀어 올랐다.","디지털 탐구 도구로 두 소리의 크고 작은 정도를 견주었다."],"title":"솔빛반 일기 ③ 작은북 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_c#4','sci',3,2,'u3','','g3_2_sci_u3_review_c','unit_review','SC3-2-u3-C8',1,'ox','auto','솔빛반 일기 ④에서 팬 플루트의 긴 관을 불면 높은 소리가 나요.',ARRAY['SC3-2-u3-X19']::text[],false,'{"seq":4,"concept":"SC3-2-u3-C8","difficulty":1,"kind":"ox","stem":"솔빛반 일기 ④에서 팬 플루트의 긴 관을 불면 높은 소리가 나요.","answer":"X","reason_options":[{"t":"긴 관을 불면 낮은 소리가 나기 때문에","correct":true},{"t":"관이 길수록 높은 소리가 나기 때문에","mis":"SC3-2-u3-X19"}],"mis":"SC3-2-u3-X19","explanation":["긴 관이에요.","길면 낮아요.","그래서 X예요."],"asset":{"type":"passage","lines":["칼림바 — 길이가 서로 다른 음판을 하나씩 튕겼다.","팬 플루트 — 짧은 관과 긴 관을 차례로 불었다.","같은 음판을 세게도 쳐 보고 약하게도 쳐 보았다."],"title":"솔빛반 일기 ④ 칼림바와 팬 플루트"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_c#5','sci',3,2,'u3','','g3_2_sci_u3_review_c','unit_review','SC3-2-u3-C11',1,'ox','auto','솔빛반 일기 ⑤의 선생님 말씀처럼 우주에서는 목소리를 들을 수 없어요.',ARRAY['SC3-2-u3-X26']::text[],false,'{"seq":5,"concept":"SC3-2-u3-C11","difficulty":1,"kind":"ox","stem":"솔빛반 일기 ⑤의 선생님 말씀처럼 우주에서는 목소리를 들을 수 없어요.","answer":"O","reason_options":[{"t":"우주에는 소리를 전달할 물질이 없기 때문에","correct":true},{"t":"우주는 너무 깜깜하기 때문에","mis":"SC3-2-u3-X26"}],"mis":"SC3-2-u3-X26","explanation":["우주에는 공기가 없어요.","전달할 물질이 없어요.","그래서 O예요."],"asset":{"type":"passage","lines":["㉠ 책상 끝에 귀를 대고 두드리는 소리를 셌다.","㉡ 수조 속 방수 스피커 소리를 관으로 들었다.","㉢ 실 전화기로 친구 목소리를 들었다.","선생님 — 「우주에서는 목소리를 들을 수 없어요.」"],"title":"솔빛반 일기 ⑤ 소리 전달 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_c#6','sci',3,2,'u3','','g3_2_sci_u3_review_c','unit_review','SC3-2-u3-C12',1,'ox','auto','솔빛반 일기 ⑥처럼 같은 빗소리도 사람마다 다르게 느낄 수 있어요.',ARRAY['SC3-2-u3-X29']::text[],false,'{"seq":6,"concept":"SC3-2-u3-C12","difficulty":1,"kind":"ox","stem":"솔빛반 일기 ⑥처럼 같은 빗소리도 사람마다 다르게 느낄 수 있어요.","answer":"O","reason_options":[{"t":"누군가에게 좋은 소리가 다른 사람에게는 소음일 수 있기 때문에","correct":true},{"t":"빗소리는 누구에게나 똑같이 들리기 때문에","mis":"SC3-2-u3-X29"}],"mis":"SC3-2-u3-X29","explanation":["두 친구 말을 견줘요.","느낌이 달라요.","그래서 O예요."],"asset":{"type":"passage","lines":["도서관 옆 공사장 소리가 너무 커서 책 읽기 어려웠다.","친구 가 — 「나는 빗소리가 좋아.」","친구 나 — 「나는 빗소리가 시끄러워.」","반 의견 — 공사장 주위에 방음벽을 세우면 좋겠다."],"title":"솔빛반 일기 ⑥ 소음 조사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_c#7','sci',3,2,'u3','','g3_2_sci_u3_review_c','unit_review','SC3-2-u3-C14',1,'ox','auto','우리 집에서 내는 큰 소리가 이웃에게는 소음이 될 수 있어요.',ARRAY['SC3-2-u3-X34']::text[],false,'{"seq":7,"concept":"SC3-2-u3-C14","difficulty":1,"kind":"ox","stem":"우리 집에서 내는 큰 소리가 이웃에게는 소음이 될 수 있어요.","answer":"O","reason_options":[{"t":"이웃이 쉬거나 잘 때 불편을 줄 수 있기 때문에","correct":true},{"t":"소리는 우리 집 밖으로 나가지 않기 때문에","mis":"SC3-2-u3-X34"}],"mis":"SC3-2-u3-X34","explanation":["이웃을 떠올려요.","위층·아래층이 있어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_c#8','sci',3,2,'u3','','g3_2_sci_u3_review_c','unit_review','SC3-2-u3-C17',1,'ox','auto','솔빛반 일기 ⑧처럼 인공지능 음향 카메라는 섞인 소리 속에서도 고장 난 곳을 빨리 찾게 도와요.',ARRAY['SC3-2-u3-X38']::text[],false,'{"seq":8,"concept":"SC3-2-u3-C17","difficulty":1,"kind":"ox","stem":"솔빛반 일기 ⑧처럼 인공지능 음향 카메라는 섞인 소리 속에서도 고장 난 곳을 빨리 찾게 도와요.","answer":"O","reason_options":[{"t":"소리마다 세기와 높낮이를 구별하기 때문에","correct":true},{"t":"고장 난 곳을 저절로 고치기 때문에","mis":"SC3-2-u3-X38"}],"mis":"SC3-2-u3-X38","explanation":["둘째 줄을 읽어요.","구별해요.","그래서 O예요."],"asset":{"type":"passage","lines":["화면 속 자동차 앞부분이 빨갛게 빛났다.","여러 소리가 섞여 있었지만 고장 난 곳을 빨리 찾았다.","더 생각 — 무인 비행기에 달면 조난자를 찾을 수 있을 것 같다."],"title":"솔빛반 일기 ⑧ 음향 카메라 영상"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_c#9','sci',3,2,'u3','','g3_2_sci_u3_review_c','unit_review','SC3-2-u3-C2',2,'mc','auto','칸막이 뒤 친구의 소리를 듣고 짐작할 때 알맞은 태도는 무엇인가요?',ARRAY['SC3-2-u3-X04']::text[],false,'{"seq":9,"concept":"SC3-2-u3-C2","difficulty":2,"kind":"mc","stem":"칸막이 뒤 친구의 소리를 듣고 짐작할 때 알맞은 태도는 무엇인가요?","options":[{"t":"끝까지 조용히 듣고 물체와 방법을 함께 말한다","correct":true},{"t":"들리자마자 큰 소리로 외친다","mis":"SC3-2-u3-X04"},{"t":"귀를 막고 기다린다","mis":"SC3-2-u3-X04"},{"t":"물체 이름만 빨리 외친다","mis":"SC3-2-u3-X04"}],"explanation":["잘 들어요.","끝까지 들어요.","물체와 방법을 함께 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_c#10','sci',3,2,'u3','','g3_2_sci_u3_review_c','unit_review','SC3-2-u3-C4',2,'mc','auto','노래가 나오는 스피커 막을 손으로 눌러 떨림을 멈추게 하면 어떻게 될까요?',ARRAY['SC3-2-u3-X09']::text[],false,'{"seq":10,"concept":"SC3-2-u3-C4","difficulty":2,"kind":"mc","stem":"노래가 나오는 스피커 막을 손으로 눌러 떨림을 멈추게 하면 어떻게 될까요?","options":[{"t":"소리도 멈춘다","correct":true},{"t":"소리가 더 커진다","mis":"SC3-2-u3-X09"},{"t":"소리는 그대로 난다","mis":"SC3-2-u3-X09"},{"t":"스피커 막이 더 크게 떨린다","mis":"SC3-2-u3-X09"}],"explanation":["떨림이 멈춰요.","소리는 떨림이 있어야 나요.","소리도 멈춰요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_c#11','sci',3,2,'u3','','g3_2_sci_u3_review_c','unit_review','SC3-2-u3-C6',2,'mc','auto','솔빛반 일기 ③의 디지털 탐구 도구로 알 수 있는 것은 무엇인가요?',ARRAY['SC3-2-u3-X11']::text[],false,'{"seq":11,"concept":"SC3-2-u3-C6","difficulty":2,"kind":"mc","stem":"솔빛반 일기 ③의 디지털 탐구 도구로 알 수 있는 것은 무엇인가요?","options":[{"t":"소리의 크고 작은 정도","correct":true},{"t":"북의 무게","mis":"SC3-2-u3-X11"},{"t":"북의 색깔","mis":"SC3-2-u3-X11"},{"t":"북을 친 사람의 이름","mis":"SC3-2-u3-X11"}],"explanation":["셋째 줄을 읽어요.","크고 작은 정도예요.","소리의 크고 작은 정도예요."],"asset":{"type":"passage","lines":["㉮ 세게 친 작은북 — 퐁퐁이가 높게 튀어 올랐다.","㉯ 약하게 친 작은북 — 퐁퐁이가 낮게 튀어 올랐다.","디지털 탐구 도구로 두 소리의 크고 작은 정도를 견주었다."],"title":"솔빛반 일기 ③ 작은북 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_c#12','sci',3,2,'u3','','g3_2_sci_u3_review_c','unit_review','SC3-2-u3-C9',2,'mc','auto','더 짧은 음판을 쳤을 때 달라진 것은 무엇인가요?',ARRAY['SC3-2-u3-X22','SC3-2-u3-X17']::text[],false,'{"seq":12,"concept":"SC3-2-u3-C9","difficulty":2,"kind":"mc","stem":"더 짧은 음판을 쳤을 때 달라진 것은 무엇인가요?","options":[{"t":"소리의 높낮이","correct":true},{"t":"소리의 세기","mis":"SC3-2-u3-X22"},{"t":"음판의 색깔","mis":"SC3-2-u3-X17"},{"t":"떨림이 없어짐","mis":"SC3-2-u3-X17"}],"explanation":["길이가 달라졌어요.","높낮이예요.","소리의 높낮이예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_c#13','sci',3,2,'u3','','g3_2_sci_u3_review_c','unit_review','SC3-2-u3-C10',2,'mc','auto','소리가 나는 곳에서 떨어져 있어도 휴대 전화 소리를 들을 수 있는 까닭은 무엇인가요?',ARRAY['SC3-2-u3-X26','SC3-2-u3-X23']::text[],false,'{"seq":13,"concept":"SC3-2-u3-C10","difficulty":2,"kind":"mc","stem":"소리가 나는 곳에서 떨어져 있어도 휴대 전화 소리를 들을 수 있는 까닭은 무엇인가요?","options":[{"t":"소리가 공기를 통해 전달되기 때문에","correct":true},{"t":"소리가 물질 없이 날아오기 때문에","mis":"SC3-2-u3-X26"},{"t":"휴대 전화가 떨리는 것이 보이기 때문에","mis":"SC3-2-u3-X23"},{"t":"소리는 책상을 통해서만 오기 때문에","mis":"SC3-2-u3-X23"}],"explanation":["떨어져 있어요.","공기가 있어요.","공기를 통해 전달돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_c#14','sci',3,2,'u3','','g3_2_sci_u3_review_c','unit_review','SC3-2-u3-C12',2,'mc','auto','솔빛반 일기 ⑥의 두 친구 말로 알 수 있는 것은 무엇인가요?',ARRAY['SC3-2-u3-X29','SC3-2-u3-X28']::text[],false,'{"seq":14,"concept":"SC3-2-u3-C12","difficulty":2,"kind":"mc","stem":"솔빛반 일기 ⑥의 두 친구 말로 알 수 있는 것은 무엇인가요?","options":[{"t":"같은 소리도 사람마다 소음인지 아닌지 다르게 느낀다","correct":true},{"t":"빗소리는 누구에게나 소음이다","mis":"SC3-2-u3-X29"},{"t":"빗소리는 누구에게나 좋은 소리다","mis":"SC3-2-u3-X29"},{"t":"소리는 모두 없애야 한다","mis":"SC3-2-u3-X28"}],"explanation":["두 친구를 견줘요.","느낌이 달라요.","사람마다 달라요."],"asset":{"type":"passage","lines":["도서관 옆 공사장 소리가 너무 커서 책 읽기 어려웠다.","친구 가 — 「나는 빗소리가 좋아.」","친구 나 — 「나는 빗소리가 시끄러워.」","반 의견 — 공사장 주위에 방음벽을 세우면 좋겠다."],"title":"솔빛반 일기 ⑥ 소음 조사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_c#15','sci',3,2,'u3','','g3_2_sci_u3_review_c','unit_review','SC3-2-u3-C14',2,'mc','auto','솔빛반 일기 ⑦의 방법 가운데 소리의 세기를 줄이는 방법은 무엇인가요?',ARRAY['SC3-2-u3-X31','SC3-2-u3-X35']::text[],false,'{"seq":15,"concept":"SC3-2-u3-C14","difficulty":2,"kind":"mc","stem":"솔빛반 일기 ⑦의 방법 가운데 소리의 세기를 줄이는 방법은 무엇인가요?","options":[{"t":"텔레비전 소리 줄이기","correct":true},{"t":"집 안에서 실내화 신기","mis":"SC3-2-u3-X31"},{"t":"실천표에 매일 기록하기","mis":"SC3-2-u3-X35"},{"t":"둘 다 아니다","mis":"SC3-2-u3-X31"}],"explanation":["작게 하는 것을 찾아요.","실내화는 막아요.","텔레비전 소리 줄이기예요."],"asset":{"type":"passage","lines":["방법 — 집 안에서 실내화 신기, 텔레비전 소리 줄이기","실천표 — 일주일 동안 매일 기록했다.","잘한 점 — 아래층에서 조용해졌다고 고마워했다.","보완할 점 — 주말에 기록을 빠뜨렸다."],"title":"솔빛반 일기 ⑦ 실천 소개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_c#16','sci',3,2,'u3','','g3_2_sci_u3_review_c','unit_review','SC3-2-u3-C16',2,'mc','auto','음향 카메라 화면에 나타나는 여러 가지 색깔은 무엇에 따라 달라지나요?',ARRAY['SC3-2-u3-X37']::text[],false,'{"seq":16,"concept":"SC3-2-u3-C16","difficulty":2,"kind":"mc","stem":"음향 카메라 화면에 나타나는 여러 가지 색깔은 무엇에 따라 달라지나요?","options":[{"t":"소리의 세기나 높낮이","correct":true},{"t":"카메라를 든 사람의 키","mis":"SC3-2-u3-X37"},{"t":"그날의 날씨","mis":"SC3-2-u3-X37"},{"t":"카메라의 무게","mis":"SC3-2-u3-X37"}],"explanation":["소리의 성질이에요.","두 가지예요.","세기나 높낮이예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_c#17','sci',3,2,'u3','','g3_2_sci_u3_review_c','unit_review','SC3-2-u3-C4',3,'mc','auto','솔빛반 일기 ②의 관찰을 감각에 따라 바르게 나눈 것은 무엇인가요?',ARRAY['SC3-2-u3-X08']::text[],false,'{"seq":17,"concept":"SC3-2-u3-C4","difficulty":3,"kind":"mc","stem":"솔빛반 일기 ②의 관찰을 감각에 따라 바르게 나눈 것은 무엇인가요?","options":[{"t":"물이 튀어 오름 — 눈 · 목의 떨림 — 손","correct":true},{"t":"물이 튀어 오름 — 손 · 목의 떨림 — 눈","mis":"SC3-2-u3-X08"},{"t":"물이 튀어 오름 — 귀 · 목의 떨림 — 귀","mis":"SC3-2-u3-X08"},{"t":"두 가지 모두 감각으로 알 수 없다","mis":"SC3-2-u3-X08"}],"explanation":["본 것과 느낀 것이에요.","튀어 오름은 봐요.","물-눈, 목-손이에요."],"asset":{"type":"passage","lines":["친 소리굽쇠를 물 표면에 대니 물이 튀어 올랐다.","목에 손을 대고 「아.」 하고 소리를 내니 떨림이 느껴졌다.","소리 나는 소리굽쇠를 손으로 꽉 잡으니 소리가 멈췄다."],"title":"솔빛반 일기 ② 소리굽쇠 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_c#18','sci',3,2,'u3','','g3_2_sci_u3_review_c','unit_review','SC3-2-u3-C6',3,'mc','auto','심벌즈를 세게 쳤다가 약하게 쳤어요. 소리와 떨림은 어떻게 바뀌나요?',ARRAY['SC3-2-u3-X13','SC3-2-u3-X14']::text[],false,'{"seq":18,"concept":"SC3-2-u3-C6","difficulty":3,"kind":"mc","stem":"심벌즈를 세게 쳤다가 약하게 쳤어요. 소리와 떨림은 어떻게 바뀌나요?","options":[{"t":"크게 떨리며 큰 소리에서 작게 떨리며 작은 소리로 바뀐다","correct":true},{"t":"작게 떨리며 큰 소리에서 크게 떨리며 작은 소리로 바뀐다","mis":"SC3-2-u3-X13"},{"t":"떨림은 그대로이고 소리만 작아진다","mis":"SC3-2-u3-X13"},{"t":"약하게 칠 때는 떨리지 않고 소리만 난다","mis":"SC3-2-u3-X14"}],"explanation":["세게 → 약하게예요.","떨림도 작아져요.","큰 소리에서 작은 소리로요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_c#19','sci',3,2,'u3','','g3_2_sci_u3_review_c','unit_review','SC3-2-u3-C8',3,'mc','auto','기타 줄을 짧게 잡고 튕겼다가 길게 잡고 튕겼어요. 소리는 어떻게 바뀌나요?',ARRAY['SC3-2-u3-X19','SC3-2-u3-X22','SC3-2-u3-X18']::text[],false,'{"seq":19,"concept":"SC3-2-u3-C8","difficulty":3,"kind":"mc","stem":"기타 줄을 짧게 잡고 튕겼다가 길게 잡고 튕겼어요. 소리는 어떻게 바뀌나요?","options":[{"t":"높은 소리에서 낮은 소리로 바뀐다","correct":true},{"t":"낮은 소리에서 높은 소리로 바뀐다","mis":"SC3-2-u3-X19"},{"t":"큰 소리에서 작은 소리로만 바뀐다","mis":"SC3-2-u3-X22"},{"t":"소리가 바뀌지 않는다","mis":"SC3-2-u3-X18"}],"explanation":["짧게 → 길게예요.","길면 낮아요.","높은 소리에서 낮은 소리로요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_c#20','sci',3,2,'u3','','g3_2_sci_u3_review_c','unit_review','SC3-2-u3-C10',3,'mc','auto','책상에 귀를 대고 친구가 두드린 횟수를 맞히려고 해요. 가장 알맞은 방법은 무엇인가요?',ARRAY['SC3-2-u3-X24','SC3-2-u3-X23']::text[],false,'{"seq":20,"concept":"SC3-2-u3-C10","difficulty":3,"kind":"mc","stem":"책상에 귀를 대고 친구가 두드린 횟수를 맞히려고 해요. 가장 알맞은 방법은 무엇인가요?","options":[{"t":"책상에 한쪽 귀를 대고 반대쪽 귀는 손으로 막는다","correct":true},{"t":"양쪽 귀를 모두 열어 둔다","mis":"SC3-2-u3-X24"},{"t":"귀를 책상에서 멀리 뗀다","mis":"SC3-2-u3-X24"},{"t":"친구에게 책상 대신 크게 소리쳐 달라고 한다","mis":"SC3-2-u3-X23"}],"explanation":["책상으로 오는 소리예요.","공기로 오는 소리는 막아요.","반대쪽 귀를 막아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_c#21','sci',3,2,'u3','','g3_2_sci_u3_review_c','unit_review','SC3-2-u3-C12',3,'mc','auto','소음에 대해 바르게 말한 것은 무엇인가요?',ARRAY['SC3-2-u3-X27','SC3-2-u3-X28','SC3-2-u3-X29']::text[],false,'{"seq":21,"concept":"SC3-2-u3-C12","difficulty":3,"kind":"mc","stem":"소음에 대해 바르게 말한 것은 무엇인가요?","options":[{"t":"불쾌감이나 고통을 주는 소리이고, 사람마다 다르게 느낄 수 있다","correct":true},{"t":"큰 소리는 모두 소음이다","mis":"SC3-2-u3-X27"},{"t":"소리는 모두 소음이니 없애야 한다","mis":"SC3-2-u3-X28"},{"t":"같은 소리는 누구에게나 똑같은 소음이다","mis":"SC3-2-u3-X29"}],"explanation":["뜻을 떠올려요.","사람마다 달라요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_c#22','sci',3,2,'u3','','g3_2_sci_u3_review_c','unit_review','SC3-2-u3-C17',3,'mc','auto','솔빛반 일기 ⑧의 「더 생각」처럼 음향 카메라를 무인 비행기에 달면 좋은 까닭은 무엇인가요?',ARRAY['SC3-2-u3-X36','SC3-2-u3-X38']::text[],false,'{"seq":22,"concept":"SC3-2-u3-C17","difficulty":3,"kind":"mc","stem":"솔빛반 일기 ⑧의 「더 생각」처럼 음향 카메라를 무인 비행기에 달면 좋은 까닭은 무엇인가요?","options":[{"t":"조난자가 내는 소리가 나는 곳을 화면에서 찾을 수 있어서","correct":true},{"t":"비행기 소리가 사라져서","mis":"SC3-2-u3-X36"},{"t":"조난자를 저절로 구해 줘서","mis":"SC3-2-u3-X38"},{"t":"날씨를 맑게 해 줘서","mis":"SC3-2-u3-X38"}],"explanation":["조난자가 소리를 내요.","화면에서 찾아요.","소리 나는 곳을 찾아요."],"asset":{"type":"passage","lines":["화면 속 자동차 앞부분이 빨갛게 빛났다.","여러 소리가 섞여 있었지만 고장 난 곳을 빨리 찾았다.","더 생각 — 무인 비행기에 달면 조난자를 찾을 수 있을 것 같다."],"title":"솔빛반 일기 ⑧ 음향 카메라 영상"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_c#23','sci',3,2,'u3','','g3_2_sci_u3_review_c','unit_review','SC3-2-u3-C8',4,'essay','teacher','솔빛반 일기 ④를 보고 칼림바나 팬 플루트로 높은 소리와 낮은 소리를 내는 방법을 쓰고, 같은 음판을 세게 칠 때 달라지는 것과 달라지지 않는 것을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"SC3-2-u3-C8","difficulty":4,"kind":"essay","stem":"솔빛반 일기 ④를 보고 칼림바나 팬 플루트로 높은 소리와 낮은 소리를 내는 방법을 쓰고, 같은 음판을 세게 칠 때 달라지는 것과 달라지지 않는 것을 쓰세요.","answer_guide":{"answer":"예: 칼림바는 짧은 음판을 튕기면 높은 소리, 긴 음판을 튕기면 낮은 소리가 난다. 팬 플루트도 짧은 관은 높은 소리, 긴 관은 낮은 소리가 난다. 같은 음판을 세게 치면 소리의 세기는 커지지만 높낮이는 달라지지 않는다.","scoring_points":["높은 소리 내는 방법을 썼는가","낮은 소리 내는 방법을 썼는가","세게 칠 때 세기만 달라짐을 썼는가"]},"explanation":["길이를 떠올려요.","높낮이를 써요.","세기와 나눠요."],"asset":{"type":"passage","lines":["칼림바 — 길이가 서로 다른 음판을 하나씩 튕겼다.","팬 플루트 — 짧은 관과 긴 관을 차례로 불었다.","같은 음판을 세게도 쳐 보고 약하게도 쳐 보았다."],"title":"솔빛반 일기 ④ 칼림바와 팬 플루트"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_c#24','sci',3,2,'u3','','g3_2_sci_u3_review_c','unit_review','SC3-2-u3-C13',4,'mc','auto','솔빛반 일기 ⑥과 ⑦을 함께 보고 소음 줄이기를 바르게 정리한 것은 무엇인가요?',ARRAY['SC3-2-u3-X31','SC3-2-u3-X30']::text[],false,'{"seq":24,"concept":"SC3-2-u3-C13","difficulty":4,"kind":"mc","stem":"솔빛반 일기 ⑥과 ⑦을 함께 보고 소음 줄이기를 바르게 정리한 것은 무엇인가요?","options":[{"t":"방음벽·실내화는 잘 전달되지 않게 하고, 텔레비전 소리 줄이기는 세기를 줄인다","correct":true},{"t":"방음벽·실내화·텔레비전 소리 줄이기 모두 세기를 줄인다","mis":"SC3-2-u3-X31"},{"t":"방음벽은 세기를 줄이고, 텔레비전 소리 줄이기는 잘 전달되지 않게 한다","mis":"SC3-2-u3-X31"},{"t":"세 가지 모두 소음을 줄이는 방법이 아니다","mis":"SC3-2-u3-X30"}],"explanation":["세 가지를 나눠요.","막는 것과 작게 하는 것이에요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_c#25','sci',3,2,'u3','','g3_2_sci_u3_review_c','unit_review','SC3-2-u3-C16',4,'essay','teacher','솔빛반 일기 ⑧을 보고 음향 카메라로 고장 난 곳을 빨리 찾을 수 있었던 까닭을 쓰고, 음향 카메라를 쓸 수 있는 다른 곳을 한 가지 생각해 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC3-2-u3-C16","difficulty":4,"kind":"essay","stem":"솔빛반 일기 ⑧을 보고 음향 카메라로 고장 난 곳을 빨리 찾을 수 있었던 까닭을 쓰고, 음향 카메라를 쓸 수 있는 다른 곳을 한 가지 생각해 쓰세요.","answer_guide":{"answer":"예: 음향 카메라는 소리가 나는 곳을 화면에 색깔로 나타내고, 인공지능으로 섞인 소리 속에서도 소리마다 세기와 높낮이를 구별해 고장 난 곳을 빨리 찾을 수 있었다. 무인 비행기에 달아 재난 때 조난자의 위치를 찾는 데 쓸 수 있다.","scoring_points":["색깔로 나타낸다고 썼는가","섞인 소리를 구별한다고 썼는가","쓸 수 있는 다른 곳을 썼는가"]},"explanation":["일기를 읽어요.","까닭을 써요.","쓸 곳을 생각해요."],"asset":{"type":"passage","lines":["화면 속 자동차 앞부분이 빨갛게 빛났다.","여러 소리가 섞여 있었지만 고장 난 곳을 빨리 찾았다.","더 생각 — 무인 비행기에 달면 조난자를 찾을 수 있을 것 같다."],"title":"솔빛반 일기 ⑧ 음향 카메라 영상"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_d#1','sci',3,2,'u3','','g3_2_sci_u3_review_d','unit_review','SC3-2-u3-C2',1,'mc','auto','소리 내기 놀이에서 가장 중요한 것은 무엇인가요?',ARRAY['SC3-2-u3-X04','SC3-2-u3-X03']::text[],false,'{"seq":1,"concept":"SC3-2-u3-C2","difficulty":1,"kind":"mc","stem":"소리 내기 놀이에서 가장 중요한 것은 무엇인가요?","options":[{"t":"소리를 내고 듣는 과정","correct":true},{"t":"많이 맞히기","mis":"SC3-2-u3-X04"},{"t":"가장 크게 소리 내기","mis":"SC3-2-u3-X03"},{"t":"먼저 외치기","mis":"SC3-2-u3-X04"}],"explanation":["놀이의 목적이에요.","과정이 중요해요.","내고 듣는 과정이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_d#2','sci',3,2,'u3','','g3_2_sci_u3_review_d','unit_review','SC3-2-u3-C4',1,'mc','auto','기타 줄을 튕겨 소리가 날 때 떨리는 것은 무엇인가요?',ARRAY['SC3-2-u3-X10']::text[],false,'{"seq":2,"concept":"SC3-2-u3-C4","difficulty":1,"kind":"mc","stem":"기타 줄을 튕겨 소리가 날 때 떨리는 것은 무엇인가요?","options":[{"t":"기타 줄","correct":true},{"t":"기타를 든 사람의 발","mis":"SC3-2-u3-X10"},{"t":"기타 옆 책상","mis":"SC3-2-u3-X10"},{"t":"기타 가방","mis":"SC3-2-u3-X10"}],"explanation":["튕긴 곳을 봐요.","줄이 움직여요.","기타 줄이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_d#3','sci',3,2,'u3','','g3_2_sci_u3_review_d','unit_review','SC3-2-u3-C5',1,'mc','auto','큰 소리를 내야 하는 때는 언제인가요?',ARRAY['SC3-2-u3-X12']::text[],false,'{"seq":3,"concept":"SC3-2-u3-C5","difficulty":1,"kind":"mc","stem":"큰 소리를 내야 하는 때는 언제인가요?","options":[{"t":"멀리 있는 친구를 부를 때","correct":true},{"t":"친구에게 귓속말할 때","mis":"SC3-2-u3-X12"},{"t":"아기를 재울 때","mis":"SC3-2-u3-X12"},{"t":"도서관에서 책을 읽을 때","mis":"SC3-2-u3-X12"}],"explanation":["멀리까지 들려야 해요.","크게 불러요.","멀리 부를 때예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_d#4','sci',3,2,'u3','','g3_2_sci_u3_review_d','unit_review','SC3-2-u3-C7',1,'mc','auto','낮은 소리가 나는 경우는 무엇인가요?',ARRAY['SC3-2-u3-X18']::text[],false,'{"seq":4,"concept":"SC3-2-u3-C7","difficulty":1,"kind":"mc","stem":"낮은 소리가 나는 경우는 무엇인가요?","options":[{"t":"긴 음판을 두드릴 때","correct":true},{"t":"짧은 음판을 두드릴 때","mis":"SC3-2-u3-X18"},{"t":"짧은 관을 불 때","mis":"SC3-2-u3-X18"},{"t":"고무줄을 짧게 잡고 튕길 때","mis":"SC3-2-u3-X18"}],"explanation":["긴 것을 찾아요.","길면 낮아요.","긴 음판이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_d#5','sci',3,2,'u3','','g3_2_sci_u3_review_d','unit_review','SC3-2-u3-C10',1,'mc','auto','책상에 귀를 대고 두드리는 소리를 들을 때 반대쪽 귀는 어떻게 하나요?',ARRAY['SC3-2-u3-X24']::text[],false,'{"seq":5,"concept":"SC3-2-u3-C10","difficulty":1,"kind":"mc","stem":"책상에 귀를 대고 두드리는 소리를 들을 때 반대쪽 귀는 어떻게 하나요?","options":[{"t":"손으로 막는다","correct":true},{"t":"활짝 열어 둔다","mis":"SC3-2-u3-X24"},{"t":"책상에서 멀리 뗀다","mis":"SC3-2-u3-X24"},{"t":"크게 소리친다","mis":"SC3-2-u3-X24"}],"explanation":["책상으로 오는 소리만 들어요.","공기로 오는 소리를 막아요.","손으로 막아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_d#6','sci',3,2,'u3','','g3_2_sci_u3_review_d','unit_review','SC3-2-u3-C13',1,'mc','auto','텔레비전 소리를 작게 하는 것은 어떤 방법인가요?',ARRAY['SC3-2-u3-X31','SC3-2-u3-X30']::text[],false,'{"seq":6,"concept":"SC3-2-u3-C13","difficulty":1,"kind":"mc","stem":"텔레비전 소리를 작게 하는 것은 어떤 방법인가요?","options":[{"t":"소리의 세기를 줄이는 방법","correct":true},{"t":"소리가 잘 전달되지 않게 하는 방법","mis":"SC3-2-u3-X31"},{"t":"소리를 높게 하는 방법","mis":"SC3-2-u3-X30"},{"t":"소음을 늘리는 방법","mis":"SC3-2-u3-X30"}],"explanation":["작게 해요.","세기예요.","세기를 줄이는 방법이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_d#7','sci',3,2,'u3','','g3_2_sci_u3_review_d','unit_review','SC3-2-u3-C14',1,'mc','auto','실천할 소음 줄이기 방법으로 가장 알맞은 것은 무엇인가요?',ARRAY['SC3-2-u3-X33']::text[],false,'{"seq":7,"concept":"SC3-2-u3-C14","difficulty":1,"kind":"mc","stem":"실천할 소음 줄이기 방법으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"우리가 매일 할 수 있는 방법","correct":true},{"t":"돈이 많이 드는 방법","mis":"SC3-2-u3-X33"},{"t":"한 번도 해 보지 못할 방법","mis":"SC3-2-u3-X33"},{"t":"가장 어려운 방법","mis":"SC3-2-u3-X33"}],"explanation":["직접 해요.","매일 해야 해요.","할 수 있는 방법이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_d#8','sci',3,2,'u3','','g3_2_sci_u3_review_d','unit_review','SC3-2-u3-C17',1,'mc','auto','사람의 생각하는 능력 등을 컴퓨터 프로그램이 대신하게 만든 기술은 무엇인가요?',ARRAY['SC3-2-u3-X39']::text[],false,'{"seq":8,"concept":"SC3-2-u3-C17","difficulty":1,"kind":"mc","stem":"사람의 생각하는 능력 등을 컴퓨터 프로그램이 대신하게 만든 기술은 무엇인가요?","options":[{"t":"인공지능","correct":true},{"t":"확성기","mis":"SC3-2-u3-X39"},{"t":"소리굽쇠","mis":"SC3-2-u3-X39"},{"t":"방음벽","mis":"SC3-2-u3-X39"}],"explanation":["컴퓨터 프로그램이에요.","인공◯◯이에요.","인공지능이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_d#9','sci',3,2,'u3','','g3_2_sci_u3_review_d','unit_review','SC3-2-u3-C1',2,'ox','auto','나무판 하나로는 한 가지 소리만 낼 수 있어요.',ARRAY['SC3-2-u3-X01']::text[],false,'{"seq":9,"concept":"SC3-2-u3-C1","difficulty":2,"kind":"ox","stem":"나무판 하나로는 한 가지 소리만 낼 수 있어요.","answer":"X","reason_options":[{"t":"두드리거나 문지르는 등 방법을 바꾸면 다른 소리를 낼 수 있기 때문에","correct":true},{"t":"물체마다 소리가 하나씩 정해져 있기 때문에","mis":"SC3-2-u3-X01"}],"mis":"SC3-2-u3-X01","explanation":["방법을 바꿔 봐요.","다른 소리가 나요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_d#10','sci',3,2,'u3','','g3_2_sci_u3_review_d','unit_review','SC3-2-u3-C3',2,'ox','auto','솔빛반 일기 ②에서 물이 튀어 오른 것은 소리굽쇠가 떨리고 있었기 때문이에요.',ARRAY['SC3-2-u3-X07']::text[],false,'{"seq":10,"concept":"SC3-2-u3-C3","difficulty":2,"kind":"ox","stem":"솔빛반 일기 ②에서 물이 튀어 오른 것은 소리굽쇠가 떨리고 있었기 때문이에요.","answer":"O","reason_options":[{"t":"소리가 나는 소리굽쇠는 떨림이 있기 때문에","correct":true},{"t":"물이 원래 저절로 튀어 오르기 때문에","mis":"SC3-2-u3-X07"}],"mis":"SC3-2-u3-X07","explanation":["친 소리굽쇠예요.","떨리고 있었어요.","그래서 O예요."],"asset":{"type":"passage","lines":["친 소리굽쇠를 물 표면에 대니 물이 튀어 올랐다.","목에 손을 대고 「아.」 하고 소리를 내니 떨림이 느껴졌다.","소리 나는 소리굽쇠를 손으로 꽉 잡으니 소리가 멈췄다."],"title":"솔빛반 일기 ② 소리굽쇠 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_d#11','sci',3,2,'u3','','g3_2_sci_u3_review_d','unit_review','SC3-2-u3-C6',2,'ox','auto','퐁퐁이가 낮게 튀어 오른 것은 북을 세게 쳤기 때문이에요.',ARRAY['SC3-2-u3-X15']::text[],false,'{"seq":11,"concept":"SC3-2-u3-C6","difficulty":2,"kind":"ox","stem":"퐁퐁이가 낮게 튀어 오른 것은 북을 세게 쳤기 때문이에요.","answer":"X","reason_options":[{"t":"약하게 쳐서 북면이 작게 떨렸기 때문에","correct":true},{"t":"낮게 튈수록 큰 소리이기 때문에","mis":"SC3-2-u3-X15"}],"mis":"SC3-2-u3-X15","explanation":["낮게 튀었어요.","작게 떨렸어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_d#12','sci',3,2,'u3','','g3_2_sci_u3_review_d','unit_review','SC3-2-u3-C8',2,'ox','auto','고무줄 간이 악기로 높낮이를 견줄 때는 고무줄을 일정한 세기로 튕겨요.',ARRAY['SC3-2-u3-X20']::text[],false,'{"seq":12,"concept":"SC3-2-u3-C8","difficulty":2,"kind":"ox","stem":"고무줄 간이 악기로 높낮이를 견줄 때는 고무줄을 일정한 세기로 튕겨요.","answer":"O","reason_options":[{"t":"세기를 같게 해야 높낮이만 견줄 수 있기 때문에","correct":true},{"t":"세게 튕길수록 높은 소리가 나기 때문에","mis":"SC3-2-u3-X20"}],"mis":"SC3-2-u3-X20","explanation":["무엇을 견주나요?","높낮이만 견줘요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_d#13','sci',3,2,'u3','','g3_2_sci_u3_review_d','unit_review','SC3-2-u3-C10',2,'ox','auto','물속에서는 소리가 전달되지 않아요.',ARRAY['SC3-2-u3-X23']::text[],false,'{"seq":13,"concept":"SC3-2-u3-C10","difficulty":2,"kind":"ox","stem":"물속에서는 소리가 전달되지 않아요.","answer":"X","reason_options":[{"t":"물 같은 액체도 소리를 전달하기 때문에","correct":true},{"t":"소리는 공기로만 전달되기 때문에","mis":"SC3-2-u3-X23"}],"mis":"SC3-2-u3-X23","explanation":["물속 스피커를 떠올려요.","들렸어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_d#14','sci',3,2,'u3','','g3_2_sci_u3_review_d','unit_review','SC3-2-u3-C13',2,'ox','auto','창문을 활짝 열면 바깥 소음을 줄일 수 있어요.',ARRAY['SC3-2-u3-X30']::text[],false,'{"seq":14,"concept":"SC3-2-u3-C13","difficulty":2,"kind":"ox","stem":"창문을 활짝 열면 바깥 소음을 줄일 수 있어요.","answer":"X","reason_options":[{"t":"창문을 열면 바깥 소리가 더 잘 들어오기 때문에","correct":true},{"t":"창문을 열면 소리가 빠져나가 작아지기 때문에","mis":"SC3-2-u3-X30"}],"mis":"SC3-2-u3-X30","explanation":["창문을 열면?","바깥 소리가 들어와요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_d#15','sci',3,2,'u3','','g3_2_sci_u3_review_d','unit_review','SC3-2-u3-C15',2,'ox','auto','다른 모둠의 실천 소개를 들을 때는 잘한 점을 칭찬하고 보완할 점은 함께 이야기해요.',ARRAY['SC3-2-u3-X35']::text[],false,'{"seq":15,"concept":"SC3-2-u3-C15","difficulty":2,"kind":"ox","stem":"다른 모둠의 실천 소개를 들을 때는 잘한 점을 칭찬하고 보완할 점은 함께 이야기해요.","answer":"O","reason_options":[{"t":"서로 배우며 소음 문제를 함께 해결할 수 있기 때문에","correct":true},{"t":"다른 모둠의 잘못을 찾아 흉보는 것이 중요하기 때문에","mis":"SC3-2-u3-X35"}],"mis":"SC3-2-u3-X35","explanation":["함께 배워요.","칭찬부터 해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_d#16','sci',3,2,'u3','','g3_2_sci_u3_review_d','unit_review','SC3-2-u3-C17',2,'ox','auto','인공지능 음향 카메라는 여러 소리가 섞인 곳에서는 쓸 수 없어요.',ARRAY['SC3-2-u3-X38']::text[],false,'{"seq":16,"concept":"SC3-2-u3-C17","difficulty":2,"kind":"ox","stem":"인공지능 음향 카메라는 여러 소리가 섞인 곳에서는 쓸 수 없어요.","answer":"X","reason_options":[{"t":"섞인 소리 속에서도 소리마다 세기와 높낮이를 구별하기 때문에","correct":true},{"t":"소리가 하나일 때만 화면에 나타나기 때문에","mis":"SC3-2-u3-X38"}],"mis":"SC3-2-u3-X38","explanation":["섞인 소리예요.","구별할 수 있어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_d#17','sci',3,2,'u3','','g3_2_sci_u3_review_d','unit_review','SC3-2-u3-C3',3,'mc','auto','「떨림이 있는가?」로 나누었을 때 떨림이 있는 쪽에 들어가는 것끼리 묶은 것은 무엇인가요?',ARRAY['SC3-2-u3-X06']::text[],false,'{"seq":17,"concept":"SC3-2-u3-C3","difficulty":3,"kind":"mc","stem":"「떨림이 있는가?」로 나누었을 때 떨림이 있는 쪽에 들어가는 것끼리 묶은 것은 무엇인가요?","options":[{"t":"소리가 나는 기타 줄, 「아.」 하고 소리 내는 목","correct":true},{"t":"치지 않은 종, 소리가 나는 기타 줄","mis":"SC3-2-u3-X06"},{"t":"치기 전의 소리굽쇠, 치지 않은 종","mis":"SC3-2-u3-X06"},{"t":"치기 전의 소리굽쇠, 「아.」 하고 소리 내는 목","mis":"SC3-2-u3-X06"}],"explanation":["소리가 나는 것만요.","치지 않은 것은 빼요.","기타 줄과 목이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_d#18','sci',3,2,'u3','','g3_2_sci_u3_review_d','unit_review','SC3-2-u3-C5',3,'mc','auto','귓속말, 폭죽 소리, 응원 소리, 자장가를 「큰 소리가 나는 경우인가?」로 나눌 때 ✕ 쪽에 들어가는 것끼리 묶은 것은 무엇인가요?',ARRAY['SC3-2-u3-X12']::text[],false,'{"seq":18,"concept":"SC3-2-u3-C5","difficulty":3,"kind":"mc","stem":"귓속말, 폭죽 소리, 응원 소리, 자장가를 「큰 소리가 나는 경우인가?」로 나눌 때 ✕ 쪽에 들어가는 것끼리 묶은 것은 무엇인가요?","options":[{"t":"귓속말, 자장가","correct":true},{"t":"폭죽 소리, 응원 소리","mis":"SC3-2-u3-X12"},{"t":"귓속말, 응원 소리","mis":"SC3-2-u3-X12"},{"t":"폭죽 소리, 자장가","mis":"SC3-2-u3-X12"}],"explanation":["작은 소리를 찾아요.","귓속말과 자장가예요.","귓속말, 자장가예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_d#19','sci',3,2,'u3','','g3_2_sci_u3_review_d','unit_review','SC3-2-u3-C7',3,'mc','auto','높은 소리끼리만 묶은 것은 무엇인가요?',ARRAY['SC3-2-u3-X18']::text[],false,'{"seq":19,"concept":"SC3-2-u3-C7","difficulty":3,"kind":"mc","stem":"높은 소리끼리만 묶은 것은 무엇인가요?","options":[{"t":"짧은 음판 두드리기, 팬 플루트의 짧은 관 불기","correct":true},{"t":"긴 음판 두드리기, 짧은 관 불기","mis":"SC3-2-u3-X18"},{"t":"고무줄 길게 잡고 튕기기, 긴 관 불기","mis":"SC3-2-u3-X18"},{"t":"짧은 음판 두드리기, 긴 관 불기","mis":"SC3-2-u3-X18"}],"explanation":["짧은 것끼리예요.","긴 것은 빼요.","짧은 음판과 짧은 관이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_d#20','sci',3,2,'u3','','g3_2_sci_u3_review_d','unit_review','SC3-2-u3-C11',3,'mc','auto','소리를 전하는 물질이 아닌 것은 무엇인가요?',ARRAY['SC3-2-u3-X26']::text[],false,'{"seq":20,"concept":"SC3-2-u3-C11","difficulty":3,"kind":"mc","stem":"소리를 전하는 물질이 아닌 것은 무엇인가요?","options":[{"t":"물질이 없는 텅 빈 우주","correct":true},{"t":"나무","mis":"SC3-2-u3-X26"},{"t":"물","mis":"SC3-2-u3-X26"},{"t":"공기","mis":"SC3-2-u3-X26"}],"explanation":["물질을 찾아요.","텅 빈 곳은 물질이 없어요.","텅 빈 우주예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_d#21','sci',3,2,'u3','','g3_2_sci_u3_review_d','unit_review','SC3-2-u3-C14',3,'mc','auto','아파트에서 피아노를 치고 싶을 때 가장 알맞은 행동은 무엇인가요?',ARRAY['SC3-2-u3-X34','SC3-2-u3-X30']::text[],false,'{"seq":21,"concept":"SC3-2-u3-C14","difficulty":3,"kind":"mc","stem":"아파트에서 피아노를 치고 싶을 때 가장 알맞은 행동은 무엇인가요?","options":[{"t":"늦은 밤을 피하고 소리를 알맞게 하며 바닥에 매트를 깐다","correct":true},{"t":"내 집이니 밤에도 크게 친다","mis":"SC3-2-u3-X34"},{"t":"아래층에 시끄러워도 참으라고 말한다","mis":"SC3-2-u3-X34"},{"t":"창문을 활짝 열고 크게 친다","mis":"SC3-2-u3-X30"}],"explanation":["이웃을 떠올려요.","때와 방법을 생각해요.","밤을 피하고 매트를 깔아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_d#22','sci',3,2,'u3','','g3_2_sci_u3_review_d','unit_review','SC3-2-u3-C9',3,'mc','auto','음향 카메라 화면의 색깔을 바꾸는 소리의 성질과 그 성질을 정하는 것을 바르게 이은 것은 무엇인가요?',ARRAY['SC3-2-u3-X22','SC3-2-u3-X37']::text[],false,'{"seq":22,"concept":"SC3-2-u3-C9","difficulty":3,"kind":"mc","stem":"음향 카메라 화면의 색깔을 바꾸는 소리의 성질과 그 성질을 정하는 것을 바르게 이은 것은 무엇인가요?","options":[{"t":"세기 — 떨림의 크기 · 높낮이 — 물체의 길이","correct":true},{"t":"세기 — 물체의 길이 · 높낮이 — 떨림의 크기","mis":"SC3-2-u3-X22"},{"t":"세기 — 날씨 · 높낮이 — 카메라 색","mis":"SC3-2-u3-X37"},{"t":"세기 — 물체의 색 · 높낮이 — 물체의 무게","mis":"SC3-2-u3-X22"}],"explanation":["세기는 떨림이에요.","높낮이는 길이예요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_d#23','sci',3,2,'u3','','g3_2_sci_u3_review_d','unit_review','SC3-2-u3-C11',4,'essay','teacher','솔빛반 일기 ⑤의 ㉠~㉢에서 소리를 전달한 물질을 고체와 액체로 나누어 쓰고, 선생님 말씀의 까닭을 소리의 전달과 이어 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"SC3-2-u3-C11","difficulty":4,"kind":"essay","stem":"솔빛반 일기 ⑤의 ㉠~㉢에서 소리를 전달한 물질을 고체와 액체로 나누어 쓰고, 선생님 말씀의 까닭을 소리의 전달과 이어 쓰세요.","answer_guide":{"answer":"예: ㉠ 책상과 ㉢ 실은 고체, ㉡ 물은 액체를 통해 소리가 전달되었다. 소리는 여러 가지 물질을 통해 전달되는데, 우주에는 소리를 전달할 물질이 없어서 목소리를 들을 수 없다.","scoring_points":["고체를 통한 전달을 바르게 썼는가","액체를 통한 전달을 바르게 썼는가","우주에서 들을 수 없는 까닭을 썼는가"]},"explanation":["㉠~㉢을 봐요.","상태로 나눠요.","까닭을 써요."],"asset":{"type":"passage","lines":["㉠ 책상 끝에 귀를 대고 두드리는 소리를 셌다.","㉡ 수조 속 방수 스피커 소리를 관으로 들었다.","㉢ 실 전화기로 친구 목소리를 들었다.","선생님 — 「우주에서는 목소리를 들을 수 없어요.」"],"title":"솔빛반 일기 ⑤ 소리 전달 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_d#24','sci',3,2,'u3','','g3_2_sci_u3_review_d','unit_review','SC3-2-u3-C17',4,'mc','auto','음향 카메라를 소리의 성질을 이용한 첨단 기술이라고 할 수 있는 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['SC3-2-u3-X36','SC3-2-u3-X39','SC3-2-u3-X37']::text[],false,'{"seq":24,"concept":"SC3-2-u3-C17","difficulty":4,"kind":"mc","stem":"음향 카메라를 소리의 성질을 이용한 첨단 기술이라고 할 수 있는 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"소리의 세기와 높낮이를 색깔로 바꾸어 보여 주기 때문이다","correct":true},{"t":"소리를 크게 키우는 기계이기 때문이다","mis":"SC3-2-u3-X36"},{"t":"인공지능이 소리를 모두 없애 주기 때문이다","mis":"SC3-2-u3-X39"},{"t":"화면 색이 날씨를 알려 주기 때문이다","mis":"SC3-2-u3-X37"}],"explanation":["소리의 성질을 떠올려요.","색깔로 보여 줘요.","세기와 높낮이를 이용해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u3_review_d#25','sci',3,2,'u3','','g3_2_sci_u3_review_d','unit_review','SC3-2-u3-C5',4,'essay','teacher','「소리의 성질」 단원에서 배운 떨림, 소리의 세기, 소리의 높낮이, 소리의 전달 가운데 세 가지를 골라 각각 한 문장으로 설명하고, 생활 속 소음을 줄이려고 내가 할 수 있는 일을 한 가지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC3-2-u3-C5","difficulty":4,"kind":"essay","stem":"「소리의 성질」 단원에서 배운 떨림, 소리의 세기, 소리의 높낮이, 소리의 전달 가운데 세 가지를 골라 각각 한 문장으로 설명하고, 생활 속 소음을 줄이려고 내가 할 수 있는 일을 한 가지 쓰세요.","answer_guide":{"answer":"예: 소리가 나는 물체는 떨림이 있다. 물체가 크게 떨리면 큰 소리, 작게 떨리면 작은 소리가 난다. 소리는 고체, 액체, 기체 상태의 여러 가지 물질을 통해 전달된다. 나는 집 안에서 실내화를 신어 발소리가 아래층에 잘 전달되지 않게 하겠다.","scoring_points":["세 가지를 골랐는가","세 가지를 배운 내용에 맞게 설명했는가","소음을 줄이려고 할 수 있는 일을 썼는가"]},"explanation":["배운 것을 떠올려요.","세 가지를 골라요.","할 일을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
